INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('524bca7b-bc9f-5050-a20b-c8ebc9d03f09', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 24, 24, 'this is the interpretation, O king, and it is the decree of the Most High, which is come on my lord the king:'),
  ('2c2ff269-df06-5f96-ad89-b3851f1654e7', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 25, 25, 'that you shall be driven from men, and your dwelling shall be with the animals of the field, and you shall be made to eat grass as oxen, and shall be wet with the dew of the sky, and seven times shall pass over you; until you know that the Most High rules in the kingdom of men, and gives it to whomever he will.'),
  ('7d9e0bf7-9f9f-5551-a72e-329302187591', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 26, 26, 'Whereas they commanded to leave the stump of the roots of the tree; your kingdom shall be sure to you, after that you shall have known that the heavens do rule.'),
  ('6834bf78-2a70-56d8-a0a9-b28b282c8110', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 27, 27, 'Therefore, O king, let my counsel be acceptable to you, and break off your sins by righteousness, and your iniquities by showing mercy to the poor; if there may be a lengthening of your tranquility.'),
  ('7d58709b-62a5-5f27-ae50-5cf572959d2b', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 28, 28, 'All this came on the king Nebuchadnezzar.'),
  ('e89fc156-01fd-5d00-a1a1-aad697988cad', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 29, 29, 'At the end of twelve months he was walking in the royal palace of Babylon.'),
  ('361f2ee4-e890-50ff-aeec-ef6d49faf4ad', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 30, 30, 'The king spoke and said, Is not this great Babylon, which I have built for the royal dwelling place, by the might of my power and for the glory of my majesty?'),
  ('d8c71a7f-41f7-5595-a234-bfb7dda95e03', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 31, 31, 'While the word was in the king''s mouth, there fell a voice from the sky, [saying], O king Nebuchadnezzar, to you it is spoken: The kingdom has departed from you:'),
  ('b2d3efbc-1c59-5268-a4c8-91e0a6bae6f9', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 32, 32, 'and you shall be driven from men; and your dwelling shall be with the animals of the field; you shall be made to eat grass as oxen; and seven times shall pass over you; until you know that the Most High rules in the kingdom of men, and gives it to whomever he will.'),
  ('40fbf82a-8641-5d0f-a2de-f0e8de2edbca', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 33, 33, 'The same hour was the thing fulfilled on Nebuchadnezzar: and he was driven from men, and ate grass as oxen, and his body was wet with the dew of the sky, until his hair was grown like eagles'' [feathers], and his nails like birds'' [claws].'),
  ('7aa46b33-2a14-54a3-a939-4f823cc2ddbd', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 34, 34, 'At the end of the days I, Nebuchadnezzar, lifted up my eyes to heaven, and my understanding returned to me, and I blessed the Most High, and I praised and honored him who lives forever; for his dominion is an everlasting dominion, and his kingdom from generation to generation.'),
  ('588a9fa9-4ef1-54b1-a5d2-8eb0d9443e38', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 35, 35, 'All the inhabitants of the earth are reputed as nothing; and he does according to his will in the army of heaven, and among the inhabitants of the earth; and none can stay his hand, or ask him, What are you doing?'),
  ('2530c034-156a-557c-a266-6595c6203348', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 36, 36, 'At the same time my understanding returned to me; and for the glory of my kingdom, my majesty and brightness returned to me; and my counselors and my lords sought to me; and I was established in my kingdom, and excellent greatness was added to me.'),
  ('b7864c27-4c0f-5221-aae3-328fbbef0bae', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 37, 37, 'Now I, Nebuchadnezzar, praise and extol and honor the King of heaven; for all his works are truth, and his ways justice; and those who walk in pride he is able to abase.'),
  ('b1d3ca61-2fe0-597b-a5c8-de4e532df9b3', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 1, 1, 'Belshazzar the king made a great feast to a thousand of his lords, and drank wine before the thousand.'),
  ('67751297-87f0-512f-a2a3-a74b83be382f', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 2, 2, 'Belshazzar, while he tasted the wine, commanded to bring the golden and silver vessels which Nebuchadnezzar his father had taken out of the temple which was in Jerusalem; that the king and his lords, his wives and his concubines, might drink from them.'),
  ('3bb15e8d-7763-5a05-a2c3-870b16fa2063', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 3, 3, 'Then they brought the golden vessels that were taken out of the temple of the house of God which was at Jerusalem; and the king and his lords, his wives and his concubines, drank from them.'),
  ('bda74944-11df-5995-a6b7-76ad6674a927', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 4, 4, 'They drank wine, and praised the gods of gold, and of silver, of brass, of iron, of wood, and of stone.'),
  ('85547b8d-2584-5c35-aec9-08f20070b36a', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 5, 5, 'In the same hour came forth the fingers of a man''s hand, and wrote over against the lampstand on the plaster of the wall of the king''s palace: and the king saw the part of the hand that wrote.'),
  ('38cb3ff1-ff37-5a05-a3b4-c89b2f37bd2d', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 6, 6, 'Then the king''s face was changed in him, and his thoughts troubled him; and the joints of his thighs were loosened, and his knees struck one against another.'),
  ('f5c4526a-86b9-555a-a560-91454297424b', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 7, 7, 'The king cried aloud to bring in the enchanters, the Chaldeans, and the soothsayers. The king spoke and said to the wise men of Babylon, Whoever shall read this writing, and show me its interpretation, shall be clothed with purple, and have a chain of gold about his neck, and shall be the third ruler in the kingdom.'),
  ('1bc4a6ec-2aea-5082-a0ba-9c8f18b4b241', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 8, 8, 'Then came in all the king''s wise men; but they could not read the writing, nor make known to the king the interpretation.'),
  ('ded5739b-6111-5931-ae38-df27831764a7', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 9, 9, 'Then was king Belshazzar greatly troubled, and his face was changed in him, and his lords were perplexed.'),
  ('a10978c6-b860-5e1c-a6bb-a83337cedb0a', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 10, 10, '[Now] the queen by reason of the words of the king and his lords came into the banquet house: the queen spoke and said, O king, live forever; don''t let your thoughts trouble you, nor let your face be changed.'),
  ('e644e68d-9cab-5fd6-a5b7-e36a74e676f7', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 11, 11, 'There is a man in your kingdom, in whom is the spirit of the holy gods; and in the days of your father light and understanding and wisdom, like the wisdom of the gods, were found in him; and the king Nebuchadnezzar your father, the king, [I say], your father, made him master of the magicians, enchanters, Chaldeans, and soothsayers;'),
  ('a6f04d3a-4e24-50e0-a9c3-a5ff6fd5ac6d', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 12, 12, 'because an excellent spirit, and knowledge, and understanding, interpreting of dreams, and showing of dark sentences, and dissolving of doubts, were found in the same Daniel, whom the king named Belteshazzar. Now let Daniel be called, and he will show the interpretation.'),
  ('4a70a436-5c5a-5ecc-aaf4-aa63e88d7c90', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 13, 13, 'Then was Daniel brought in before the king. The king spoke and said to Daniel, Are you that Daniel, who are of the children of the captivity of Judah, whom the king my father brought out of Judah?'),
  ('8c67796f-8ea2-57b0-ad0a-4ff6b236ccbf', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 14, 14, 'I have heard of you, that the spirit of the gods is in you, and that light and understanding and excellent wisdom are found in you.'),
  ('2e3eeee4-0543-5244-ae5c-f40e5e731ad7', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 15, 15, 'Now the wise men, the enchanters, have been brought in before me, that they should read this writing, and make known to me its interpretation; but they could not show the interpretation of the thing.'),
  ('7a8aafec-a1b7-5aca-a302-030d7236635d', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 16, 16, 'But I have heard of you, that you can give interpretations, and dissolve doubts; now if you can read the writing, and make known to me its interpretation, you shall be clothed with purple, and have a chain of gold about your neck, and shall be the third ruler in the kingdom.'),
  ('dd1668f3-6d6f-548f-a816-88bb2c49c911', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 17, 17, 'Then Daniel answered before the king, Let your gifts be to yourself, and give your rewards to another; nevertheless I will read the writing to the king, and make known to him the interpretation.'),
  ('99715217-7276-50d1-a1cf-416116e72a56', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 18, 18, 'You, king, the Most High God gave Nebuchadnezzar your father the kingdom, and greatness, and glory, and majesty:'),
  ('7c398cac-5623-5951-a259-b7f31930d29a', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 19, 19, 'and because of the greatness that he gave him, all the peoples, nations, and languages trembled and feared before him: whom he would he killed, and whom he would he kept alive; and whom he would he raised up, and whom he would he put down.'),
  ('af084f67-af7e-58a1-a3f6-4de896b138ae', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 20, 20, 'But when his heart was lifted up, and his spirit was hardened so that he dealt proudly, he was deposed from his kingly throne, and they took his glory from him:'),
  ('6988e028-4ecc-5500-aed9-4102cc3ea9d5', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 21, 21, 'and he was driven from the sons of men, and his heart was made like the animals'', and his dwelling was with the wild donkeys; he was fed with grass like oxen, and his body was wet with the dew of the sky; until he knew that the Most High God rules in the kingdom of men, and that he sets up over it whomever he will.'),
  ('7fcd0ea5-99ec-54d7-a4f6-36cb89f46382', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 22, 22, 'You, his son, Belshazzar, have not humbled your heart, though you knew all this,'),
  ('7b4d3588-f17b-5c21-afab-90cceec5c243', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 23, 23, 'but have lifted up yourself against the Lord of heaven; and they have brought the vessels of his house before you, and you and your lords, your wives and your concubines, have drunk wine from them; and you have praised the gods of silver and gold, of brass, iron, wood, and stone, which don''t see, nor hear, nor know; and the God in whose hand your breath is, and whose are all your ways, you have not glorified.'),
  ('72a4f6fa-ead2-544f-a996-250b5a7587e9', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 24, 24, 'Then was the part of the hand sent from before him, and this writing was inscribed.'),
  ('81f168d8-0004-50fc-ac99-46634b0001af', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 25, 25, 'This is the writing that was inscribed: MENE, MENE, TEKEL, UPHARSIN.'),
  ('a49db899-364b-5826-aaf1-d8fb9f75189a', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 26, 26, 'This is the interpretation of the thing: MENE; God has numbered your kingdom, and brought it to an end;'),
  ('dee2beef-da61-5c62-a889-bb747c9a231a', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 27, 27, 'TEKEL; you are weighed in the balances, and are found wanting.'),
  ('3de2959b-097b-5e07-abac-295acf9f947f', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 28, 28, 'PERES; your kingdom is divided, and given to the Medes and Persians.'),
  ('d7b4801d-407d-5096-ab00-8907702aff71', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 29, 29, 'Then commanded Belshazzar, and they clothed Daniel with purple, and put a chain of gold about his neck, and made proclamation concerning him, that he should be the third ruler in the kingdom.'),
  ('d778012d-7b24-51f5-af7b-14089e76ccae', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 30, 30, 'In that night Belshazzar the Chaldean King was slain.'),
  ('e6c710d3-72c8-58dd-a075-7cef8cab3891', '5c4fe1aa-b7b3-5b84-a70c-ae22987139ae', NULL, 31, 31, 'Darius the Mede received the kingdom, being about sixty-two years old.'),
  ('9efa7074-29d6-58cf-a647-10719eec97a0', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 1, 1, 'It pleased Darius to set over the kingdom one hundred twenty satraps, who should be throughout the whole kingdom;'),
  ('071969bb-2040-5072-a38b-8e63d52d993e', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 2, 2, 'and over them three presidents, of whom Daniel was one; that these satraps might give account to them, and that the king should have no damage.'),
  ('5732083c-0514-53c0-a5eb-eb8493888f00', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 3, 3, 'Then this Daniel was distinguished above the presidents and the satraps, because an excellent spirit was in him; and the king thought to set him over the whole realm.'),
  ('56d1db88-0be9-555f-a763-c9c6957f3590', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 4, 4, 'Then the presidents and the satraps sought to find occasion against Daniel as touching the kingdom; but they could find no occasion nor fault, because he was faithful, neither was there any error or fault found in him.'),
  ('5166b3b4-8147-54d1-ac02-230918234680', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 5, 5, 'Then these men said, We shall not find any occasion against this Daniel, except we find it against him concerning the law of his God.'),
  ('30288674-319b-5c2c-a17b-9d8a38b5454d', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 6, 6, 'Then these presidents and satraps assembled together to the king, and said thus to him, King Darius, live forever.'),
  ('282dccac-0643-54cc-ae3f-ecc3b71c37e1', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 7, 7, 'All the presidents of the kingdom, the deputies and the satraps, the counselors and the governors, have consulted together to establish a royal statute, and to make a strong decree, that whoever shall ask a petition of any god or man for thirty days, except of you, O king, he shall be cast into the den of lions.'),
  ('a0e67e83-9413-5a14-a29a-3e7a1091badf', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 8, 8, 'Now, O king, establish the decree, and sign the writing, that it not be changed, according to the law of the Medes and Persians, which doesn''t alter.'),
  ('4d510ef9-7086-5603-a6c5-2441af8dfba8', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 9, 9, 'Therefore king Darius signed the writing and the decree.'),
  ('806e633b-2fb4-5c9d-a232-9dc40a52e201', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 10, 10, 'When Daniel knew that the writing was signed, he went into his house (now his windows were open in his room toward Jerusalem) and he kneeled on his knees three times a day, and prayed, and gave thanks before his God, as he did before.'),
  ('a49a4347-2fca-5004-a506-a9bc1e7816ea', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 11, 11, 'Then these men assembled together, and found Daniel making petition and supplication before his God.'),
  ('e3f1c06f-1ad4-594a-a499-92314667031c', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 12, 12, 'Then they came near, and spoke before the king concerning the king''s decree: Haven''t you signed an decree, that every man who shall make petition to any god or man within thirty days, except to you, O king, shall be cast into the den of lions? The king answered, The thing is true, according to the law of the Medes and Persians, which doesn''t alter.'),
  ('0d8169ce-ab3d-5d91-a46d-9fd1f0bb3361', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 13, 13, 'Then answered they and said before the king, That Daniel, who is of the children of the captivity of Judah, doesn''t respect you, O king, nor the decree that you have signed, but makes his petition three times a day.'),
  ('49ecb502-0ba0-53c7-a1bd-e8e561e835d9', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 14, 14, 'Then the king, when he heard these words, was very displeased, and set his heart on Daniel to deliver him; and he labored until the going down of the sun to rescue him.'),
  ('7ebac0bf-050d-545c-a7ac-0801f7443470', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 15, 15, 'Then these men assembled together to the king, and said to the king, Know, O king, that it is a law of the Medes and Persians, that no decree nor statute which the king establishes may be changed.'),
  ('ae951a94-e9d6-5535-a114-fa7ac6434cab', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 16, 16, 'Then the king commanded, and they brought Daniel, and cast him into the den of lions. [Now] the king spoke and said to Daniel, Your God whom you serve continually, he will deliver you.'),
  ('bcf36439-ec3b-5cea-adb6-31cdf8fc3830', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 17, 17, 'A stone was brought, and laid on the mouth of the den; and the king sealed it with his own signet, and with the signet of his lords; that nothing might be changed concerning Daniel.'),
  ('afe119b5-6418-5e4b-a211-774a61c37cb1', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 18, 18, 'Then the king went to his palace, and passed the night fasting; neither were instruments of music brought before him: and his sleep fled from him.'),
  ('0b5b084d-e508-592b-a6a5-388db05bcf5a', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 19, 19, 'Then the king arose very early in the morning, and went in haste to the den of lions.'),
  ('78005cc1-20e8-50c3-a659-9a486f3fa1e4', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 20, 20, 'When he came near to the den to Daniel, he cried with a lamentable voice; the king spoke and said to Daniel, Daniel, servant of the living God, is your God, whom you serve continually, able to deliver you from the lions?'),
  ('ef45f154-b8f8-5c10-aa95-70dd54ac3c18', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 21, 21, 'Then Daniel said to the king, O king, live forever.'),
  ('fe3368c4-ea31-5464-ae2d-eba566e56702', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 22, 22, 'My God has sent his angel, and has shut the lions'' mouths, and they have not hurt me; because as before him innocence was found in me; and also before you, O king, have I done no hurt.'),
  ('699e0574-24bd-5453-ab39-745902e98891', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 23, 23, 'Then was the king exceeding glad, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no kind of harm was found on him, because he had trusted in his God.'),
  ('b843c7e8-c008-5769-a8d0-7614a099c2cc', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 24, 24, 'The king commanded, and they brought those men who had accused Daniel, and they cast them into the den of lions, them, their children, and their wives; and the lions had the mastery of them, and broke all their bones in pieces, before they came to the bottom of the den.'),
  ('e916782c-7f61-520a-a6e3-5b63ac7d1558', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 25, 25, 'Then king Darius wrote to all the peoples, nations, and languages, who dwell in all the earth: Peace be multiplied to you.'),
  ('f9110dec-9322-5a9c-a757-867c4e72cafe', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 26, 26, 'I make a decree, that in all the dominion of my kingdom men tremble and fear before the God of Daniel; for he is the living God, and steadfast forever, His kingdom that which shall not be destroyed; and his dominion shall be even to the end.'),
  ('2ebe260d-7e78-5874-ae8c-6c55d90b46a4', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 27, 27, 'He delivers and rescues, and he works signs and wonders in heaven and in earth, who has delivered Daniel from the power of the lions.'),
  ('86243d52-e913-5800-adec-68adb22b3a08', 'aadce14e-a5b0-56e6-a8e7-70c2df5ee20f', NULL, 28, 28, 'So this Daniel prospered in the reign of Darius, and in the reign of Cyrus the Persian.'),
  ('a953989c-d5fe-5570-a31b-3af5418aaaf0', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 1, 1, 'In the first year of Belshazzar king of Babylon Daniel had a dream and visions of his head on his bed: then he wrote the dream and told the sum of the matters.'),
  ('8d43a32a-515a-5dda-afb7-9b836b2d8028', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 2, 2, 'Daniel spoke and said, I saw in my vision by night, and, behold, the four winds of the sky broke forth on the great sea.'),
  ('1896050b-10d2-5ce8-a4c1-bc61f9a29dc1', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 3, 3, 'Four great animals came up from the sea, diverse one from another.'),
  ('6513d085-96da-5e2e-a57f-3d9925ec1756', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 4, 4, 'The first was like a lion, and had eagle''s wings: I saw until its wings were plucked, and it was lifted up from the earth, and made to stand on two feet as a man; and a man''s heart was given to it.'),
  ('f323760c-91c3-5874-a044-2b90e8c24be6', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 5, 5, 'Behold, another animal, a second, like a bear; and it was raised up on one side, and three ribs were in its mouth between its teeth: and they said thus to it, Arise, devour much flesh.'),
  ('b5174403-ce5c-5012-a4a3-de2f18f59bf4', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 6, 6, 'After this I saw, and behold, another, like a leopard, which had on its back four wings of a bird; the animal had also four heads; and dominion was given to it.'),
  ('3b9fe0d3-4475-5af6-a13a-95351549a0a5', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 7, 7, 'After this I saw in the night visions, and, behold, a fourth animal, awesome and powerful, and strong exceedingly; and it had great iron teeth; it devoured and broke in pieces, and stamped the residue with its feet: and it was diverse from all the animals that were before it; and it had ten horns.'),
  ('690a9b05-e141-51b1-aaa0-7029025ef430', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 8, 8, 'I considered the horns, and behold, there came up among them another horn, a little one, before which three of the first horns were plucked up by the roots: and behold, in this horn were eyes like the eyes of a man, and a mouth speaking great things.'),
  ('09fa0be9-a5f5-558d-a19e-940f6d5b2d76', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 9, 9, 'I saw until thrones were placed, and one who was ancient of days sat: his clothing was white as snow, and the hair of his head like pure wool; his throne was fiery flames, [and] its wheels burning fire.'),
  ('67b2f72b-5a25-5365-a834-2e5ef528da06', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 10, 10, 'A fiery stream issued and came forth from before him: thousands of thousands ministered to him, and ten thousand times ten thousand stood before him: the judgment was set, and the books were opened.'),
  ('d3b50aee-a6a9-5231-ae60-f3c69ba3e822', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 11, 11, 'I saw at that time because of the voice of the great words which the horn spoke; I saw even until the animal was slain, and its body destroyed, and it was given to be burned with fire.'),
  ('794fb240-bec9-51fa-a067-c971364f4265', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 12, 12, 'As for the rest of the animals, their dominion was taken away: yet their lives were prolonged for a season and a time.'),
  ('3d746242-7e26-592b-ac63-d8161b660ab4', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 13, 13, 'I saw in the night visions, and behold, there came with the clouds of the sky one like a son of man, and he came even to the ancient of days, and they brought him near before him.'),
  ('4a89a9f5-e185-5cf7-a40d-381791023f52', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 14, 14, 'There was given him dominion, and glory, and a kingdom, that all the peoples, nations, and languages should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.'),
  ('0d973e97-cf48-5e7b-aaaf-a6481690bceb', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 15, 15, 'As for me, Daniel, my spirit was grieved in the midst of my body, and the visions of my head troubled me.'),
  ('39aa92a0-61aa-523b-a55e-3060fad4e827', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 16, 16, 'I came near to one of those who stood by, and asked him the truth concerning all this. So he told me, and made me know the interpretation of the things.'),
  ('67384abc-d05f-5242-a3cb-2f341e927397', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 17, 17, 'These great animals, which are four, are four kings, who shall arise out of the earth.'),
  ('1a4886dc-d3e1-51ce-af91-157a5cbb51a4', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 18, 18, 'But the saints of the Most High shall receive the kingdom, and possess the kingdom forever, even forever and ever.'),
  ('d81c2de3-5430-5f0d-a1ec-18cbb5ea85ca', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 19, 19, 'Then I desired to know the truth concerning the fourth animal, which was diverse from all of them, exceedingly terrible, whose teeth were of iron, and its nails of brass; which devoured, broke in pieces, and stamped the residue with its feet;'),
  ('0cfc2cd8-748b-5b3c-a472-544680e0b521', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 20, 20, 'and concerning the ten horns that were on its head, and the other [horn] which came up, and before which three fell, even that horn that had eyes, and a mouth that spoke great things, whose look was more stout than its fellows.'),
  ('70c04663-35eb-5e11-a4c5-b34a249b10ae', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 21, 21, 'I saw, and the same horn made war with the saints, and prevailed against them;'),
  ('85638fe1-2a1b-558f-a317-c645373e88e3', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 22, 22, 'until the ancient of days came, and judgment was given to the saints of the Most High, and the time came that the saints possessed the kingdom.'),
  ('4a389b28-dae1-5ef6-a51d-612f6c500ec2', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 23, 23, 'Thus he said, The fourth animal shall be a fourth kingdom on earth, which shall be diverse from all the kingdoms, and shall devour the whole earth, and shall tread it down, and break it in pieces.'),
  ('b87308dd-a65a-5eb3-ae02-54b329991798', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 24, 24, 'As for the ten horns, out of this kingdom shall ten kings arise: and another shall arise after them; and he shall be diverse from the former, and he shall put down three kings.'),
  ('6a148718-d084-55ea-a143-6a57c323140e', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 25, 25, 'He shall speak words against the Most High, and shall wear out the saints of the Most High; and he shall think to change the times and the law; and they shall be given into his hand until a time and times and half a time.'),
  ('6bb89127-4802-5c48-aebd-508070610f69', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 26, 26, 'But the judgment shall be set, and they shall take away his dominion, to consume and to destroy it to the end.'),
  ('d4d30ff5-0542-55af-a8bd-9db36e56d381', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 27, 27, 'The kingdom and the dominion, and the greatness of the kingdoms under the whole sky, shall be given to the people of the saints of the Most High: his kingdom is an everlasting kingdom, and all dominions shall serve and obey him.'),
  ('11b06f8e-34c1-5da4-a4cc-eab66059be15', 'baba0506-2a36-5d15-a1d3-f0827a5eb38b', NULL, 28, 28, 'Here is the end of the matter. As for me, Daniel, my thoughts much troubled me, and my face was changed in me: but I kept the matter in my heart.'),
  ('833877df-4ead-5244-ab97-40a06f70fc2a', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 1, 1, 'In the third year of the reign of king Belshazzar a vision appeared to me, even to me, Daniel, after that which appeared to me at the first.'),
  ('866b7268-07e8-52ca-a9c6-cd7ed562c7f6', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 2, 2, 'I saw in the vision; now it was so, that when I saw, I was in the citadel of Susa, which is in the province of Elam; and I saw in the vision, and I was by the river Ulai.'),
  ('70a987ae-67ea-5ae1-a6f7-47bd17dee087', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 3, 3, 'Then I lifted up my eyes, and saw, and behold, there stood before the river a ram which had two horns: and the two horns were high; but one was higher than the other, and the higher came up last.'),
  ('702f57d1-2708-54a6-a554-1264df6aba34', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 4, 4, 'I saw the ram pushing westward, and northward, and southward; and no animals could stand before him, neither was there any who could deliver out of his hand; but he did according to his will, and magnified himself.'),
  ('f03cc2b8-fa88-57c6-abf8-b7c3debec4b9', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 5, 5, 'As I was considering, behold, a male goat came from the west over the surface of the whole earth, and didn''t touch the ground: and the goat had a notable horn between his eyes.'),
  ('5465363d-9b7b-55df-af6d-9b88096e27d5', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 6, 6, 'He came to the ram that had the two horns, which I saw standing before the river, and ran on him in the fury of his power.'),
  ('1fc64cff-df40-544c-a456-078bc1ab68ad', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 7, 7, 'I saw him come close to the ram, and he was moved with anger against him, and struck the ram, and broke his two horns; and there was no power in the ram to stand before him; but he cast him down to the ground, and trampled on him; and there was none who could deliver the ram out of his hand.'),
  ('60e51434-2dff-5974-a0ee-fa7b72638548', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 8, 8, 'The male goat magnified himself exceedingly: and when he was strong, the great horn was broken; and instead of it there came up four notable [horns] toward the four winds of the sky.'),
  ('764beb8b-8761-591f-a972-2c673dd154bd', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 9, 9, 'Out of one of them came forth a little horn, which grew exceeding great, toward the south, and toward the east, and toward the glorious [land].'),
  ('7df8abd4-05e6-5a3a-a5bd-2b5e4594f39d', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 10, 10, 'It grew great, even to the army of the sky; and some of the army and of the stars it cast down to the ground, and trampled on them.'),
  ('0a55f38b-3fc7-5fcb-aa47-2ad5d2d5ec10', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 11, 11, 'Yes, it magnified itself, even to the prince of the army; and it took away from him the continual [burnt offering], and the place of his sanctuary was cast down.'),
  ('10c7f066-e62c-5887-a1c0-cc83f79fc728', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 12, 12, 'The army was given over [to it] together with the continual [burnt offering] through disobedience; and it cast down truth to the ground, and it did [its pleasure] and prospered.'),
  ('79eed672-0996-551c-abad-5977ec371006', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 13, 13, 'Then I heard a holy one speaking; and another holy one said to that certain one who spoke, How long shall be the vision [concerning] the continual [burnt offering], and the disobedience that makes desolate, to give both the sanctuary and the army to be trodden under foot?'),
  ('7b1d2c41-e9d1-53a4-a0e0-ed2e74bdd231', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 14, 14, 'He said to me, To two thousand and three hundred evenings [and] mornings; then shall the sanctuary be cleansed.'),
  ('b363779d-0662-5bb2-adcf-7daecd219cc7', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 15, 15, 'It happened, when I, even I Daniel, had seen the vision, that I sought to understand it; and behold, there stood before me as the appearance of a man.'),
  ('9397a335-6d34-5475-a882-57f0710a0151', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 16, 16, 'I heard a man''s voice between [the banks of] the Ulai, which called, and said, Gabriel, make this man to understand the vision.'),
  ('54401842-2373-5bc8-aaa0-9e6342662a9d', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 17, 17, 'So he came near where I stood; and when he came, I was frightened, and fell on my face: but he said to me, Understand, son of man; for the vision belongs to the time of the end.'),
  ('b8a0f40a-9f1e-59b0-ae1d-0f3033c4dd33', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 18, 18, 'Now as he was speaking with me, I fell into a deep sleep with my face toward the ground; but he touched me, and set me upright.'),
  ('90c725bb-3df3-5c9d-a58e-4a746ed2b5d7', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 19, 19, 'He said, Behold, I will make you know what shall be in the latter time of the indignation; for it belongs to the appointed time of the end.'),
  ('2feb7753-852d-5043-a402-08f9cded1ce8', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 20, 20, 'The ram which you saw, that had the two horns, they are the kings of Media and Persia.'),
  ('2144c56e-a15c-56b9-a3c3-f5b42a5eb186', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 21, 21, 'The rough male goat is the king of Greece: and the great horn that is between his eyes is the first king.'),
  ('e5ab992e-8801-596c-a2a2-6436d9de919c', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 22, 22, 'As for that which was broken, in the place where four stood up, four kingdoms shall stand up out of the nation, but not with his power.'),
  ('5d3d62e0-6913-5687-a680-901681619617', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 23, 23, 'In the latter time of their kingdom, when the transgressors are come to the full, a king of fierce face, and understanding dark sentences, shall stand up.'),
  ('79561b88-6d28-5bcc-afb6-e3ac5e9c44f4', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 24, 24, 'His power shall be mighty, but not by his own power; and he shall destroy wonderfully, and shall prosper and do [his pleasure]; and he shall destroy the mighty ones and the holy people.'),
  ('774e4d70-51da-5ad0-ab18-bd311530ad12', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 25, 25, 'Through his policy he shall cause craft to prosper in his hand; and he shall magnify himself in his heart, and in [their] security shall he destroy many: he shall also stand up against the prince of princes; but he shall be broken without hand.'),
  ('45679f53-e37d-5b3d-a7cc-ec1adec20d03', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 26, 26, 'The vision of the evenings and mornings which has been told is true: but seal up the vision; for it belongs to many days [to come].'),
  ('7752c92c-bd67-5143-aefc-3092a1d443ce', '9b30a4ed-e7fe-5ab7-aa14-bdfffc547b45', NULL, 27, 27, 'I, Daniel, fainted, and was sick certain days; then I rose up, and did the king''s business: and I wondered at the vision, but none understood it.'),
  ('846ef6c9-69d4-59ea-a832-95713bbd280f', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 1, 1, 'In the first year of Darius the son of Ahasuerus, of the seed of the Medes, who was made king over the realm of the Chaldeans,'),
  ('d632dbe5-3826-59cd-a3d1-40389d4e59e0', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 2, 2, 'in the first year of his reign I, Daniel, understood by the books the number of the years about which the word of Yahweh came to Jeremiah the prophet, for the accomplishing of the desolations of Jerusalem, even seventy years.'),
  ('f4f8dec1-f973-58ef-af3a-6b62ef9377ea', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 3, 3, 'I set my face to the Lord God, to seek by prayer and petitions, with fasting and sackcloth and ashes.'),
  ('4cb5ba21-2a15-5359-ac9f-542425783fb4', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 4, 4, 'I prayed to Yahweh my God, and made confession, and said, Oh, Lord, the great and dreadful God, who keeps covenant and loving kindness with those who love him and keep his commandments,'),
  ('e0200420-2d2e-550f-a3fd-3eb9aa1599b8', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 5, 5, 'we have sinned, and have dealt perversely, and have done wickedly, and have rebelled, even turning aside from your precepts and from your ordinances;'),
  ('39dd796c-9d0d-5405-a1c0-ab4b9c0a2189', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 6, 6, 'neither have we listened to your servants the prophets, who spoke in your name to our kings, our princes, and our fathers, and to all the people of the land.'),
  ('4a7335a3-24bd-5f88-a5a6-ae1ce2881bfc', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 7, 7, 'Lord, righteousness belongs to you, but to us confusion of face, as at this day; to the men of Judah, and to the inhabitants of Jerusalem, and to all Israel, who are near, and who are far off, through all the countries where you have driven them, because of their trespass that they have trespassed against you.'),
  ('cb6a3872-0151-515d-ac20-b3bedd0efdd2', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 8, 8, 'Lord, to us belongs confusion of face, to our kings, to our princes, and to our fathers, because we have sinned against you.'),
  ('b68753d4-0287-59cd-aeaf-f23b0dddc5e6', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 9, 9, 'To the Lord our God belong mercies and forgiveness; for we have rebelled against him;'),
  ('ecfe5cfe-a7c8-5a1e-a5c9-12209f83d5ac', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 10, 10, 'neither have we obeyed the voice of Yahweh our God, to walk in his laws, which he set before us by his servants the prophets.'),
  ('2da5656c-ee36-5c4b-a7dc-eda5ea43e063', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 11, 11, 'Yes, all Israel have transgressed your law, turning aside, that they should not obey your voice: therefore the curse and the oath written in the law of Moses the servant of God has been poured out on us; for we have sinned against him.'),
  ('9cfcdcd0-3ee7-574c-a6b7-11400e55dd21', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 12, 12, 'He has confirmed his words, which he spoke against us, and against our judges who judged us, by bringing on us a great evil; for under the whole sky, such has not been done as has been done to Jerusalem.'),
  ('6e2663d6-91b5-5f1e-a209-25a7620507ef', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 13, 13, 'As it is written in the law of Moses, all this evil is come on us: yet have we not entreated the favor of Yahweh our God, that we should turn from our iniquities, and have discernment in your truth.'),
  ('a4d922eb-4402-5d24-a920-321ac968f76d', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 14, 14, 'Therefore has Yahweh watched over the evil, and brought it on us; for Yahweh our God is righteous in all his works which he does, and we have not obeyed his voice.'),
  ('97ad595d-0111-5b1b-a8f0-2d6a070abc2a', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 15, 15, 'Now, Lord our God, who has brought your people forth out of the land of Egypt with a mighty hand, and have gotten yourself renown, as at this day; we have sinned, we have done wickedly.'),
  ('77ed0572-da0f-5981-a2e4-5ab0f5f17cc5', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 16, 16, 'Lord, according to all your righteousness, let your anger and please let your wrath be turned away from your city Jerusalem, your holy mountain; because for our sins, and for the iniquities of our fathers, Jerusalem and your people have become a reproach to all who are around us.'),
  ('8427ed07-9383-5a48-ad06-94f082bf99ba', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 17, 17, 'Now therefore, our God, listen to the prayer of your servant, and to his petitions, and cause your face to shine on your sanctuary that is desolate, for the Lord''s sake.'),
  ('1ab3dccb-306b-58bd-a4f1-f9b13e3c9066', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 18, 18, 'My God, turn your ear, and hear; open your eyes, and see our desolations, and the city which is called by your name: for we do not present our petitions before you for our righteousness, but for your great mercies'' sake.'),
  ('0907d4d2-8ea6-5c76-a119-66aeb1c533df', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 19, 19, 'Lord, hear; Lord, forgive; Lord, listen and do; don''t defer, for your own sake, my God, because your city and your people are called by your name.'),
  ('7205f0d5-02c9-5f18-ab0d-1956fe84af70', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 20, 20, 'While I was speaking, and praying, and confessing my sin and the sin of my people Israel, and presenting my supplication before Yahweh my God for the holy mountain of my God;'),
  ('2259b13c-8996-5bd1-a05a-2b24495328ad', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 21, 21, 'yes, while I was speaking in prayer, the man Gabriel, whom I had seen in the vision at the beginning, being caused to fly swiftly, touched me about the time of the evening offering.'),
  ('57cfe46c-b429-5e24-a3d9-5532ba3ff879', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 22, 22, 'He instructed me, and talked with me, and said, Daniel, I am now come forth to give you wisdom and understanding.'),
  ('5133ed13-dfaa-556f-a0b9-6b22854f13fa', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 23, 23, 'At the beginning of your petitions the commandment went forth, and I have come to tell you; for you are greatly beloved: therefore consider the matter, and understand the vision.'),
  ('2833dd41-ac0a-5885-ac31-94bf823ba652', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 24, 24, 'Seventy weeks are decreed on your people and on your holy city, to finish disobedience, and to make an end of sins, and to make reconciliation for iniquity, and to bring in everlasting righteousness, and to seal up vision and prophecy, and to anoint the most holy.'),
  ('9c4312d6-e858-5a5f-ac2d-7ef6700a0577', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 25, 25, 'Know therefore and discern, that from the going forth of the commandment to restore and to build Jerusalem to the Anointed One, the prince, shall be seven weeks, and sixty-two weeks: it shall be built again, with street and moat, even in troubled times.'),
  ('10e6adc7-14a3-5533-aff4-dd591a9c576b', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 26, 26, 'After the sixty-two weeks the Anointed One shall be cut off, and shall have nothing: and the people of the prince who shall come shall destroy the city and the sanctuary; and its end shall be with a flood, and even to the end shall be war; desolations are determined.'),
  ('237a9e6f-99d4-574b-ae52-2e4e5c8b4724', 'e2f2beb3-4e2b-5fff-a365-9143a0139347', NULL, 27, 27, 'He shall make a firm covenant with many for one week: and in the midst of the week he shall cause the sacrifice and the offering to cease; and on the wing of abominations [shall come] one who makes desolate; and even to the full end, and that determined, shall [wrath] be poured out on the desolate.'),
  ('5ac88817-3c2d-529d-ad13-7327fe3a3d26', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 1, 1, 'In the third year of Cyrus king of Persia a thing was revealed to Daniel, whose name was called Belteshazzar; and the thing was true, even a great warfare: and he understood the thing, and had understanding of the vision.'),
  ('702d8f6e-769c-50fb-a990-b76f93b2eab5', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 2, 2, 'In those days I, Daniel, was mourning three whole weeks.'),
  ('03e2ac81-37c1-5292-a411-d54b4e164530', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 3, 3, 'I ate no pleasant bread, neither came flesh nor wine into my mouth, neither did I anoint myself at all, until three whole weeks were fulfilled.'),
  ('6ff324c6-fa46-5cd4-ad80-ba0069240cbd', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 4, 4, 'In the four and twentieth day of the first month, as I was by the side of the great river, which is Hiddekel,'),
  ('6b7655d9-36d7-5d1e-afcf-80ee67904240', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 5, 5, 'I lifted up my eyes, and looked, and behold, a man clothed in linen, whose thighs were adorned with pure gold of Uphaz:'),
  ('420fef38-b009-5291-aa91-611e4f978ace', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 6, 6, 'his body also was like the beryl, and his face as the appearance of lightning, and his eyes as flaming torches, and his arms and his feet like burnished brass, and the voice of his words like the voice of a multitude.'),
  ('6747cb94-93e3-5596-ac98-c4bd6826a7fb', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 7, 7, 'I, Daniel, alone saw the vision; for the men who were with me didn''t see the vision; but a great quaking fell on them, and they fled to hide themselves.'),
  ('a9d98c7d-905d-5c2c-aa21-17c389b94c99', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 8, 8, 'So I was left alone, and saw this great vision, and there remained no strength in me; for my comeliness was turned in me into corruption, and I retained no strength.'),
  ('65dcfd47-5f92-5977-ad87-a9d304e045c6', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 9, 9, 'Yet heard I the voice of his words; and when I heard the voice of his words, then was I fallen into a deep sleep on my face, with my face toward the ground.'),
  ('26918745-72f8-5ff4-a764-70e1da13d3f4', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 10, 10, 'Behold, a hand touched me, which set me on my knees and on the palms of my hands.'),
  ('dc67dd42-45c1-57fb-a0c1-7b7d07b27b30', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 11, 11, 'He said to me, Daniel, you man greatly beloved, understand the words that I speak to you, and stand upright; for am I now sent to you. When he had spoken this word to me, I stood trembling.'),
  ('75bdf824-4f85-5bcb-a4e7-fe1b3c9fc359', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 12, 12, 'Then he said to me, Don''t be afraid, Daniel; for from the first day that you set your heart to understand, and to humble yourself before your God, your words were heard: and I have come for your words'' sake.'),
  ('194b6065-eec6-5421-a317-06fcd23062a5', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 13, 13, 'But the prince of the kingdom of Persia withstood me twenty-one days; but, behold, Michael, one of the chief princes, came to help me: and I remained there with the kings of Persia.'),
  ('3b1b1fcb-f601-5f56-ab49-040cd9acb945', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 14, 14, 'Now I have come to make you understand what shall happen to your people in the latter days; for the vision is yet for [many] days:'),
  ('c74a5171-b155-5736-a1eb-70048e0fac2d', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 15, 15, 'and when he had spoken to me according to these words, I set my face toward the ground, and was mute.'),
  ('1ab2ae9b-6a52-5e93-aaeb-2af81e5a24d8', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 16, 16, 'Behold, one in the likeness of the sons of men touched my lips: then I opened my mouth, and spoke and said to him who stood before me, my lord, by reason of the vision my sorrows are turned on me, and I retain no strength.'),
  ('4fe629b8-7d93-5a3d-a370-636f3de2c394', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 17, 17, 'For how can the servant of this my lord talk with this my lord? for as for me, immediately there remained no strength in me, neither was there breath left in me.'),
  ('3294a5b5-06c6-59b2-afeb-a6a8e911f1d9', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 18, 18, 'Then there touched me again one like the appearance of a man, and he strengthened me.'),
  ('8140ca46-7c3e-557b-a109-958cb7ac624d', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 19, 19, 'He said, "Greatly beloved man, don''t be afraid: peace be to you, be strong, yes, be strong." When he spoke to me, I was strengthened, and said, "Let my lord speak; for you have strengthened me."'),
  ('71e613ce-3010-5d2f-aa6d-6e438e5833de', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 20, 20, 'Then he said, "Do you know why I have come to you? Now I will return to fight with the prince of Persia. When I go forth, behold, the prince of Greece shall come.'),
  ('b654245e-e5a1-543d-a288-61dd23050a9d', 'e20447ca-67fd-5b2a-a38f-9a5db3abc9a6', NULL, 21, 21, 'But I will tell you that which is inscribed in the writing of truth: and there is none who holds with me against these, but Michael your prince."'),
  ('a5116447-c0a3-5d04-a7b6-2f287e16ebf1', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 1, 1, '"As for me, in the first year of Darius the Mede, I stood up to confirm and strengthen him.'),
  ('e836d3a6-053c-55ed-a51d-9060fe0b8479', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 2, 2, 'Now will I show you the truth. Behold, there shall stand up yet three kings in Persia; and the fourth shall be far richer than they all: and when he has grown strong through his riches, he shall stir up all against the realm of Greece.'),
  ('1bc19ac7-002f-5d5a-a55f-0e541b08047f', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 3, 3, 'A mighty king shall stand up, who shall rule with great dominion, and do according to his will.'),
  ('d3411209-9a7f-5b08-ae55-6b76be6c7fde', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 4, 4, 'When he shall stand up, his kingdom shall be broken, and shall be divided toward the four winds of the sky, but not to his posterity, nor according to his dominion with which he ruled; for his kingdom shall be plucked up, even for others besides these.'),
  ('e962a395-f36f-54a6-af20-ebdcd947e887', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 5, 5, 'The king of the south shall be strong, and [one] of his princes; and he shall be strong above him, and have dominion; his dominion shall be a great dominion.'),
  ('3ff3c28d-722a-5fbb-a7a3-12070b707775', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 6, 6, 'At the end of years they shall join themselves together; and the daughter of the king of the south shall come to the king of the north to make an agreement: but she shall not retain the strength of her arm; neither shall he stand, nor his arm; but she shall be given up, and those who brought her, and he who became the father of her, and he who strengthened her in those times.'),
  ('706a3411-cd49-5729-a49a-1642507232ac', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 7, 7, 'But out of a shoot from her roots shall one stand up in his place, who shall come to the army, and shall enter into the fortress of the king of the north, and shall deal against them, and shall prevail.'),
  ('26b93fd9-fa99-52e7-a7ee-cd4f612be852', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 8, 8, 'Also their gods, with their molten images, [and] with their goodly vessels of silver and of gold, shall he carry captive into Egypt; and he shall refrain some years from the king of the north.'),
  ('e1dbf143-8df6-548e-a2b6-93bcaf823cfd', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 9, 9, 'He shall come into the realm of the king of the south, but he shall return into his own land.'),
  ('1fb0e376-8970-5791-a57f-0a28037c98d2', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 10, 10, 'His sons shall war, and shall assemble a multitude of great forces, which shall come on, and overflow, and pass through; and they shall return and war, even to his fortress.'),
  ('4f4aca9f-f86a-592b-a510-83a16b482d44', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 11, 11, 'The king of the south shall be moved with anger, and shall come forth and fight with him, even with the king of the north; and he shall set forth a great multitude, and the multitude shall be given into his hand.'),
  ('ad0cfec5-0fc6-5154-ae00-0b1046a9eb89', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 12, 12, 'The multitude shall be lifted up, and his heart shall be exalted; and he shall cast down tens of thousands, but he shall not prevail.'),
  ('cf9f84ac-050f-5847-aad0-4cf4e1d22087', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 13, 13, 'The king of the north shall return, and shall set forth a multitude greater than the former; and he shall come on at the end of the times, [even of] years, with a great army and with much substance.'),
  ('6040742d-4b0e-50aa-a6b4-c7c576d1d384', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 14, 14, 'In those times there shall many stand up against the king of the south: also the children of the violent among your people shall lift themselves up to establish the vision; but they shall fall.'),
  ('63992b5e-53c4-5ec5-a67b-366cdac5b366', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 15, 15, 'So the king of the north shall come, and cast up a mound, and take a well-fortified city: and the forces of the south shall not stand, neither his chosen people, neither shall there be any strength to stand.'),
  ('c4e2d04b-65a7-5bef-aaf5-b9f3d26d15cf', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 16, 16, 'But he who comes against him shall do according to his own will, and none shall stand before him; and he shall stand in the glorious land, and in his hand shall be destruction.'),
  ('f951047d-df6b-572c-afed-1067ed053a89', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 17, 17, 'He shall set his face to come with the strength of his whole kingdom, and with him equitable conditions; and he shall perform them: and he shall give him the daughter of women, to corrupt her; but she shall not stand, neither be for him.'),
  ('b51d0b92-1a6c-5558-abd2-fcd0879415ba', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 18, 18, 'After this shall he turn his face to the islands, and shall take many: but a prince shall cause the reproach offered by him to cease; yes, moreover, he shall cause his reproach to turn on him.'),
  ('d215e0ee-baec-59bd-ab89-480ad02c79d9', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 19, 19, 'Then he shall turn his face toward the fortresses of his own land; but he shall stumble and fall, and shall not be found.'),
  ('290e6dbf-b53d-5f7d-a19e-3d64a01796c0', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 20, 20, 'Then shall stand up in his place one who shall cause a tax collector to pass through the kingdom to maintain its glory; but within few days he shall be destroyed, neither in anger, nor in battle.'),
  ('4b39fa0a-f835-5508-a9d3-e24547679048', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 21, 21, 'In his place shall stand up a contemptible person, to whom they had not given the honor of the kingdom: but he shall come in time of security, and shall obtain the kingdom by flatteries.'),
  ('104cb173-1354-57ad-ad42-b0f6aa170143', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 22, 22, 'The overwhelming forces shall be overwhelmed from before him, and shall be broken; yes, also the prince of the covenant.'),
  ('f2b2f155-efe1-5d7a-ad46-b6afd24922a1', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 23, 23, 'After the treaty made with him he shall work deceitfully; for he shall come up, and shall become strong, with a small people.'),
  ('6e0c3955-3847-5d08-a52c-e76534386dc0', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 24, 24, 'In time of security shall he come even on the fattest places of the province; and he shall do that which his fathers have not done, nor his fathers'' fathers; he shall scatter among them prey, and spoil, and substance: yes, he shall devise his devices against the strongholds, even for a time.'),
  ('feaec294-697f-5cb0-a517-76a503df7618', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 25, 25, 'He shall stir up his power and his courage against the king of the south with a great army; and the king of the south shall war in battle with an exceeding great and mighty army; but he shall not stand; for they shall devise devices against him.'),
  ('3d03aeca-40f7-5730-a287-c7f4219387c8', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 26, 26, 'Yes, they who eat of his dainties shall destroy him, and his army shall overflow; and many shall fall down slain.'),
  ('6c108698-f117-5f66-a396-85881d8a7ad5', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 27, 27, 'As for both these kings, their hearts shall be to do mischief, and they shall speak lies at one table: but it shall not prosper; for yet the end shall be at the time appointed.'),
  ('9b6dc209-a8de-5ce2-ac24-9c75fe3ad193', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 28, 28, 'Then shall he return into his land with great substance; and his heart [shall be] against the holy covenant; and he shall do [his pleasure], and return to his own land.'),
  ('89776360-719f-5c14-ae6b-366c4577e3e9', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 29, 29, 'At the time appointed he shall return, and come into the south; but it shall not be in the latter time as it was in the former.'),
  ('459042b5-6343-5869-a1aa-052af45b3a0a', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 30, 30, 'For ships of Kittim shall come against him; therefore he shall be grieved, and shall return, and have indignation against the holy covenant, and shall do [his pleasure]: he shall even return, and have regard to those who forsake the holy covenant.'),
  ('892b3596-5e67-5224-ad7e-07b965c9cc17', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 31, 31, 'Forces shall stand on his part, and they shall profane the sanctuary, even the fortress, and shall take away the continual [burnt offering], and they shall set up the abomination that makes desolate.'),
  ('953d855c-ae4a-5cc1-a369-f75ca70f5475', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 32, 32, 'Such as do wickedly against the covenant shall he pervert by flatteries; but the people who know their God shall be strong, and do [exploits].'),
  ('3f4c3d05-083a-5613-a9a8-d7a4be13c707', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 33, 33, 'Those who are wise among the people shall instruct many; yet they shall fall by the sword and by flame, by captivity and by spoil, [many] days.'),
  ('83d14775-79b0-5edb-ab4c-a5cc699a029c', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 34, 34, 'Now when they shall fall, they shall be helped with a little help; but many shall join themselves to them with flatteries.'),
  ('3ed20440-1885-5ce6-a5c2-596f5047d519', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 35, 35, 'Some of those who are wise shall fall, to refine them, and to purify, and to make them white, even to the time of the end; because it is yet for the time appointed.'),
  ('c8d1de11-e835-5720-a854-f11fe287d3c7', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 36, 36, 'The king shall do according to his will; and he shall exalt himself, and magnify himself above every god, and shall speak marvelous things against the God of gods; and he shall prosper until the indignation be accomplished; for that which is determined shall be done.'),
  ('30159f1a-451a-5f91-a407-6da9f9016477', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 37, 37, 'Neither shall he regard the gods of his fathers, nor the desire of women, nor regard any god; for he shall magnify himself above all.'),
  ('4eca5b3b-fd57-5e61-a73b-673d5af5bb81', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 38, 38, 'But in his place shall he honor the god of fortresses; and a god whom his fathers didn''t know shall he honor with gold, and silver, and with precious stones, and pleasant things.'),
  ('0a28210e-5904-5559-a3b2-bc445195bd72', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 39, 39, 'He shall deal with the strongest fortresses by the help of a foreign god: whoever acknowledges [him] he will increase with glory; and he shall cause them to rule over many, and shall divide the land for a price.'),
  ('d4c6a9fb-fb0f-5841-aefe-b37c6e722b6e', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 40, 40, 'At the time of the end shall the king of the south contend with him; and the king of the north shall come against him like a whirlwind, with chariots, and with horsemen, and with many ships; and he shall enter into the countries, and shall overflow and pass through.'),
  ('e78c46ce-b850-517d-adbb-6d882bf18eed', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 41, 41, 'He shall enter also into the glorious land, and many [countries] shall be overthrown; but these shall be delivered out of his hand: Edom, and Moab, and the chief of the children of Ammon.'),
  ('af95e78d-5e17-59df-a585-bccf85de440c', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 42, 42, 'He shall stretch forth his hand also on the countries; and the land of Egypt shall not escape.'),
  ('706b7ea0-0352-5eb3-a81e-9ac5cb3c030a', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 43, 43, 'But he shall have power over the treasures of gold and of silver, and over all the precious things of Egypt; and the Libyans and the Ethiopians shall be at his steps.'),
  ('6b1407a6-19e2-54e2-a616-70fdbd21ddf1', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 44, 44, 'But news out of the east and out of the north shall trouble him; and he shall go forth with great fury to destroy and utterly to sweep away many.'),
  ('c15abdf6-857f-5abc-a1f5-32f910c5f05b', '7d55ec4c-5344-5a3b-a4c5-7d54c3e9959f', NULL, 45, 45, 'He shall plant the tents of his palace between the sea and the glorious holy mountain; yet he shall come to his end, and none shall help him.'),
  ('82063230-1bea-56b0-a816-2e4a26ea5bd5', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 1, 1, '"At that time shall Michael stand up, the great prince who stands for the children of your people; and there shall be a time of trouble, such as never was since there was a nation even to that same time: and at that time your people shall be delivered, everyone who shall be found written in the book.'),
  ('32ad7aa2-ae7b-52cf-ab70-85dbe5d06567', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 2, 2, 'Many of those who sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt.'),
  ('bb8375af-78f6-5091-a0c2-7c317f6a1a64', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 3, 3, 'Those who are wise shall shine as the brightness of the expanse; and those who turn many to righteousness as the stars forever and ever.'),
  ('bb398b74-8cf0-58bb-a632-85fca14a04cb', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 4, 4, 'But you, Daniel, shut up the words, and seal the book, even to the time of the end: many shall run back and forth, and knowledge shall be increased."'),
  ('59665cd5-415c-515b-a376-84505205380e', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 5, 5, 'Then I, Daniel, looked, and behold, two others stood, one on the river bank on this side, and the other on the river bank on that side.'),
  ('60539146-7206-525c-a9fd-80e911becbb2', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 6, 6, 'One said to the man clothed in linen, who was above the waters of the river, How long shall it be to the end of these wonders?'),
  ('1acb4894-43fe-5b47-aa71-4319beb1f6dd', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 7, 7, 'I heard the man clothed in linen, who was above the waters of the river, when he held up his right hand and his left hand to heaven, and swore by him who lives forever that it shall be for a time, times, and a half; and when they have made an end of breaking in pieces the power of the holy people, all these things shall be finished.'),
  ('c92653e3-a55a-58d2-a2bd-54a97f827c0d', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 8, 8, 'I heard, but I didn''t understand: then I said, my lord, what shall be the issue of these things?'),
  ('158007cf-09b1-50b4-aee3-c278542cbf04', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 9, 9, 'He said, Go your way, Daniel; for the words are shut up and sealed until the time of the end.'),
  ('f5ff5389-7897-5ad1-a505-8bea08c8f1d8', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 10, 10, 'Many shall purify themselves, and make themselves white, and be refined; but the wicked shall do wickedly; and none of the wicked shall understand; but those who are wise shall understand.'),
  ('52f6f9f7-e0c0-515b-a313-69fe21e6ff8a', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 11, 11, 'From the time that the continual [burnt offering] shall be taken away, and the abomination that makes desolate set up, there shall be one thousand two hundred ninety days.'),
  ('c0aef8e0-e4a0-5280-a822-bb9c9f6b97a8', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 12, 12, 'Blessed is he who waits, and comes to the one thousand three hundred thirty-five days.'),
  ('93872576-5713-5775-aef2-a769d9731349', '8d300ffc-2f62-546f-a319-8726d8fd70e2', NULL, 13, 13, 'But go you your way until the end; for you shall rest, and shall stand in your lot, at the end of the days.'),
  ('43bfdf53-4144-5c7d-a467-a95832aa501f', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 1, 1, 'The word of Yahweh that came to Hosea the son of Beeri, in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah, and in the days of Jeroboam the son of Joash, king of Israel.'),
  ('0adaa60f-0048-5a55-a2d0-4e92450ae89f', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 2, 2, 'When Yahweh spoke at first by Hosea, Yahweh said to Hosea, "Go, take for yourself a wife of prostitution and children of unfaithfulness; for the land commits great adultery, forsaking Yahweh."'),
  ('3e920a91-2da2-5dc7-a69f-88bb0d211c03', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 3, 3, 'So he went and took Gomer the daughter of Diblaim; and she conceived, and bore him a son.'),
  ('a65918f9-c9b5-5fea-a0a4-c854123c53f6', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 4, 4, 'Yahweh said to him, "Call his name Jezreel; for yet a little while, and I will avenge the blood of Jezreel on the house of Jehu, and will cause the kingdom of the house of Israel to cease.'),
  ('66210d48-9b19-5aeb-a945-b561858650c5', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 5, 5, 'It will happen in that day that I will break the bow of Israel in the valley of Jezreel."'),
  ('5f70fa79-4cb0-5b00-a25c-f2adf2276da2', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 6, 6, 'She conceived again, and bore a daughter. Then he said to him, "Call her name Lo-Ruhamah; for I will no longer have mercy on the house of Israel, that I should in any way pardon them.'),
  ('acc736c6-b875-559f-a228-a3b77672f74a', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 7, 7, 'But I will have mercy on the house of Judah, and will save them by Yahweh their God, and will not save them by bow, sword, battle, horses, or horsemen."'),
  ('fa5c9d0f-a066-5c12-a66a-3c60a13385f7', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 8, 8, 'Now when she had weaned Lo-Ruhamah, she conceived, and bore a son.'),
  ('11227c38-35a6-5c8f-a8cb-10b9917daae2', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 9, 9, 'He said, "Call his name Lo-Ammi; for you are not my people, and I will not be yours.'),
  ('544d5be9-6117-591f-a4e7-b2bfb0deb48d', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 10, 10, 'Yet the number of the children of Israel will be as the sand of the sea, which can''t be measured nor numbered; and it will come to pass that, in the place where it was said to them, ''You are not my people,'' they will be called ''sons of the living God.'''),
  ('dd647f20-f006-54a9-a3d8-0327b091babd', '1465dac6-245e-515b-a8cd-7d191cfb79b0', NULL, 11, 11, 'The children of Judah and the children of Israel will be gathered together, and they will appoint themselves one head, and will go up from the land; for great will be the day of Jezreel.'),
  ('77a83cab-0e9e-5ac7-a619-8a3dcab74d14', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 1, 1, '"Say to your brothers, ''My people!'' and to your sisters, ''My loved one!'''),
  ('531cf2c2-78a0-55f2-ae72-e6a39d2c082e', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 2, 2, 'Contend with your mother! Contend, for she is not my wife, neither am I her husband; and let her put away her prostitution from her face, and her adulteries from between her breasts;'),
  ('dcf4b91b-93a7-5eb7-a165-79f071696792', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 3, 3, 'Lest I strip her naked, and make her bare as in the day that she was born, and make her like a wilderness, and set her like a dry land, and kill her with thirst.'),
  ('ebacbcdf-4833-565f-ab43-4400d7748418', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 4, 4, 'Indeed, on her children I will have no mercy; for they are children of unfaithfulness;'),
  ('e21593a6-7187-5765-a655-e72bcacb79d0', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 5, 5, 'For their mother has played the prostitute. She who conceived them has done shamefully; for she said, ''I will go after my lovers, who give me my bread and my water, my wool and my flax, my oil and my drink.''')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('c6596d84-e84f-5f3f-a511-f32bf9b90f64', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 6, 6, 'Therefore, behold, I will hedge up your way with thorns, and I will build a wall against her, that she can''t find her way.'),
  ('7255f81b-9223-52bc-a739-c56ccad6e4d1', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 7, 7, 'She will follow after her lovers, but she won''t overtake them; and she will seek them, but won''t find them. Then she will say, ''I will go and return to my first husband; for then was it better with me than now.'''),
  ('52fd0c9c-ed9e-58e6-af6d-7a36c1e8611d', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 8, 8, 'For she did not know that I gave her the grain, the new wine, and the oil, and multiplied to her silver and gold, which they used for Baal.'),
  ('5e50cd59-ca04-57b5-a29a-1ea2e7af191b', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 9, 9, 'Therefore I will take back my grain in its time, and my new wine in its season, and will pluck away my wool and my flax which should have covered her nakedness.'),
  ('64c0f168-33a3-59c0-a3bd-405619c1a9f5', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 10, 10, 'Now I will uncover her lewdness in the sight of her lovers, and no one will deliver her out of my hand.'),
  ('9c562b66-c8b4-570c-a14d-073d26b62734', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 11, 11, 'I will also cause all her celebrations to cease: her feasts, her new moons, her Sabbaths, and all her solemn assemblies.'),
  ('fbd36a1c-2ee2-567f-aff9-4f7166dceec4', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 12, 12, 'I will lay waste her vines and her fig trees, about which she has said, ''These are my wages that my lovers have given me; and I will make them a forest,'' and the animals of the field shall eat them.'),
  ('0774365f-56f0-556f-afa9-87d9fd0b4687', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 13, 13, 'I will visit on her the days of the Baals, to which she burned incense, when she decked herself with her earrings and her jewels, and went after her lovers, and forgot me," says Yahweh.'),
  ('36fd99a1-e08e-52e8-a3e7-847914848732', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 14, 14, '"Therefore, behold, I will allure her, and bring her into the wilderness, and speak tenderly to her.'),
  ('16c9c3c6-90cb-5f1f-a43b-abb7d5d0d36e', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 15, 15, 'I will give her vineyards from there, and the valley of Achor for a door of hope; and she will respond there, as in the days of her youth, and as in the day when she came up out of the land of Egypt.'),
  ('5cde31e0-aac3-5f71-a66d-d8081d63cfd3', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 16, 16, 'It will be in that day," says Yahweh, "that you will call me ''my husband,'' and no longer call me ''my master.'''),
  ('539c76a0-dd10-5b42-a70b-fd4dfda558da', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 17, 17, 'For I will take away the names of the Baals out of her mouth, and they will no longer be mentioned by name.'),
  ('c9bea99c-66da-5ca8-a551-61feaa74c1f3', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 18, 18, 'In that day I will make a covenant for them with the animals of the field, and with the birds of the sky, and with the creeping things of the ground. I will break the bow, the sword, and the battle out of the land, and will make them lie down safely.'),
  ('9ff6cbb7-48f7-5ab5-aa10-c6f9518ceaaf', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 19, 19, 'I will betroth you to me forever. Yes, I will betroth you to me in righteousness, in justice, in loving kindness, and in compassion.'),
  ('3c601fd3-b6ee-5eab-a7d0-416b4180ae12', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 20, 20, 'I will even betroth you to me in faithfulness; and you shall know Yahweh.'),
  ('5de71387-86b0-5c64-a9c9-98b3c61c5443', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 21, 21, 'It will happen in that day, I will respond," says Yahweh, "I will respond to the heavens, and they will respond to the earth;'),
  ('64ccc030-aa06-5546-afba-f2afa5dac44c', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 22, 22, 'and the earth will respond to the grain, and the new wine, and the oil; and they will respond to Jezreel.'),
  ('063dc81e-cb27-57af-a3db-688e384a8f1a', 'e5b455b2-294f-51d2-a9ef-fa0929f7e6e2', NULL, 23, 23, 'I will sow her to me in the earth; and I will have mercy on her who had not obtained mercy; and I will tell those who were not my people, ''You are my people;'' and they will say, ''My God!''"'),
  ('ce807abd-f723-54d0-abd8-b049f313baee', '90074df7-4440-5726-aa04-e4ab9fdeeb39', NULL, 1, 1, 'Yahweh said to me, "Go again, love a woman loved by another, and an adulteress, even as Yahweh loves the children of Israel, though they turn to other gods, and love cakes of raisins."'),
  ('d4652f05-97f5-5cbc-a7dc-25bfdd305b23', '90074df7-4440-5726-aa04-e4ab9fdeeb39', NULL, 2, 2, 'So I bought her for myself for fifteen pieces of silver and a homer and a half of barley.'),
  ('b97a368c-6d12-5a3c-ad9a-e52f1f087d2b', '90074df7-4440-5726-aa04-e4ab9fdeeb39', NULL, 3, 3, 'I said to her, "You shall stay with me many days. You shall not play the prostitute, and you shall not be with any other man. I will also be so toward you."'),
  ('0e634663-ca24-5dd7-a86f-23f2779d87f5', '90074df7-4440-5726-aa04-e4ab9fdeeb39', NULL, 4, 4, 'For the children of Israel shall live many days without king, and without prince, and without sacrifice, and without sacred stone, and without ephod or idols.'),
  ('3b3b570a-14bd-5c70-ab31-8d52791f74fc', '90074df7-4440-5726-aa04-e4ab9fdeeb39', NULL, 5, 5, 'Afterward the children of Israel shall return, and seek Yahweh their God, and David their king, and shall come with trembling to Yahweh and to his blessings in the last days.'),
  ('0a4ce10e-666a-5726-a8d4-026802259248', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 1, 1, 'Hear the word of Yahweh, you children of Israel; for Yahweh has a charge against the inhabitants of the land: "Indeed there is no truth, nor goodness, nor knowledge of God in the land.'),
  ('74c0c812-ce9b-5459-a6a6-c54e5f055922', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 2, 2, 'There is cursing, lying, murder, stealing, and committing adultery; they break boundaries, and bloodshed causes bloodshed.'),
  ('0822ec08-9514-58c5-ae69-ef9b7f7c6749', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 3, 3, 'Therefore the land will mourn, and everyone who dwells therein will waste away. all living things in her, even the animals of the field and the birds of the sky; yes, the fish of the sea also die.'),
  ('cbe19a5a-ad34-545a-aa0a-805caec1bb35', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 4, 4, '"Yet let no man bring a charge, neither let any man accuse; For your people are like those who bring charges against a priest.'),
  ('a3364d53-da22-5d12-a045-314ecde862f6', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 5, 5, 'You will stumble in the day, and the prophet will also stumble with you in the night; and I will destroy your mother.'),
  ('d6a59b61-1edd-5662-a43e-42e313d87020', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 6, 6, 'My people are destroyed for lack of knowledge. Because you have rejected knowledge, I will also reject you, that you may be no priest to me. Because you have forgotten your God''s law, I will also forget your children.'),
  ('b330a7c2-8c74-5a03-abdd-eff448282a6d', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 7, 7, 'As they were multiplied, so they sinned against me. I will change their glory into shame.'),
  ('c57e5f8a-48dd-565b-ab2a-cba2f398ee67', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 8, 8, 'They feed on the sin of my people, and set their heart on their iniquity.'),
  ('9892d49e-6931-547a-aa26-5f9a7d0327c8', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 9, 9, 'It will be, like people, like priest; and I will punish them for their ways, and will repay them for their deeds.'),
  ('bc6b0681-ab41-5049-aab9-9642411c2f56', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 10, 10, 'They will eat, and not have enough. They will play the prostitute, and will not increase; because they have abandoned giving to Yahweh.'),
  ('c5caae15-7e3a-5bc7-a5ef-849da9a1fea9', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 11, 11, 'Prostitution, wine, and new wine take away understanding.'),
  ('b21434cd-37f3-596a-a931-ad97a6d008d5', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 12, 12, 'My people consult with their wooden idol, and answer to a stick of wood. Indeed the spirit of prostitution has led them astray, and they have been unfaithful to their God.'),
  ('981e2e7a-aca4-5e13-a055-8adb189eb8b9', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 13, 13, 'They sacrifice on the tops of the mountains, and burn incense on the hills, under oaks and poplars and terebinths, because its shade is good. Therefore your daughters play the prostitute, and your brides commit adultery.'),
  ('e0b22ea5-8ec2-57b2-a535-861bf232d7aa', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 14, 14, 'I will not punish your daughters when they play the prostitute, nor your brides when they commit adultery; because the men consort with prostitutes, and they sacrifice with the shrine prostitutes; so the people without understanding will come to ruin.'),
  ('68913992-7cb8-5e95-ae5f-035656de7578', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 15, 15, '"Though you, Israel, play the prostitute, yet don''t let Judah offend; and don''t come to Gilgal, neither go up to Beth Aven, nor swear, ''As Yahweh lives.'''),
  ('da204005-76c4-5634-a413-8c76cf3ead1b', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 16, 16, 'For Israel has behaved extremely stubbornly, like a stubborn heifer. Then how will Yahweh feed them like a lamb in a meadow.'),
  ('34b3e4a1-5e59-58af-a0a0-28b1fa4e13e2', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 17, 17, 'Ephraim is joined to idols. Leave him alone!'),
  ('4ac4df43-4d16-5934-aa87-68398f29ba80', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 18, 18, 'Their drink has become sour. They play the prostitute continually. Her rulers dearly love their shameful way.'),
  ('b1b0b82a-f372-5bd0-a4a3-d9b8538bb78b', 'afc4af1c-4904-556b-af2d-2132952fdb16', NULL, 19, 19, 'The wind has wrapped her up in its wings; and they shall be disappointed because of their sacrifices.'),
  ('f9f71f5d-64fa-5078-aa4d-74b874283740', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 1, 1, '"Listen to this, you priests! Listen, house of Israel, and give ear, house of the king! For the judgment is against you; for you have been a snare at Mizpah, and a net spread on Tabor.'),
  ('c89f360a-8e4a-5133-a083-452e71ab530e', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 2, 2, 'The rebels are deep in slaughter; but I discipline all of them.'),
  ('418b6b21-49be-5f50-a289-ed0accf726f6', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 3, 3, 'I know Ephraim, and Israel is not hidden from me; for now, Ephraim, you have played the prostitute. Israel is defiled.'),
  ('da13cf1d-eb4b-53ae-a9c4-d29424b92fdf', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 4, 4, 'Their deeds won''t allow them to turn to their God; for the spirit of prostitution is within them, and they don''t know Yahweh.'),
  ('139e305c-9587-5b39-a98d-7e082f4da6b6', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 5, 5, 'The pride of Israel testifies to his face. Therefore Israel and Ephraim will stumble in their iniquity. Judah also will stumble with them.'),
  ('699d1568-f511-5a80-adbe-86d32be34c93', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 6, 6, 'They will go with their flocks and with their herds to seek Yahweh; but they won''t find him. He has withdrawn himself from them.'),
  ('d240de94-8e82-51dd-ac2e-b18b768e34da', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 7, 7, 'They are unfaithful to Yahweh; for they have borne illegitimate children. Now the new moon will devour them with their fields.'),
  ('822d63da-1474-56dc-abe1-86ba53136618', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 8, 8, '"Blow the cornet in Gibeah, and the trumpet in Ramah! Sound a battle cry at Beth Aven, behind you, Benjamin!'),
  ('af070577-0b1b-57e7-a65f-a6767eb12783', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 9, 9, 'Ephraim will become a desolation in the day of rebuke. Among the tribes of Israel, I have made known that which will surely be.'),
  ('823f3934-0ebf-5110-a29c-33933acdcef3', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 10, 10, 'The princes of Judah are like those who remove a landmark. I will pour out my wrath on them like water.'),
  ('28eafad2-764f-5c6b-a87d-3437a6b1abaa', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 11, 11, 'Ephraim is oppressed, he is crushed in judgment; Because he is intent in his pursuit of idols.'),
  ('6caafd62-54cd-5453-a6a8-55a2e95de34a', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 12, 12, 'Therefore I am to Ephraim like a moth, and to the house of Judah like rottenness.'),
  ('a6c547d3-93d0-5843-a8cb-37bacd17b227', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 13, 13, '"When Ephraim saw his sickness, and Judah his wound, Then Ephraim went to Assyria, and sent to king Jareb: but he is not able to heal you, neither will he cure you of your wound.'),
  ('d0cbdef2-95a4-52a3-a98a-dd8243466edf', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 14, 14, 'For I will be to Ephraim like a lion, and like a young lion to the house of Judah. I myself will tear in pieces and go away. I will carry off, and there will be no one to deliver.'),
  ('f1113a3b-441b-548d-a6f7-10c74c87aef5', 'e0ebc547-4352-5220-a3c5-817154755a71', NULL, 15, 15, 'I will go and return to my place, until they acknowledge their offense, and seek my face. In their affliction they will seek me earnestly."'),
  ('95e6e4ae-e802-5d6f-a8c4-0da7845f6383', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 1, 1, '"Come, and let us return to Yahweh; for he has torn us to pieces, and he will heal us; he has injured us, and he will bind up our wounds.'),
  ('a9c702e9-bc76-521d-a66b-9bcf285b0436', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 2, 2, 'After two days he will revive us. On the third day he will raise us up, and we will live before him.'),
  ('2049611f-f7f1-58d9-aeba-0ef48c921b57', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 3, 3, 'Let us acknowledge Yahweh. Let us press on to know Yahweh. As surely as the sun rises, Yahweh will appear. He will come to us like the rain, like the spring rain that waters the earth."'),
  ('76e9fd3d-f1a6-5ac2-a90e-bb5751ebdf1b', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 4, 4, '"Ephraim, what shall I do to you? Judah, what shall I do to you? For your love is like a morning cloud, and like the dew that disappears early.'),
  ('5ff13d08-9bbc-59b8-a411-dad6a13cbbc6', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 5, 5, 'Therefore I have cut them to pieces with the prophets; I killed them with the words of my mouth. Your judgments are like a flash of lightning.'),
  ('09bfdb43-9645-5880-a357-d2c6ce5a7a3f', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 6, 6, 'For I desire mercy, and not sacrifice; and the knowledge of God more than burnt offerings.'),
  ('e869a994-19b6-5976-adde-c9b01754df63', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 7, 7, 'But they, like Adam, have broken the covenant. They were unfaithful to me, there.'),
  ('187e042c-b029-5f85-a4bf-db5b48c2eca3', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 8, 8, 'Gilead is a city of those who work iniquity; it is stained with blood.'),
  ('f432b930-cbdf-5c36-a384-2f6d454bbc61', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 9, 9, 'As gangs of robbers wait to ambush a man, so the company of priests murder in the way toward Shechem, committing shameful crimes.'),
  ('4c353454-730e-5786-a9bd-32d6ce845031', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 10, 10, 'In the house of Israel I have seen a horrible thing. There is prostitution in Ephraim. Israel is defiled.'),
  ('ef05b9b2-f938-58e5-a209-1de75d8a2be0', '87821cdf-b87c-53f9-ab6b-7eb046582957', NULL, 11, 11, '"Also, Judah, there is a harvest appointed for you, when I restore the fortunes of my people.'),
  ('1983e9ef-7a0f-59f1-a733-ab8ff04e8c6f', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 1, 1, 'When I would heal Israel, then the iniquity of Ephraim is uncovered, also the wickedness of Samaria; for they commit falsehood, and the thief enters in, and the gang of robbers ravages outside.'),
  ('1430953b-f7d2-5b26-ac04-f12ab422caa3', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 2, 2, 'They don''t consider in their hearts that I remember all their wickedness. Now their own deeds have engulfed them. They are before my face.'),
  ('ff4fc1ab-e697-59d0-aabf-f1a405802288', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 3, 3, 'They make the king glad with their wickedness, and the princes with their lies.'),
  ('4981b637-1fb8-588b-aeaf-44e6d1bc5453', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 4, 4, 'They are all adulterers. They are burning like an oven that the baker stops stirring, from the kneading of the dough, until it is leavened.'),
  ('cc34cadc-c83e-528f-ae66-6cdab3b4c2eb', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 5, 5, 'On the day of our king, the princes made themselves sick with the heat of wine. He joined his hand with mockers.'),
  ('5aa97af6-9e85-590d-a2d1-61b90a8b10b8', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 6, 6, 'For they have prepared their heart like an oven, while they lie in wait. Their baker sleeps all the night. In the morning it burns as a flaming fire.'),
  ('8b01ab9e-b425-586a-a8c7-20a120359a12', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 7, 7, 'They are all hot as an oven, and devour their judges. All their kings have fallen. There is no one among them who calls to me.'),
  ('172f402b-d64e-54b1-ab17-7e1bc3964f77', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 8, 8, 'Ephraim, he mixes himself among the nations. Ephraim is a pancake not turned over.'),
  ('bbd99090-da3f-5b5a-a448-2960dbb0a5f4', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 9, 9, 'Strangers have devoured his strength, and he doesn''t realize it. Indeed, gray hairs are here and there on him, and he doesn''t realize it.'),
  ('33db2a61-d3e8-500a-ae5b-a6a008141add', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 10, 10, 'The pride of Israel testifies to his face; yet they haven''t returned to Yahweh their God, nor sought him, for all this.'),
  ('0eea510b-6030-554d-ae0f-52249b0661b0', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 11, 11, '"Ephraim is like an easily deceived dove, without understanding. They call to Egypt. They go to Assyria.'),
  ('86a5194d-ae1d-552f-a478-6c2bf370082e', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 12, 12, 'When they go, I will spread my net on them. I will bring them down like the birds of the sky. I will chastise them, as their congregation has heard.'),
  ('6ce13cf3-652b-5ad3-a6e5-45cb6a449dbd', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 13, 13, 'Woe to them! For they have wandered from me. Destruction to them! For they have trespassed against me. Though I would redeem them, yet they have spoken lies against me.'),
  ('977f054e-cf05-5974-ab73-51f251f8693b', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 14, 14, 'They haven''t cried to me with their heart, but they howl on their beds. They assemble themselves for grain and new wine. They turn away from me.'),
  ('6ac697c4-6ffc-564d-a73d-f2de86833328', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 15, 15, 'Though I have taught and strengthened their arms, yet they plot evil against me.'),
  ('920a0dc2-bd80-5bae-ae3d-e9055b6bd809', '9fc4c243-7ad2-5a38-afca-52424b6d4beb', NULL, 16, 16, 'They return, but not to the Most High. They are like a faulty bow. Their princes will fall by the sword for the rage of their tongue. This will be their derision in the land of Egypt.'),
  ('440cba73-2b06-5375-a167-6dba51e19eb9', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 1, 1, '"Put the trumpet to your lips! Something like an eagle is over Yahweh''s house, because they have broken my covenant, and rebelled against my law.'),
  ('2cc64785-ffe4-5928-a5b7-e60c1185465a', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 2, 2, 'They cry to me, ''My God, we Israel acknowledge you!'''),
  ('ef0d4332-289c-541a-a7e8-7b5aa7df3a8a', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 3, 3, 'Israel has cast off that which is good. The enemy will pursue him.'),
  ('c6d982f5-90cc-5f62-a843-d3d071595bf9', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 4, 4, 'They have set up kings, but not by me. They have made princes, and I didn''t approve. Of their silver and their gold they have made themselves idols, that they may be cut off.'),
  ('411fdea5-0f2d-512e-a639-6c97e0dd4b45', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 5, 5, 'Let Samaria throw out his calf idol! My anger burns against them! How long will it be until they are capable of purity?'),
  ('d9aa547b-fd3f-5601-ac6e-cbcb750d6211', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 6, 6, 'For this is even from Israel! The workman made it, and it is no God; indeed, the calf of Samaria shall be broken in pieces.'),
  ('870db35a-0f14-5bfb-ab83-3ff8117d3fa3', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 7, 7, 'For they sow the wind, and they will reap the whirlwind. He has no standing grain. The stalk will yield no head. If it does yield, strangers will swallow it up.'),
  ('74542095-484b-57be-a79a-59732dd3a2e4', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 8, 8, 'Israel is swallowed up. Now they are among the nations like a worthless thing.'),
  ('745d5456-1de3-5b51-af48-2919cae40147', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 9, 9, 'For they have gone up to Assyria, like a wild donkey wandering alone. Ephraim has hired lovers for himself.'),
  ('37a5e697-347b-5bb8-a4c9-c594392cd615', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 10, 10, 'But although they sold themselves among the nations, I will now gather them; and they begin to waste away because of the oppression of the king of mighty ones.'),
  ('78475b56-7235-5f4e-a235-e037ab27e51c', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 11, 11, 'Because Ephraim has multiplied altars for sinning, they became for him altars for sinning.'),
  ('c6ca54fa-6cd2-54d7-a7c8-4c147d8f4d40', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 12, 12, 'I wrote for him the many things of my law; but they were regarded as a strange thing.'),
  ('c9b70292-5a39-5db7-adc5-94d917f8189a', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 13, 13, 'As for the sacrifices of my offerings, they sacrifice flesh and eat it; But Yahweh doesn''t accept them. Now he will remember their iniquity, and punish their sins. They will return to Egypt.'),
  ('248fd95f-628d-5a51-ab3b-6b4aaa854253', 'db117fcf-99ae-5e4b-aeb5-2861d5ebab91', NULL, 14, 14, 'For Israel has forgotten his Maker and built palaces; and Judah has multiplied fortified cities; but I will send a fire on his cities, and it will devour its fortresses."'),
  ('b00d5b74-e8bf-5d76-a93d-6dd42d9bf252', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 1, 1, 'Don''t rejoice, Israel, to jubilation like the nations; for you were unfaithful to your God. You love the wages of a prostitute at every grain threshing floor.'),
  ('19ed6207-fe2f-509e-a160-70a379eea92c', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 2, 2, 'The threshing floor and the winepress won''t feed them, and the new wine will fail her.'),
  ('dfd6951f-6c40-5a1d-a86d-3e011afb6094', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 3, 3, 'They won''t dwell in Yahweh''s land; but Ephraim will return to Egypt, and they will eat unclean food in Assyria.'),
  ('fb24cd32-2ecc-57aa-a858-2974eb59707a', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 4, 4, 'They won''t pour out wine offerings to Yahweh, neither will they be pleasing to him. Their sacrifices will be to them like the bread of mourners; all who eat of it will be polluted; for their bread will be for their appetite. It will not come into the house of Yahweh.'),
  ('7dcfa6a3-b35a-5025-a9b3-545725811355', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 5, 5, 'What will you do in the day of solemn assembly, and in the day of the feast of Yahweh?'),
  ('cd80b2d2-e87c-56e5-aafb-d15c8f4e4ac7', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 6, 6, 'For, behold, they have gone away from destruction. Egypt will gather them up. Memphis will bury them. Nettles will possess their pleasant things of silver. Thorns will be in their tents.'),
  ('30a822e4-ba61-5287-ae7c-f0f941efef60', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 7, 7, 'The days of visitation have come. The days of reckoning have come. Israel will consider the prophet to be a fool, and the man who is inspired to be insane, because of the abundance of your sins, and because your hostility is great.'),
  ('7734df18-c9b5-5a10-a0d7-2e5907660991', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 8, 8, 'A prophet watches over Ephraim with my God. A fowler''s snare is on all of his paths, and hostility in the house of his God.'),
  ('97ffb3a9-571b-5505-a28a-b5f14ec3547c', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 9, 9, 'They have deeply corrupted themselves, as in the days of Gibeah. He will remember their iniquity. He will punish them for their sins.'),
  ('6a7c873d-6acb-5318-a744-14f818346bb6', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 10, 10, 'I found Israel like grapes in the wilderness. I saw your fathers as the first ripe in the fig tree at its first season; but they came to Baal Peor, and consecrated themselves to the shameful thing, and became abominable like that which they loved.'),
  ('edc8ad9b-8b84-5c53-a3f6-544c43544efe', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 11, 11, 'As for Ephraim, their glory will fly away like a bird. There will be no birth, none with child, and no conception.'),
  ('e03b47c5-c3ac-536a-a5e1-658907353a16', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 12, 12, 'Though they bring up their children, yet I will bereave them, so that not a man shall be left. Indeed, woe also to them when I depart from them!'),
  ('4d657b64-5749-5943-ad09-d0dba5f9323d', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 13, 13, 'I have seen Ephraim, like Tyre, planted in a pleasant place; but Ephraim will bring out his children to the murderer.'),
  ('9d462776-9a1c-52d6-a701-0f36a94ef4b1', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 14, 14, 'Give them--Yahweh what will you give? Give them a miscarrying womb and dry breasts.'),
  ('082adf40-cbf0-5977-a423-c22e6a34377a', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 15, 15, '"All their wickedness is in Gilgal; for there I hated them. Because of the wickedness of their deeds I will drive them out of my house! I will love them no more. All their princes are rebels.'),
  ('dee1867c-7e03-59e4-a8fc-bffdaf6364f5', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 16, 16, 'Ephraim is struck. Their root has dried up. They will bear no fruit. Even though they bring forth, yet I will kill the beloved ones of their womb."'),
  ('10c3a230-0303-5ba3-aec8-e7a7efcc4bcf', '9b1d9b18-6d86-57a8-ae15-74dc5658a444', NULL, 17, 17, 'My God will cast them away, because they did not listen to him; and they will be wanderers among the nations.'),
  ('fee496f0-8fa7-5c9d-a70d-40dfde9c0436', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 1, 1, 'Israel is a luxuriant vine that puts forth his fruit. According to the abundance of his fruit he has multiplied his altars. As their land has prospered, they have adorned their sacred stones.'),
  ('d56c448a-404f-5ba7-a1a9-f51c64da366b', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 2, 2, 'Their heart is divided. Now they will be found guilty. He will demolish their altars. He will destroy their sacred stones.'),
  ('c5e94e21-9f1f-534b-a50b-2c0652eb2af8', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 3, 3, 'Surely now they will say, "We have no king; for we don''t fear Yahweh; and the king, what can he do for us?"'),
  ('1f61d1f3-20c8-5792-ab01-68855a20a63d', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 4, 4, 'They make promises, swearing falsely in making covenants. Therefore judgment springs up like poisonous weeds in the furrows of the field.'),
  ('52365727-f42e-5ecb-a511-de565d6dac35', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 5, 5, 'The inhabitants of Samaria will be in terror for the calves of Beth Aven; for its people will mourn over it, Along with its priests who rejoiced over it, for its glory, because it has departed from it.'),
  ('c08c36b8-c99b-5412-ac0e-3b2af3dc5e58', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 6, 6, 'It also will be carried to Assyria for a present to a great king. Ephraim will receive shame, and Israel will be ashamed of his own counsel.'),
  ('6ae5e6de-d16f-590c-a712-8ff3e4e56052', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 7, 7, 'Samaria and her king float away, like a twig on the water.'),
  ('9b1e22fa-032a-5bf8-ade7-bc1e3a785e9a', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 8, 8, 'The high places also of Aven, the sin of Israel, will be destroyed. The thorn and the thistle will come up on their altars. They will tell the mountains, "Cover us!" and the hills, "Fall on us!"'),
  ('642ac7d4-3fce-5605-a4a2-2c822dc597f8', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 9, 9, '"Israel, you have sinned from the days of Gibeah. There they remained. The battle against the children of iniquity doesn''t overtake them in Gibeah.'),
  ('5c882de2-3e04-5937-a8fb-8d86eb8b4d95', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 10, 10, 'When it is my desire, I will chastise them; and the nations will be gathered against them, when they are bound to their two transgressions.'),
  ('bfbc8132-90e1-507d-a972-f35c0386f7ce', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 11, 11, 'Ephraim is a trained heifer that loves to thresh; so I will put a yoke on her beautiful neck. I will set a rider on Ephraim. Judah will plow. Jacob will break his clods.'),
  ('560fcdff-016c-5178-a871-f3e3228b25f9', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 12, 12, 'Sow to yourselves in righteousness, reap according to kindness. Break up your fallow ground; for it is time to seek Yahweh, until he comes and rains righteousness on you.'),
  ('10dbf923-c031-5730-a66b-5a23f4023127', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 13, 13, 'You have plowed wickedness. You have reaped iniquity. You have eaten the fruit of lies, for you trusted in your way, in the multitude of your mighty men.'),
  ('2cebd21a-29d4-56be-a22b-f2672fa4ae0e', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 14, 14, 'Therefore a battle roar will arise among your people, and all your fortresses will be destroyed, as Shalman destroyed Beth Arbel in the day of battle. The mother was dashed in pieces with her children.'),
  ('3b498491-5cf8-58ba-a99e-0a59ef83558c', 'b818e222-a50e-582c-a47b-16cc53982330', NULL, 15, 15, 'So Bethel will do to you because of your great wickedness. At daybreak the king of Israel will be destroyed.'),
  ('4af82875-894f-55c6-aa79-be22054ad3bd', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 1, 1, '"When Israel was a child, then I loved him, and called my son out of Egypt.'),
  ('6c1b9e96-d9a3-5872-a681-69aa80ebfc07', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 2, 2, 'They called to them, so they went from them. They sacrificed to the Baals, and burned incense to engraved images.'),
  ('6014b812-026b-5059-a37c-5e2a2cb5ca69', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 3, 3, 'Yet I taught Ephraim to walk. I took them by his arms; but they didn''t know that I healed them.'),
  ('75ed0a62-7248-59cd-af8e-8a0ead966ee0', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 4, 4, 'I drew them with cords of a man, with ties of love; and I was to them like those who lift up the yoke on their necks; and I bent down to him and I fed him.'),
  ('5ce94a06-4f97-5713-acbf-ecbd657838aa', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 5, 5, '"They won''t return into the land of Egypt; but the Assyrian will be their king, because they refused to repent.'),
  ('85bb8887-ad82-5fc7-a7f9-b61e1168fd9c', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 6, 6, 'The sword will fall on their cities, and will destroy the bars of their gates, and will put an end to their plans.'),
  ('64ad6ae4-7422-50cb-a9b5-80751d14c9f3', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 7, 7, 'My people are determined to turn from me. Though they call to the Most High, he certainly won''t exalt them.'),
  ('91e80c7b-3fc6-50c0-acca-13b0cfcac96c', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 8, 8, '"How can I give you up, Ephraim? How can I hand you over, Israel? How can I make you like Admah? How can I make you like Zeboiim? My heart is turned within me, my compassion is aroused.'),
  ('9c4b133b-b434-5f1a-af01-8059e30fb19a', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 9, 9, 'I will not execute the fierceness of my anger. I will not return to destroy Ephraim: for I am God, and not man; the Holy One in the midst of you; and I will not come in wrath.'),
  ('133fb180-8213-5a09-aeb9-7ac3a8391785', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 10, 10, 'They will walk after Yahweh, who will roar like a lion; for he will roar, and the children will come trembling from the west.'),
  ('d3a3089c-fcc0-5e89-a09f-627081490fdb', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 11, 11, 'They will come trembling like a bird out of Egypt, and like a dove out of the land of Assyria; and I will settle them in their houses," says Yahweh.'),
  ('b0e97193-9d59-5e42-af3b-c733230bbd82', 'c0d58bc8-007a-58d3-ae0b-7b16fb4193f1', NULL, 12, 12, 'Ephraim surrounds me with falsehood, and the house of Israel with deceit. Judah still strays from God, and is unfaithful to the Holy One.'),
  ('323b75d6-157c-54c9-a637-d42a8598f2a2', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 1, 1, 'Ephraim feeds on wind, and chases the east wind. He continually multiplies lies and desolation. They make a covenant with Assyria, and oil is carried into Egypt.'),
  ('fcfe9c50-5c54-5e5c-a4b6-4fc88893cde8', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 2, 2, 'Yahweh also has a controversy with Judah, and will punish Jacob according to his ways; according to his deeds he will repay him.'),
  ('44880772-b48a-55d3-a2af-4512b57de5e1', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 3, 3, 'In the womb he took his brother by the heel; and in his manhood he contended with God.'),
  ('caf2ecbc-cd10-59da-acc7-32c6788f2ba8', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 4, 4, 'Indeed, he struggled with the angel, and prevailed; he wept, and made supplication to him. He found him at Bethel, and there he spoke with us,'),
  ('71227462-af45-5b03-abca-7e96411d8791', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 5, 5, 'even Yahweh, the God of Armies; Yahweh is his name of renown!'),
  ('2e862145-6dd5-5175-a9f1-39fdbe7ffa4c', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 6, 6, 'Therefore turn to your God. Keep kindness and justice, and wait continually for your God.'),
  ('d0edd87c-3cb2-52d6-abb2-cf37543fa248', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 7, 7, 'A merchant has dishonest scales in his hand. He loves to defraud.'),
  ('82fdf249-efb6-55f3-acd6-dfb07c455b74', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 8, 8, 'Ephraim said, "Surely I have become rich, I have found myself wealth. In all my wealth they won''t find in me any iniquity that is sin."'),
  ('01b4c348-641a-507b-a542-044cac9b93dc', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 9, 9, '"But I am Yahweh your God from the land of Egypt. I will yet again make you dwell in tents, as in the days of the solemn feast.'),
  ('279141ad-b2bc-5ca4-a091-825d119940f2', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 10, 10, 'I have also spoken to the prophets, and I have multiplied visions; and by the ministry of the prophets I have used parables.'),
  ('b90a9604-ad80-5532-a0c5-d60745aad05a', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 11, 11, 'If Gilead is wicked, surely they are worthless. In Gilgal they sacrifice bulls. Indeed, their altars are like heaps in the furrows of the field.'),
  ('980d23b0-0bee-5f3f-a0e3-71b49ae9fb0c', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 12, 12, 'Jacob fled into the country of Aram, and Israel served to get a wife, and for a wife he tended flocks and herds.'),
  ('cfd8b213-f4fd-522f-a2f7-dc31280d855a', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 13, 13, 'By a prophet Yahweh brought Israel up out of Egypt, and by a prophet he was preserved.'),
  ('aba1935a-06c3-50e0-aef3-cc4a25404173', '651594f6-6bb1-5d5a-ae78-da467f369682', NULL, 14, 14, 'Ephraim has bitterly provoked anger. Therefore his blood will be left on him, and his Lord will repay his contempt.'),
  ('df89600a-1350-544f-a6e3-a2a01bee0c5f', '91949358-6175-548e-a836-c66ba9921f32', NULL, 1, 1, 'When Ephraim spoke, there was trembling. He exalted himself in Israel, but when he became guilty in Baal, he died.'),
  ('9de73b81-4c4f-57bb-a711-434a2842a140', '91949358-6175-548e-a836-c66ba9921f32', NULL, 2, 2, 'Now they sin more and more, and have made themselves molten images of their silver, even idols according to their own understanding, all of them the work of the craftsmen. They say of them, ''They offer human sacrifice and kiss the calves.'''),
  ('8a734a62-8871-5075-a9a0-1cba7f8a99bc', '91949358-6175-548e-a836-c66ba9921f32', NULL, 3, 3, 'Therefore they will be like the morning mist, and like the dew that passes away early, like the chaff that is driven with the whirlwind out of the threshing floor, and like the smoke out of the chimney.'),
  ('2e28545d-cefc-544a-a167-cbfd157a033c', '91949358-6175-548e-a836-c66ba9921f32', NULL, 4, 4, '"Yet I am Yahweh your God from the land of Egypt; and you shall acknowledge no god but me, and besides me there is no savior.'),
  ('31116b6a-04c5-57d7-ae8e-63367b3122e2', '91949358-6175-548e-a836-c66ba9921f32', NULL, 5, 5, 'I knew you in the wilderness, in the land of great drought.'),
  ('d823368d-ad3e-5443-acde-f5b085c77ae2', '91949358-6175-548e-a836-c66ba9921f32', NULL, 6, 6, 'According to their pasture, so were they filled; they were filled, and their heart was exalted. Therefore they have forgotten me.'),
  ('d053d9a3-9378-5045-a2c2-77f6ec52e017', '91949358-6175-548e-a836-c66ba9921f32', NULL, 7, 7, 'Therefore I am like a lion to them. Like a leopard, I will lurk by the path.'),
  ('05f7ec3e-5bbd-548c-ac25-46040409b3d4', '91949358-6175-548e-a836-c66ba9921f32', NULL, 8, 8, 'I will meet them like a bear that is bereaved of her cubs, and will tear the covering of their heart. There I will devour them like a lioness. The wild animal will tear them.'),
  ('e1c8330a-917c-52f9-a6d1-d276ae0a5248', '91949358-6175-548e-a836-c66ba9921f32', NULL, 9, 9, 'You are destroyed, Israel, because you are against me, against your help.'),
  ('5c18e103-659d-5bc1-af11-17bf020da150', '91949358-6175-548e-a836-c66ba9921f32', NULL, 10, 10, 'Where is your king now, that he may save you in all your cities? And your judges, of whom you said, ''Give me a king and princes?'''),
  ('50e4ef8c-2e5f-50e4-a6d9-09034015b69b', '91949358-6175-548e-a836-c66ba9921f32', NULL, 11, 11, 'I have given you a king in my anger, and have taken him away in my wrath.'),
  ('0a28a2e3-b472-5222-a97f-dbfd1d972950', '91949358-6175-548e-a836-c66ba9921f32', NULL, 12, 12, 'The guilt of Ephraim is stored up. His sin is stored up.'),
  ('f62a5e1e-e987-5f04-abf0-f927bb6e6d32', '91949358-6175-548e-a836-c66ba9921f32', NULL, 13, 13, 'The sorrows of a travailing woman will come on him. He is an unwise son; for when it is time, he doesn''t come to the opening of the womb.'),
  ('39bd7c74-9044-56cc-a4c5-9a44b781ea3d', '91949358-6175-548e-a836-c66ba9921f32', NULL, 14, 14, 'I will ransom them from the power of Sheol. I will redeem them from death! Death, where are your plagues? Sheol, where is your destruction? "Compassion will be hidden from my eyes.'),
  ('808ac327-5a59-5747-a5c8-883c3b41b092', '91949358-6175-548e-a836-c66ba9921f32', NULL, 15, 15, 'Though he is fruitful among his brothers, an east wind will come, the breath of Yahweh coming up from the wilderness; and his spring will become dry, and his fountain will be dried up. He will plunder the storehouse of treasure.'),
  ('acf82fae-7772-508b-a9fe-d2c4a1a0dbcc', '91949358-6175-548e-a836-c66ba9921f32', NULL, 16, 16, 'Samaria will bear her guilt; for she has rebelled against her God. They will fall by the sword. Their infants will be dashed in pieces, and their pregnant women will be ripped open."'),
  ('54ebd8c0-5f6d-5457-a7b9-2d8902a670fc', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 1, 1, 'Israel, return to Yahweh your God; for you have fallen because of your sin.'),
  ('738ace7c-306b-556c-a8a1-e7dd0917c1ae', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 2, 2, 'Take words with you, and return to Yahweh. Tell him, "Forgive all our sins, and accept that which is good: so we offer our lips like bulls.'),
  ('d45e56c6-11bf-5009-ab88-244e28ed8bc6', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 3, 3, 'Assyria can''t save us. We won''t ride on horses; neither will we say any more to the work of our hands, ''Our gods!'' for in you the fatherless finds mercy."'),
  ('23d5f3fc-9d09-51b2-a92d-ea3ee838519c', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 4, 4, '"I will heal their waywardness. I will love them freely; for my anger is turned away from him.'),
  ('57f20964-356e-5681-a882-786f6bc0f284', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 5, 5, 'I will be like the dew to Israel. He will blossom like the lily, and send down his roots like Lebanon.'),
  ('320f23d1-d818-5241-adcc-5b93817229c0', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 6, 6, 'His branches will spread, and his beauty will be like the olive tree, and his fragrance like Lebanon.'),
  ('3fab9adc-1f21-518e-aa5c-4d734da1ae7c', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 7, 7, 'Men will dwell in his shade. They will revive like the grain, and blossom like the vine. Their fragrance will be like the wine of Lebanon.'),
  ('2f437d23-aaa1-5c74-ad8b-202c8d709c65', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 8, 8, 'Ephraim, what have I to do any more with idols? I answer, and will take care of him. I am like a green fir tree; from me your fruit is found."'),
  ('08f4e271-319e-5fcf-afda-073ff3560f48', '34637356-cb2d-53cb-a259-e956f4fa025b', NULL, 9, 9, 'Who is wise, that he may understand these things? Who is prudent, that he may know them? For the ways of Yahweh are right, and the righteous walk in them; But the rebellious stumble in them.'),
  ('109ce204-6c27-58b5-a932-f60ceb7b0c36', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 1, 1, 'The Word of Yahweh that came to Joel, the son of Pethuel.'),
  ('7d0dcc61-54ae-52bf-a259-4c32da811666', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 2, 2, 'Hear this, you elders, And listen, all you inhabitants of the land. Has this ever happened in your days, or in the days of your fathers?'),
  ('c65b64be-44c3-5306-a31a-2b435a95cb8e', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 3, 3, 'Tell your children about it, and have your children tell their children, and their children, another generation.'),
  ('57c356b0-3dd3-52c1-a362-d40e89c3df9a', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 4, 4, 'What the swarming locust has left, the great locust has eaten. What the great locust has left, the grasshopper has eaten. What the grasshopper has left, the caterpillar has eaten.'),
  ('0b866858-03c1-510a-a958-fb353082ab22', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 5, 5, 'Wake up, you drunkards, and weep! Wail, all you drinkers of wine, because of the sweet wine; for it is cut off from your mouth.'),
  ('9af21302-df71-53fe-a1c4-d736a9d1826e', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 6, 6, 'For a nation has come up on my land, strong, and without number. His teeth are the teeth of a lion, and he has the fangs of a lioness.'),
  ('486ec2cf-d9a4-574d-a40c-3fc89c4b56f1', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 7, 7, 'He has laid my vine waste, and stripped my fig tree. He has stripped its bark, and thrown it away. Its branches are made white.'),
  ('a76bcd89-40e7-5fd6-a7f7-6d19519535a4', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 8, 8, 'Mourn like a virgin dressed in sackcloth for the husband of her youth!'),
  ('7881f458-33ea-5f8b-ad8a-3255694b6610', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 9, 9, 'The meal offering and the drink offering are cut off from Yahweh''s house. The priests, Yahweh''s ministers, mourn.'),
  ('8df17ac5-d11d-52e9-a162-f3f3092e3456', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 10, 10, 'The field is laid waste. The land mourns, for the grain is destroyed, The new wine has dried up, and the oil languishes.'),
  ('106d20eb-75f1-5fa0-a8da-2badbbeeadb7', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 11, 11, 'Be confounded, you farmers! Wail, you vineyard keepers; for the wheat and for the barley; for the harvest of the field has perished.'),
  ('1f59d91c-06c1-56d0-aed6-00054f025a73', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 12, 12, 'The vine has dried up, and the fig tree withered; the pomegranate tree, the palm tree also, and the apple tree, even all of the trees of the field are withered; for joy has withered away from the sons of men.'),
  ('d8513d30-217d-561d-af03-f45dc280f1f9', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 13, 13, 'Put on sackcloth and mourn, you priests! Wail, you ministers of the altar. Come, lie all night in sackcloth, you ministers of my God, for the meal offering and the drink offering are withheld from your God''s house.'),
  ('28b4628c-a99a-5bee-aab3-69eb185551b4', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 14, 14, 'Sanctify a fast. Call a solemn assembly. Gather the elders, and all the inhabitants of the land, to the house of Yahweh, your God, and cry to Yahweh.'),
  ('88c39866-fb60-5e78-a2f7-f5693f43ce4a', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 15, 15, 'Alas for the day! For the day of Yahweh is at hand, and it will come as destruction from the Almighty.'),
  ('dbbc9df7-eabb-571e-ab9c-3df4f391a8aa', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 16, 16, 'Isn''t the food cut off before our eyes; joy and gladness from the house of our God?'),
  ('216d9409-853a-5b0b-a6a4-12a93620967c', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 17, 17, 'The seeds rot under their clods. The granaries are laid desolate. The barns are broken down, for the grain has withered.'),
  ('6e408a31-d818-5cdb-a8e7-c2352eadd144', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 18, 18, 'How the animals groan! The herds of livestock are perplexed, because they have no pasture. Yes, the flocks of sheep are made desolate.'),
  ('3fb6ceab-7012-5beb-ae27-4d887ce35136', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 19, 19, 'Yahweh, I cry to you, For the fire has devoured the pastures of the wilderness, and the flame has burned all the trees of the field.'),
  ('3da30acf-96bb-5f8a-a083-c3c83daf3180', '3ba5db4f-876a-5cfc-a542-96c64deda4f9', NULL, 20, 20, 'Yes, the animals of the field pant to you, for the water brooks have dried up, And the fire has devoured the pastures of the wilderness.'),
  ('c18c2b83-9c19-5b1f-a535-f62898edcf48', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 1, 1, 'Blow the trumpet in Zion, and sound an alarm in my holy mountain! Let all the inhabitants of the land tremble, for the day of Yahweh comes, for it is close at hand:'),
  ('a9aec336-9599-5f30-a190-942f54a9db73', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 2, 2, 'A day of darkness and gloominess, a day of clouds and thick darkness. As the dawn spreading on the mountains, a great and strong people; there has never been the like, neither will there be any more after them, even to the years of many generations.'),
  ('87e95419-2ce3-52bc-a525-27dc211ccbcf', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 3, 3, 'A fire devours before them, and behind them, a flame burns. The land is as the garden of Eden before them, and behind them, a desolate wilderness. Yes, and no one has escaped them.'),
  ('157ed183-0405-5c16-a630-416d3f4f1bb1', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 4, 4, 'The appearance of them is as the appearance of horses, and as horsemen, so do they run.'),
  ('1b4cabea-9488-5a54-a7a2-92abe135eb21', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 5, 5, 'Like the noise of chariots on the tops of the mountains do they leap, like the noise of a flame of fire that devours the stubble, as a strong people set in battle array.'),
  ('9e8a0f1a-739c-5a78-a466-4b9b9aceeb0d', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 6, 6, 'At their presence the peoples are in anguish. All faces have grown pale.'),
  ('2333872d-90bc-5baa-ae6f-19de32317cbf', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 7, 7, 'They run like mighty men. They climb the wall like warriors. They each march in his line, and they don''t swerve off course.'),
  ('b1bd3aad-d67c-5c13-aa72-13ce43482f23', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 8, 8, 'Neither does one jostle another; they march everyone in his path, and they burst through the defenses, and don''t break ranks.'),
  ('ca3128d4-c574-51fd-a066-69f2fc108d7e', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 9, 9, 'They rush on the city. They run on the wall. They climb up into the houses. They enter in at the windows like thieves.'),
  ('c233d251-7ad6-54da-a87c-773a1cf637ec', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 10, 10, 'The earth quakes before them. The heavens tremble. The sun and the moon are darkened, and the stars withdraw their shining.'),
  ('e06be47b-b443-59f8-aaae-c0162df2de22', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 11, 11, 'Yahweh thunders his voice before his army; for his forces are very great; for he is strong who obeys his command; for the day of Yahweh is great and very awesome, and who can endure it?'),
  ('58f90dc6-1157-5f73-ab30-abcdcc10be95', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 12, 12, '"Yet even now," says Yahweh, "turn to me with all your heart, and with fasting, and with weeping, and with mourning."'),
  ('d4cc0a7c-4582-5087-ae85-4c64bf07cad4', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 13, 13, 'Tear your heart, and not your garments, and turn to Yahweh, your God; for he is gracious and merciful, slow to anger, and abundant in loving kindness, and relents from sending calamity.'),
  ('998622d9-f729-5d48-a588-3b03b35cdaa7', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 14, 14, 'Who knows? He may turn and relent, and leave a blessing behind him, even a meal offering and a drink offering to Yahweh, your God.'),
  ('acdabee9-41bf-56b1-a43a-f39952a40a51', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 15, 15, 'Blow the trumpet in Zion! Sanctify a fast. Call a solemn assembly.'),
  ('27bf0aff-2547-5ddc-ae74-c4db38328184', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 16, 16, 'Gather the people. Sanctify the assembly. Assemble the elders. Gather the children, and those who nurse from breasts. Let the bridegroom go forth from his room, and the bride out of her room.'),
  ('22b883e8-094a-5bba-a226-d8305479b648', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 17, 17, 'Let the priests, the ministers of Yahweh, weep between the porch and the altar, and let them say, "Spare your people, Yahweh, and don''t give your heritage to reproach, that the nations should rule over them. Why should they say among the peoples, ''Where is their God?''"'),
  ('3856574a-4cfd-5b60-ae45-e77976faa57d', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 18, 18, 'Then Yahweh was jealous for his land, And had pity on his people.'),
  ('09cd4397-b02b-5b4e-a325-2fa398c3319d', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 19, 19, 'Yahweh answered his people, "Behold, I will send you grain, new wine, and oil, and you will be satisfied with them; and I will no more make you a reproach among the nations.'),
  ('e4ba30ac-1b9e-53dd-ab8a-babfd9085767', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 20, 20, 'But I will remove the northern army far away from you, and will drive it into a barren and desolate land, its front into the eastern sea, and its back into the western sea; and its stench will come up, and its bad smell will rise." Surely he has done great things.'),
  ('fd259d48-e313-522a-ad4b-0747cbc7b119', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 21, 21, 'Land, don''t be afraid. Be glad and rejoice, for Yahweh has done great things.'),
  ('d26d5821-981d-5291-a69d-9cea11b73f55', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 22, 22, 'Don''t be afraid, you animals of the field; for the pastures of the wilderness spring up, for the tree bears its fruit. The fig tree and the vine yield their strength.'),
  ('108a1d12-3fd7-56b8-a94e-4b52bb6f656b', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 23, 23, '"Be glad then, you children of Zion, and rejoice in Yahweh, your God; for he gives you the former rain in just measure, and he causes the rain to come down for you, the former rain and the latter rain, as before.'),
  ('6f135501-ea49-5ddd-a338-5e595afddab6', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 24, 24, 'The threshing floors will be full of wheat, and the vats will overflow with new wine and oil.'),
  ('2b097fd6-730d-5dbb-a4eb-4c628639aeee', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 25, 25, 'I will restore to you the years that the swarming locust has eaten, the great locust, the grasshopper, and the caterpillar, my great army, which I sent among you.'),
  ('5235e7eb-2312-5f9f-ae99-d4e3afb7de28', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 26, 26, 'You will have plenty to eat, and be satisfied, and will praise the name of Yahweh, your God, who has dealt wondrously with you; and my people will never again be disappointed.'),
  ('8c011e08-948d-5eb4-a1f3-74d28798c4a1', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 27, 27, 'You will know that I am in the midst of Israel, and that I am Yahweh, your God, and there is no one else; and my people will never again be disappointed.'),
  ('e7e6b5cc-2907-597b-a76d-7b15ed36285f', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 28, 28, '"It will happen afterward, that I will pour out my Spirit on all flesh; and your sons and your daughters will prophesy. Your old men will dream dreams. Your young men will see visions.'),
  ('95a17642-f604-5e4b-ab2c-b29be01b2a2e', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 29, 29, 'And also on the servants and on the handmaids in those days, I will pour out my Spirit.'),
  ('68b455b8-6714-58ce-ab2c-dd455aa3ea6e', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 30, 30, 'I will show wonders in the heavens and in the earth: blood, fire, and pillars of smoke.'),
  ('6e6dbb8e-c441-5b60-af59-432e944528f8', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 31, 31, 'The sun will be turned into darkness, and the moon into blood, before the great and terrible day of Yahweh comes.'),
  ('76bbfba8-85fb-5cce-a17f-472fbb42ac06', '0f8d576a-9ec9-519b-a190-5353846bb14e', NULL, 32, 32, 'It will happen that whoever will call on the name of Yahweh shall be saved; for in Mount Zion and in Jerusalem there will be those who escape, as Yahweh has said, and among the remnant, those whom Yahweh calls.'),
  ('ac066913-053d-57d1-a55f-02c02f3193f0', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 1, 1, '"For, behold, in those days, and in that time, when I restore the fortunes of Judah and Jerusalem,'),
  ('ed1d2ffe-328d-5eef-abf6-72d32863ed9a', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 2, 2, 'I will gather all nations, and will bring them down into the valley of Jehoshaphat; and I will execute judgment on them there for my people, and for my heritage, Israel, whom they have scattered among the nations. They have divided my land,'),
  ('07df2e1a-7e6c-5283-a3df-8b47eb2c9c70', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 3, 3, 'and have cast lots for my people, and have given a boy for a prostitute, and sold a girl for wine, that they may drink.'),
  ('bebbab8e-ae74-549f-aedf-7dc385556018', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 4, 4, '"Yes, and what are you to me, Tyre, and Sidon, and all the regions of Philistia? Will you repay me? And if you repay me, I will swiftly and speedily return your repayment on your own head.'),
  ('59ef1145-0780-54e7-a437-a64733a6792a', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 5, 5, 'Because you have taken my silver and my gold, and have carried my finest treasures into your temples,'),
  ('75c63b33-1f95-53e2-a422-0684894975c4', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 6, 6, 'and have sold the children of Judah and the children of Jerusalem to the sons of the Greeks, that you may remove them far from their border.'),
  ('818f7971-1d4b-55e4-a71f-62baca18f467', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 7, 7, 'Behold, I will stir them up out of the place where you have sold them, and will return your repayment on your own head;'),
  ('4111a618-900d-5bb8-a0c9-9a255c83f7ca', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 8, 8, 'and I will sell your sons and your daughters into the hands of the children of Judah, and they will sell them to the men of Sheba, to a faraway nation, for Yahweh has spoken it."'),
  ('09cc3365-7484-5cf6-a486-067c0c50d031', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 9, 9, 'Proclaim this among the nations: "Prepare for war! Stir up the mighty men. Let all the warriors draw near. Let them come up.'),
  ('e4dce50d-689c-5d7c-a969-f4bb03a52b80', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 10, 10, 'Beat your plowshares into swords, and your pruning hooks into spears. Let the weak say, ''I am strong.'''),
  ('daa800cf-dff1-5a9a-a3b3-b70ec0b0aecd', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 11, 11, 'Hurry and come, all you surrounding nations, and gather yourselves together." Cause your mighty ones to come down there, Yahweh.'),
  ('18c64906-5b6b-523b-a868-beb2ebe38eb9', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 12, 12, '"Let the nations arouse themselves, and come up to the valley of Jehoshaphat; for there will I sit to judge all the surrounding nations.'),
  ('503b0e87-f6c5-5719-a29e-741e37ef1015', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 13, 13, 'Put in the sickle; for the harvest is ripe. Come, tread, for the winepress is full, the vats overflow, for their wickedness is great."'),
  ('81c4287b-2e6a-570d-a654-4ea1e604904f', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 14, 14, 'Multitudes, multitudes in the valley of decision! For the day of Yahweh is near, in the valley of decision.'),
  ('88cca67a-2f69-5514-aed0-4c6e0a1436d6', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 15, 15, 'The sun and the moon are darkened, and the stars withdraw their shining.'),
  ('6fabcb13-fc24-5487-abf9-0914480b375a', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 16, 16, 'Yahweh will roar from Zion, and thunder from Jerusalem; and the heavens and the earth will shake; but Yahweh will be a refuge to his people, and a stronghold to the children of Israel.'),
  ('bae0c690-bf84-573c-ab44-4fe61ea54468', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 17, 17, '"So you will know that I am Yahweh, your God, dwelling in Zion, my holy mountain. Then Jerusalem will be holy, and no strangers will pass through her any more.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ad302ba6-0287-52f1-aefd-02b947c87971', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 18, 18, 'It will happen in that day, that the mountains will drop down sweet wine, the hills will flow with milk, all the brooks of Judah will flow with waters, and a fountain will come forth from the house of Yahweh, and will water the valley of Shittim.'),
  ('e2694d9f-36e9-5dd4-aedd-3be555b7c0ba', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 19, 19, 'Egypt will be a desolation, and Edom will be a desolate wilderness, for the violence done to the children of Judah, because they have shed innocent blood in their land.'),
  ('c7664dc8-263d-56b5-a610-7225f06b5e3a', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 20, 20, 'But Judah will be inhabited forever, and Jerusalem from generation to generation.'),
  ('d2d2c7e4-4e1c-5dec-a667-73be7da13df2', 'f907bab3-2b1c-5fe8-a923-ab883346c5a5', NULL, 21, 21, 'I will cleanse their blood, that I have not cleansed: for Yahweh dwells in Zion."'),
  ('3669fa00-a33d-51ca-a788-08a6456f6005', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 1, 1, 'The words of Amos, who was among the herdsmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah, and in the days of Jeroboam the son of Joash king of Israel, two years before the earthquake.'),
  ('85e45db4-837e-55e3-a4fe-6896afe68b33', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 2, 2, 'He said: "Yahweh will roar from Zion, and utter his voice from Jerusalem; and the pastures of the shepherds will mourn, and the top of Carmel will wither."'),
  ('32949b25-847a-5fb7-af15-19e2088d5e49', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 3, 3, 'Thus says Yahweh: "For three transgressions of Damascus, yes, for four, I will not turn away its punishment; because they have threshed Gilead with threshing instruments of iron;'),
  ('f888acb9-148f-5e56-a427-1c79a8164c25', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 4, 4, 'but I will send a fire into the house of Hazael, and it will devour the palaces of Ben Hadad.'),
  ('dab7529a-59d8-5ce7-a218-3d7c50db2a5b', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 5, 5, 'I will break the bar of Damascus, and cut off the inhabitant from the valley of Aven, and him who holds the scepter from the house of Eden; and the people of Syria shall go into captivity to Kir," says Yahweh.'),
  ('15902a61-06f2-59a6-ada3-63e435d58d8e', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 6, 6, 'Thus says Yahweh: "For three transgressions of Gaza, yes, for four, I will not turn away its punishment; because they carried away captive the whole community, to deliver them up to Edom;'),
  ('04ec7b13-ea59-5397-afe4-51560633f4b4', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 7, 7, 'but I will send a fire on the wall of Gaza, and it will devour its palaces.'),
  ('8ec19e6b-3fd4-543b-a7d8-2129171759e1', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 8, 8, 'I will cut off the inhabitant from Ashdod, and him who holds the scepter from Ashkelon; and I will turn my hand against Ekron; and the remnant of the Philistines will perish," says the Lord Yahweh.'),
  ('eee36972-eae9-50d8-a9cf-a7d0021f9262', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 9, 9, 'Thus says Yahweh: "For three transgressions of Tyre, yes, for four, I will not turn away its punishment; because they delivered up the whole community to Edom, and didn''t remember the brotherly covenant;'),
  ('b7795978-5024-5d41-a3c7-97121ecfb7fa', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 10, 10, 'but I will send a fire on the wall of Tyre, and it will devour its palaces."'),
  ('95d1c227-7b75-51af-a0f9-ebbea70860b0', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 11, 11, 'Thus says Yahweh: "For three transgressions of Edom, yes, for four, I will not turn away its punishment; because he pursued his brother with the sword, and cast off all pity, and his anger raged continually, and he kept his wrath forever;'),
  ('39324bdc-28ad-5b63-a729-dac3bc23c5e9', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 12, 12, 'but I will send a fire on Teman, and it will devour the palaces of Bozrah."'),
  ('16ba4d1d-2975-5103-a3ac-e5b9c2e23f23', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 13, 13, 'Thus says Yahweh: "For three transgressions of the children of Ammon, yes, for four, I will not turn away its punishment; because they have ripped open the pregnant women of Gilead, that they may enlarge their border.'),
  ('82229fe4-22ac-5bbd-ab53-62fe8e252c88', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 14, 14, 'But I will kindle a fire in the wall of Rabbah, and it will devour its palaces, with shouting in the day of battle, with a storm in the day of the whirlwind;'),
  ('fcc5cba0-b677-5bf7-a896-9b0ae11d34c2', 'f15a47eb-d1cb-51f9-a75d-758c28f5b670', NULL, 15, 15, 'and their king will go into captivity, he and his princes together," says Yahweh.'),
  ('8fc4d72f-4a0c-5b8a-a419-9d54490b488f', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 1, 1, 'Thus says Yahweh: "For three transgressions of Moab, yes, for four, I will not turn away its punishment; because he burned the bones of the king of Edom into lime;'),
  ('153cbe0d-b302-56c5-aeda-017dcd5b245e', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 2, 2, 'but I will send a fire on Moab, and it will devour the palaces of Kerioth; and Moab will die with tumult, with shouting, and with the sound of the trumpet;'),
  ('58d33866-ce2a-590f-a6d7-a4541b0f8169', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 3, 3, 'and I will cut off the judge from their midst, and will kill all its princes with him," says Yahweh.'),
  ('5141c11b-83d5-5d1d-a905-37d740e1b80f', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 4, 4, 'Thus says Yahweh: "For three transgressions of Judah, yes, for four, I will not turn away its punishment; because they have rejected Yahweh''s law, and have not kept his statutes, and their lies have led them astray, after which their fathers walked;'),
  ('52016243-a525-5ec3-adbb-4458fe99f231', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 5, 5, 'But I will send a fire on Judah, and it will devour the palaces of Jerusalem."'),
  ('0e27f98f-f9cd-56cb-a6ad-b79113f468e2', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 6, 6, 'Thus says Yahweh: "For three transgressions of Israel, yes, for four, I will not turn away its punishment; because they have sold the righteous for silver, and the needy for a pair of shoes;'),
  ('c89ef4cc-cc98-5d8e-a519-ac00bd967949', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 7, 7, 'They trample on the dust of the earth on the head of the poor, and deny justice to the oppressed; and a man and his father use the same maiden, to profane my holy name;'),
  ('25ea1a7d-d4e1-5bef-a468-607c3898daad', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 8, 8, 'and they lay themselves down beside every altar on clothes taken in pledge; and in the house of their God they drink the wine of those who have been fined.'),
  ('08f94877-3d6a-529d-a272-e01b6ce0e9a7', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 9, 9, 'Yet I destroyed the Amorite before them, whose height was like the height of the cedars, and he was strong as the oaks; yet I destroyed his fruit from above, and his roots from beneath.'),
  ('cf627f49-2f8a-5973-a9f9-8dcce2fb3056', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 10, 10, 'Also I brought you up out of the land of Egypt, and led you forty years in the wilderness, to possess the land of the Amorite.'),
  ('bd16066f-8746-5c7b-ab95-c8d6b47ccdcc', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 11, 11, 'I raised up some of your sons for prophets, and some of your young men for Nazirites. Isn''t this true, you children of Israel?" says Yahweh.'),
  ('8429ead9-1bb9-553a-ad7d-bece94458633', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 12, 12, '"But you gave the Nazirites wine to drink, and commanded the prophets, saying, ''Don''t prophesy!'''),
  ('cfac70bb-744e-5a8a-a1a7-bb4fab287693', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 13, 13, 'Behold, I will crush you in your place, as a cart crushes that is full of grain.'),
  ('8b0dac63-0b99-51fa-a841-2d06db4e94a8', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 14, 14, 'Flight will perish from the swift; and the strong won''t strengthen his force; neither shall the mighty deliver himself;'),
  ('13486e0c-2cd3-5dd8-a4d0-3e14a74a400b', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 15, 15, 'neither shall he stand who handles the bow; and he who is swift of foot won''t escape; neither shall he who rides the horse deliver himself;'),
  ('f5bb1bf9-545f-5b79-a0cf-e746c1aa4628', '8185ccfb-1b87-58fa-a53d-ae1e678ee60d', NULL, 16, 16, 'and he who is courageous among the mighty will flee away naked on that day," says Yahweh.'),
  ('1f8379e7-9ba0-5ca4-a16e-10ae61a81905', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 1, 1, 'Hear this word that Yahweh has spoken against you, children of Israel, against the whole family which I brought up out of the land of Egypt, saying:'),
  ('d233093e-44e8-536f-a981-9389a66f6d53', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 2, 2, '"You only have I chosen of all the families of the earth. Therefore I will punish you for all of your sins."'),
  ('b73c6a99-6521-5ef8-ab0b-809e7ab6ab6a', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 3, 3, 'Do two walk together, unless they have agreed?'),
  ('262540ee-4c31-55f9-ac12-c1bcf6d1cf02', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 4, 4, 'Will a lion roar in the thicket, when he has no prey? Does a young lion cry out of his den, if he has caught nothing?'),
  ('55a15d43-3bc2-5199-adb2-9a3928ee2f07', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 5, 5, 'Can a bird fall in a trap on the earth, where no snare is set for him? Does a snare spring up from the ground, when there is nothing to catch?'),
  ('17d4f845-2ea4-5cc0-a667-23298a588b3f', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 6, 6, 'Does the trumpet alarm sound in a city, without the people being afraid? Does evil happen to a city, and Yahweh hasn''t done it?'),
  ('5be3e72e-082d-5297-ae3f-ff8d188c4f90', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 7, 7, 'Surely the Lord Yahweh will do nothing, unless he reveals his secret to his servants the prophets.'),
  ('0a203b26-2868-5368-abc3-cee85da29f11', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 8, 8, 'The lion has roared. Who will not fear? The Lord Yahweh has spoken. Who can but prophesy?'),
  ('a697df5a-3236-5572-ad38-de440654a6dd', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 9, 9, 'Proclaim in the palaces at Ashdod, and in the palaces in the land of Egypt, and say, "Assemble yourselves on the mountains of Samaria, and see what unrest is in her, and what oppression is among them."'),
  ('33110ff4-c4c9-5af4-a3a7-e8ce625d4e46', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 10, 10, '"Indeed they don''t know to do right," says Yahweh, "Who hoard plunder and loot in their palaces."'),
  ('cf779939-a078-5569-a48a-0ad7b3a66f1e', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 11, 11, 'Therefore thus says the Lord Yahweh: "An adversary will overrun the land; and he will pull down your strongholds, and your fortresses will be plundered."'),
  ('5e1516b0-4296-56ea-a070-909be66455f6', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 12, 12, 'Thus says Yahweh: "As the shepherd rescues out of the mouth of the lion two legs, or a piece of an ear, so shall the children of Israel be rescued who sit in Samaria on the corner of a couch, and on the silken cushions of a bed."'),
  ('33ad2edf-bd4f-52e1-a1ea-426810293b63', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 13, 13, '"Listen, and testify against the house of Jacob," says the Lord Yahweh, the God of Armies.'),
  ('7026b4f7-42e5-59e2-ab43-ab3673ce9d42', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 14, 14, '"For in the day that I visit the transgressions of Israel on him, I will also visit the altars of Bethel; and the horns of the altar will be cut off, and fall to the ground.'),
  ('b601d8d3-333b-5090-ab03-12ec83425bd5', '2fbf9b3b-f220-514e-ad16-f8ff644f19b1', NULL, 15, 15, 'I will strike the winter house with the summer house; and the houses of ivory will perish, and the great houses will have an end," says Yahweh.'),
  ('63899116-5cce-52bf-a250-061cc88ced97', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 1, 1, 'Listen to this word, you cows of Bashan, who are on the mountain of Samaria, who oppress the poor, who crush the needy, who tell their husbands, "Bring us drinks!"'),
  ('2cb9340a-ec38-521b-afbe-9c5d7d6be727', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 2, 2, 'The Lord Yahweh has sworn by his holiness that behold, "The days shall come on you that they will take you away with hooks, and the last of you with fish hooks.'),
  ('2e02c0df-ad37-5d33-ab11-314791bbeea2', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 3, 3, 'You will go out at the breaks in the wall, everyone straight before her; and you will cast yourselves into Harmon," says Yahweh.'),
  ('e6ff2d36-0501-500e-af78-a18397034d50', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 4, 4, '"Go to Bethel, and sin; to Gilgal, and sin more. Bring your sacrifices every morning, your tithes every three days,'),
  ('0ab875a9-eeb4-5d02-a236-213f1fe21222', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 5, 5, 'offer a sacrifice of thanksgiving of that which is leavened, and proclaim free will offerings and brag about them: for this pleases you, you children of Israel," says the Lord Yahweh.'),
  ('ecf5e6fb-5fda-520b-af7c-178e0105622b', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 6, 6, '"I also have given you cleanness of teeth in all your cities, and lack of bread in every town; yet you haven''t returned to me," says Yahweh.'),
  ('0c6bcc8a-ef37-5f96-a0b4-d81e5be106e8', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 7, 7, '"I also have withheld the rain from you, when there were yet three months to the harvest; and I caused it to rain on one city, and caused it not to rain on another city. One place was rained on, and the piece where it didn''t rain withered.'),
  ('57d47d52-a9ab-5f7f-a27a-9f838717cbad', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 8, 8, 'So two or three cities staggered to one city to drink water, and were not satisfied: yet you haven''t returned to me," says Yahweh.'),
  ('f25684d5-6ce7-519c-a0e4-2c4e6d52cd40', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 9, 9, '"I struck you with blight and mildew many times in your gardens and your vineyards; and your fig trees and your olive trees have the swarming locust devoured: yet you haven''t returned to me," says Yahweh.'),
  ('52baa404-c9c3-5ea1-a58e-040a4758d636', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 10, 10, '"I sent plagues among you like I did Egypt. I have slain your young men with the sword, and have carried away your horses; and I filled your nostrils with the stench of your camp, yet you haven''t returned to me," says Yahweh.'),
  ('020d67ed-b638-53f9-aa9f-43b7c51c0223', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 11, 11, '"I have overthrown some of you, as when God overthrew Sodom and Gomorrah, and you were like a burning stick plucked out of the fire; yet you haven''t returned to me," says Yahweh.'),
  ('10bf66ad-7c94-5d7f-a4b5-cfd071301b92', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 12, 12, '"Therefore thus will I do to you, Israel; because I will do this to you, prepare to meet your God, Israel.'),
  ('ae23cad6-ffea-5149-ad6c-6cf89419153a', '25625a21-b5c3-5ca4-aa62-cfd35e305b95', NULL, 13, 13, 'For, behold, he who forms the mountains, and creates the wind, and declares to man what is his thought; who makes the morning darkness, and treads on the high places of the Earth: Yahweh, the God of Armies, is his name."'),
  ('70366dd1-81f1-5a9d-a182-1ad48f006327', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 1, 1, 'Listen to this word which I take up for a lamentation over you, O house of Israel.'),
  ('6e829e75-1dc5-5f6a-a3a2-a22ff8d0ba95', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 2, 2, '"The virgin of Israel has fallen; She shall rise no more. She is cast down on her land; there is no one to raise her up."'),
  ('5150f706-dd30-570b-ae77-79e0bf21672b', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 3, 3, 'For thus says the Lord Yahweh: "The city that went forth a thousand shall have a hundred left, and that which went forth one hundred shall have ten left to the house of Israel."'),
  ('414acb61-124f-5d5b-a767-5717a5d76251', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 4, 4, 'For thus says Yahweh to the house of Israel: "Seek me, and you will live;'),
  ('c3ea90ef-0357-5eb4-a563-3e837560feee', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 5, 5, 'but don''t seek Bethel, nor enter into Gilgal, and don''t pass to Beersheba: for Gilgal shall surely go into captivity, and Bethel shall come to nothing.'),
  ('00a83371-d9fd-57be-aded-ca7a2bc54d9a', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 6, 6, 'Seek Yahweh, and you will live; lest he break out like fire in the house of Joseph, and it devour, and there be no one to quench it in Bethel.'),
  ('86bdf3ea-7b0e-5bf4-ad23-3f0abaf1f54e', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 7, 7, 'You who turn justice to wormwood, and cast down righteousness to the earth:'),
  ('963e5e56-397b-5f63-a153-3c13e963432c', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 8, 8, 'seek him who made the Pleiades and Orion, and turns the shadow of death into the morning, and makes the day dark with night; who calls for the waters of the sea, and pours them out on the surface of the earth, Yahweh is his name,'),
  ('92c58399-afe5-5204-aeef-401ec7f5cd5d', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 9, 9, 'who brings sudden destruction on the strong, so that destruction comes on the fortress.'),
  ('1ebb0119-e105-56d2-a755-8b23280f4784', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 10, 10, 'They hate him who reproves in the gate, and they abhor him who speaks blamelessly.'),
  ('f1544e75-4c84-5883-afbe-90b9f818bdcb', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 11, 11, 'Forasmuch therefore as you trample on the poor, and take taxes from him of wheat: You have built houses of cut stone, but you will not dwell in them. You have planted pleasant vineyards, but you shall not drink their wine.'),
  ('41b80f32-6c31-5bec-a3bc-783aec5c9185', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 12, 12, 'For I know how many your offenses, and how great are your sins-- you who afflict the just, who take a bribe, and who turn aside the needy in the courts.'),
  ('45487e21-8e3d-5136-ae72-8119890276e7', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 13, 13, 'Therefore a prudent person keeps silent in such a time, for it is an evil time.'),
  ('3110e4bc-50dd-5858-a6b6-c1b5a0e83f88', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 14, 14, 'Seek good, and not evil, that you may live; and so Yahweh, the God of Armies, will be with you, as you say.'),
  ('fe3e85d2-dfde-52d9-a333-e8b07cf23912', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 15, 15, 'Hate evil, love good, and establish justice in the courts. It may be that Yahweh, the God of Armies, will be gracious to the remnant of Joseph."'),
  ('44e43842-2ae6-501e-a4e4-8727a99b3301', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 16, 16, 'Therefore thus says Yahweh, the God of Armies, the Lord: "Wailing will be in all the broad ways; and they will say in all the streets, ''Alas! Alas!'' and they will call the farmer to mourning, and those who are skillful in lamentation to wailing.'),
  ('a62bd55f-c946-5366-a045-e639fc70ada9', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 17, 17, 'In all vineyards there will be wailing; for I will pass through the midst of you," says Yahweh.'),
  ('bb44077e-379e-53b5-a6b0-44c62f489de6', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 18, 18, '"Woe to you who desire the day of Yahweh! Why do you long for the day of Yahweh? It is darkness, and not light.'),
  ('a5264474-8632-57bc-a620-72554b41f53c', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 19, 19, 'As if a man fled from a lion, and a bear met him; Or he went into the house and leaned his hand on the wall, and a snake bit him.'),
  ('62ba294b-7ef6-5ab0-a8a4-27badbe66224', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 20, 20, 'Won''t the day of Yahweh be darkness, and not light? Even very dark, and no brightness in it?'),
  ('9135c563-5932-59f4-a5d9-4c43b4def131', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 21, 21, 'I hate, I despise your feasts, and I can''t stand your solemn assemblies.'),
  ('77c82cd5-0b8e-5884-a18d-97ff12b3289a', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 22, 22, 'Yes, though you offer me your burnt offerings and meal offerings, I will not accept them; neither will I regard the peace offerings of your fat animals.'),
  ('39b7abf5-31ea-52f7-a1b3-8f23afa6c480', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 23, 23, 'Take away from me the noise of your songs! I will not listen to the music of your harps.'),
  ('003faafe-136e-513a-aaeb-27a88ec0b653', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 24, 24, 'But let justice roll on like rivers, and righteousness like a mighty stream.'),
  ('71660eea-8be7-5507-a686-938fa012ef83', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 25, 25, '"Did you bring to me sacrifices and offerings in the wilderness forty years, house of Israel?'),
  ('84359661-e4b0-5cf1-aa3f-463babeefe06', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 26, 26, 'You also carried the tent of your king and the shrine of your images, the star of your god, which you made for yourselves.'),
  ('782e281f-5648-5c9d-ab85-08fbb4b6b1c1', '7e1e58b5-54a1-5f5d-a2d3-5ccf2cb31062', NULL, 27, 27, 'Therefore will I cause you to go into captivity beyond Damascus," says Yahweh, whose name is the God of Armies.'),
  ('a507c6ec-dda8-59e5-aedc-61a3d29db714', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 1, 1, 'Woe to those who are at ease in Zion, and to those who are secure on the mountain of Samaria, the notable men of the chief of the nations, to whom the house of Israel come!'),
  ('66fb601c-56aa-56ed-adc2-f35f03461f05', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 2, 2, 'Go to Calneh, and see; and from there go to Hamath the great; then go down to Gath of the Philistines. are they better than these kingdoms? or is their border greater than your border?'),
  ('7884ae8d-396a-58b1-aba1-599d0cd8da55', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 3, 3, 'Those who put far away the evil day, and cause the seat of violence to come near;'),
  ('f68f5a73-1b37-5ba2-a8a9-342f9bf2ebc3', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 4, 4, 'Who lie on beds of ivory, and stretch themselves on their couches, and eat the lambs out of the flock, and the calves out of the midst of the stall;'),
  ('c6ff9e16-1577-569e-a271-ad78598bdf54', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 5, 5, 'who strum on the strings of a harp; who invent for themselves instruments of music, like David;'),
  ('dd1e6851-bba4-5688-a4df-660c46b68178', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 6, 6, 'who drink wine in bowls, and anoint themselves with the best oils; but they are not grieved for the affliction of Joseph.'),
  ('ef9e3ce9-e84e-55e4-a624-66d29572fc1e', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 7, 7, 'Therefore they will now go captive with the first who go captive; and the feasting and lounging will end.'),
  ('d2f979b2-4fdd-5e7b-a459-ad32299cd961', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 8, 8, '"The Lord Yahweh has sworn by himself," says Yahweh, the God of Armies: "I abhor the pride of Jacob, and detest his fortresses. Therefore I will deliver up the city with all that is in it.'),
  ('9b789688-066b-531e-a171-3eb5ae3b443e', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 9, 9, 'It will happen, if there remain ten men in one house, that they shall die.'),
  ('0f94f4bf-e8f9-56f2-a0e9-aa16631d901b', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 10, 10, '"When a man''s relative carries him, even he who burns him, to bring bodies out of the house, and asks him who is in the innermost parts of the house, ''Is there yet any with you?'' And he says, ''No;'' then he will say, ''Hush! Indeed we must not mention the name of Yahweh.'''),
  ('64bd9e20-c21c-525d-ad38-da9bd3e398df', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 11, 11, '"For, behold, Yahweh commands, and the great house will be smashed to pieces, and the little house into bits.'),
  ('27d9cd1c-7346-554c-aff3-55c3b981bd71', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 12, 12, 'Do horses run on the rocky crags? Does one plow there with oxen? But you have turned justice into poison, and the fruit of righteousness into bitterness;'),
  ('03c7677e-cd1a-5597-afd9-c3cf6837c591', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 13, 13, 'you who rejoice in a thing of nothing, who say, ''Haven''t we taken for ourselves horns by our own strength?'''),
  ('553a58f1-42a4-533d-a679-cef6f68e1d37', '0cfe3f4e-1ca6-5a53-add4-63e3f325fe1e', NULL, 14, 14, 'For, behold, I will raise up against you a nation, house of Israel," says Yahweh, the God of Armies; "and they will afflict you from the entrance of Hamath to the brook of the Arabah."'),
  ('e5d2d409-9fd0-50b9-acb6-7e52359cbb8a', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 1, 1, 'Thus the Lord Yahweh showed me: and behold, he formed locusts in the beginning of the shooting up of the latter growth; and behold, it was the latter growth after the king''s harvest.'),
  ('815f8583-e181-54b4-af12-4bd503223bdb', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 2, 2, 'It happened that, when they made an end of eating the grass of the land, then I said, "Lord Yahweh, forgive, I beg you! How could Jacob stand? For he is small."'),
  ('19ab45e7-a0c8-57ea-aee3-d365d9e79b49', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 3, 3, 'Yahweh relented concerning this. "It shall not be," says Yahweh.'),
  ('4af9c9c7-204d-5155-a9c4-7aa2e8329883', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 4, 4, 'Thus the Lord Yahweh showed me and behold, the Lord Yahweh called for judgment by fire; and it dried up the great deep, and would have devoured the land.'),
  ('9ab0b24c-c9cc-59f4-ac83-cee639280984', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 5, 5, 'Then I said, "Lord Yahweh, stop, I beg you! How could Jacob stand? For he is small."'),
  ('0714e223-fa8d-55b7-af26-548cc105927b', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 6, 6, 'Yahweh relented concerning this. "This also shall not be," says the Lord Yahweh.'),
  ('dd79b35f-892f-54b7-a8ef-3c62f23cf6bc', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 7, 7, 'Thus he showed me and behold, the Lord stood beside a wall made by a plumb line, with a plumb line in his hand.'),
  ('4bea23a6-b5f6-5309-a880-6db7aafdcff6', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 8, 8, 'Yahweh said to me, "Amos, what do you see?" I said, "A plumb line." Then the Lord said, "Behold, I will set a plumb line in the midst of my people Israel. I will not again pass by them any more.'),
  ('81088c4b-fe33-5f07-aed3-3904466d2c66', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 9, 9, 'The high places of Isaac will be desolate, the sanctuaries of Israel will be laid waste; and I will rise against the house of Jeroboam with the sword."'),
  ('7e3cfd93-cf0a-55a1-ad78-a135f5b50bf4', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 10, 10, 'Then Amaziah the priest of Bethel sent to Jeroboam king of Israel, saying, "Amos has conspired against you in the midst of the house of Israel. The land is not able to bear all his words.'),
  ('a95e0fb5-1d4d-5bbf-a9b7-1179896b32e3', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 11, 11, 'For Amos says, ''Jeroboam will die by the sword, and Israel shall surely be led away captive out of his land.''"'),
  ('9c901f3a-f3c3-56e6-a06e-2868eecb12da', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 12, 12, 'Amaziah also said to Amos, "You seer, go, flee away into the land of Judah, and there eat bread, and prophesy there:'),
  ('e4a82dcb-a586-50ce-a0eb-c363477fc15d', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 13, 13, 'but don''t prophesy again any more at Bethel; for it is the king''s sanctuary, and it is a royal house!"'),
  ('6089d060-ad0e-5ea4-a520-265814592c19', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 14, 14, 'Then Amos answered Amaziah, "I was no prophet, neither was I a prophet''s son; but I was a herdsman, and a farmer of sycamore figs;'),
  ('d975d4d6-1440-5161-aa50-2022e6bd89f3', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 15, 15, 'and Yahweh took me from following the flock, and Yahweh said to me, ''Go, prophesy to my people Israel.'''),
  ('5d6824da-c0ba-5586-a5ff-51d0c83f720e', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 16, 16, 'Now therefore listen to the word of Yahweh: ''You say, Don''t prophesy against Israel, and don''t preach against the house of Isaac.'''),
  ('fec282a6-7748-57af-a568-60875ad770c4', '7c48abc8-d81a-5e11-ab54-71c81a06d08d', NULL, 17, 17, 'Therefore thus says Yahweh: ''Your wife shall be a prostitute in the city, and your sons and your daughters shall fall by the sword, and your land shall be divided by line; and you yourself shall die in a land that is unclean, and Israel shall surely be led away captive out of his land.''"'),
  ('301efe19-2c50-50c2-ae73-cc3240d83db0', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 1, 1, 'Thus the Lord Yahweh showed me: behold, a basket of summer fruit.'),
  ('59126dad-58ee-5144-a15d-e54f3f895509', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 2, 2, 'He said, "Amos, what do you see?" I said, "A basket of summer fruit." Then Yahweh said to me, "The end has come on my people Israel. I will not again pass by them any more.'),
  ('dc69f38c-f07f-54f8-ab79-18914e6f9495', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 3, 3, 'The songs of the temple will be wailings in that day," says the Lord Yahweh. "The dead bodies will be many. In every place they will throw them out with silence.'),
  ('0a38692f-b379-5850-a246-ab66c80c6bd9', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 4, 4, 'Hear this, you who desire to swallow up the needy, and cause the poor of the land to fail,'),
  ('db4d4eda-516a-59a0-acaa-7cc46ce0e412', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 5, 5, 'Saying, ''When will the new moon be gone, that we may sell grain? And the Sabbath, that we may market wheat, making the ephah small, and the shekel large, and dealing falsely with balances of deceit;'),
  ('1ab04917-3757-5d8d-a2a7-695f0cb7e47a', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 6, 6, 'that we may buy the poor for silver, and the needy for a pair of shoes, and sell the sweepings with the wheat?''"'),
  ('04cd9c60-5b37-559d-a64f-ec3c58fe2967', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 7, 7, 'Yahweh has sworn by the pride of Jacob, "Surely I will never forget any of their works.'),
  ('7a49afdb-9130-5d68-a2e7-06f696eb9969', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 8, 8, 'Won''t the land tremble for this, and everyone mourn who dwells in it? Yes, it will rise up wholly like the River; and it will be stirred up and sink again, like the River of Egypt.'),
  ('8d43522d-8130-589c-a2fb-4db8978b99c1', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 9, 9, 'It will happen in that day," says the Lord Yahweh, "that I will cause the sun to go down at noon, and I will darken the earth in the clear day.'),
  ('a5aefc27-742b-51fa-acb0-34a6a99cdaee', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 10, 10, 'I will turn your feasts into mourning, and all your songs into lamentation; and I will make you wear sackcloth on all your bodies, and baldness on every head. I will make it like the mourning for an only son, and its end like a bitter day.'),
  ('0a13fcb2-cc7a-5356-a303-6829c2358610', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 11, 11, 'Behold, the days come," says the Lord Yahweh, "that I will send a famine in the land, not a famine of bread, nor a thirst for water, but of hearing the words of Yahweh.'),
  ('baf2f0df-cd34-5e6f-a957-0c96f6b67cb6', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 12, 12, 'They will wander from sea to sea, and from the north even to the east; they will run back and forth to seek the word of Yahweh, and will not find it.'),
  ('2f0a91aa-1110-54f1-a0df-5c72be45a8ac', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 13, 13, 'In that day the beautiful virgins and the young men will faint for thirst.'),
  ('bfccb1e0-22fa-56b2-a06e-aac933580887', 'ead00deb-2cc1-5864-a1b7-abddd9328013', NULL, 14, 14, 'Those who swear by the sin of Samaria, and say, ''As your god, Dan, lives;'' and, ''As the way of Beersheba lives;'' they will fall, and never rise up again."'),
  ('33505b61-6fbc-5090-a48a-0f19b50b5d31', '10b28963-8370-5765-a632-d35c6548453a', NULL, 1, 1, 'I saw the Lord standing beside the altar, and he said, "Strike the tops of the pillars, that the thresholds may shake; and break them in pieces on the head of all of them; and I will kill the last of them with the sword: there shall not one of them flee away, and there shall not one of them escape.'),
  ('328924c4-4f8a-5c9e-afa4-203a14fcfe13', '10b28963-8370-5765-a632-d35c6548453a', NULL, 2, 2, 'Though they dig into Sheol, there my hand will take them; and though they climb up to heaven, there I will bring them down.'),
  ('4c92fcfb-aeb9-5304-adf9-882cb5b56d41', '10b28963-8370-5765-a632-d35c6548453a', NULL, 3, 3, 'Though they hide themselves in the top of Carmel, I will search and take them out there; and though they be hidden from my sight in the bottom of the sea, there I will command the serpent, and it will bite them.'),
  ('a7ddaf59-56c0-5b63-abb9-7cd88e156aa2', '10b28963-8370-5765-a632-d35c6548453a', NULL, 4, 4, 'Though they go into captivity before their enemies, there I will command the sword, and it will kill them. I will set my eyes on them for evil, and not for good.'),
  ('ba9098dd-7fb3-5338-a471-8967530ca77f', '10b28963-8370-5765-a632-d35c6548453a', NULL, 5, 5, 'For the Lord, Yahweh of Armies, is he who touches the land and it melts, and all who dwell in it will mourn; and it will rise up wholly like the River, and will sink again, like the River of Egypt.'),
  ('36a004e8-93f9-581c-a8fc-b585e3dd089a', '10b28963-8370-5765-a632-d35c6548453a', NULL, 6, 6, 'It is he who builds his rooms in the heavens, and has founded his vault on the earth; he who calls for the waters of the sea, and pours them out on the surface of the earth; Yahweh is his name.'),
  ('8714fa1d-6d7a-5548-a191-52d18ee92c45', '10b28963-8370-5765-a632-d35c6548453a', NULL, 7, 7, 'Are you not like the children of the Ethiopians to me, children of Israel?" says Yahweh. "Haven''t I brought up Israel out of the land of Egypt, and the Philistines from Caphtor, and the Syrians from Kir?'),
  ('90d279c1-ce8f-5cd0-aa70-8443bb6e36e8', '10b28963-8370-5765-a632-d35c6548453a', NULL, 8, 8, 'Behold, the eyes of the Lord Yahweh are on the sinful kingdom, and I will destroy it from off the surface of the earth; except that I will not utterly destroy the house of Jacob," says Yahweh.'),
  ('68132338-8810-5418-a36f-f957ba3689fe', '10b28963-8370-5765-a632-d35c6548453a', NULL, 9, 9, '"For, behold, I will command, and I will sift the house of Israel among all the nations, as grain is sifted in a sieve, yet not the least kernel will fall on the earth.'),
  ('a138edb8-af57-58b3-abf4-fd07fb172b44', '10b28963-8370-5765-a632-d35c6548453a', NULL, 10, 10, 'All the sinners of my people will die by the sword, who say, ''Evil won''t overtake nor meet us.'''),
  ('d63226ca-7098-548f-a975-e9d8be15777f', '10b28963-8370-5765-a632-d35c6548453a', NULL, 11, 11, 'In that day I will raise up the tent of David who is fallen, and close up its breaches, and I will raise up its ruins, and I will build it as in the days of old;'),
  ('e25f70e0-0cf2-5b33-a5f2-217cc3afc0cb', '10b28963-8370-5765-a632-d35c6548453a', NULL, 12, 12, 'that they may possess the remnant of Edom, and all the nations who are called by my name," says Yahweh who does this.'),
  ('94e9a854-56c0-548c-a15b-f4f2d7bfef50', '10b28963-8370-5765-a632-d35c6548453a', NULL, 13, 13, '"Behold, the days come," says Yahweh, "that the plowman shall overtake the reaper, and the one treading grapes him who sows seed; and sweet wine will drip from the mountains, and flow from the hills.'),
  ('e3765b08-a9b7-54d4-a762-b3d604fa2d25', '10b28963-8370-5765-a632-d35c6548453a', NULL, 14, 14, 'I will bring my people Israel back from captivity, and they will rebuild the ruined cities, and inhabit them; and they will plant vineyards, and drink wine from them. They shall also make gardens, and eat the fruit of them.'),
  ('f7a28afd-5080-59c8-a634-da11fc5dcfc5', '10b28963-8370-5765-a632-d35c6548453a', NULL, 15, 15, 'I will plant them on their land, and they will no more be plucked up out of their land which I have given them," says Yahweh your God.'),
  ('bd2762e1-9c19-594a-a6e7-6c99a3794c65', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 1, 1, 'The vision of Obadiah. This is what the Lord Yahweh says about Edom. We have heard news from Yahweh, and an ambassador is sent among the nations, saying, "Arise, and let''s rise up against her in battle.'),
  ('f206e646-bda1-5434-a8f7-27001397c40d', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 2, 2, 'Behold, I have made you small among the nations. You are greatly despised.'),
  ('e7d019d4-1b25-50d3-afb5-249b75bd2709', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 3, 3, 'The pride of your heart has deceived you, you who dwell in the clefts of the rock, whose habitation is high, who says in his heart, ''Who will bring me down to the ground?'''),
  ('e3a95480-cc86-5c55-a9d9-6a839ef16344', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 4, 4, 'Though you mount on high as the eagle, and though your nest is set among the stars, I will bring you down from there," says Yahweh.'),
  ('442314be-20bb-5ddb-ae13-099daedcf3fd', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 5, 5, '"If thieves came to you, if robbers by night--oh, what disaster awaits you--wouldn''t they only steal until they had enough? If grape pickers came to you, wouldn''t they leave some gleaning grapes?'),
  ('826190e4-aee6-55e9-a1a2-d02c91b885de', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 6, 6, 'How Esau will be ransacked! How his hidden treasures are sought out!'),
  ('f4738844-5433-5e24-a522-3128ed327877', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 7, 7, 'All the men of your alliance have brought you on your way, even to the border. The men who were at peace with you have deceived you, and prevailed against you. Friends who eat your bread lay a snare under you. There is no understanding in him."'),
  ('5939abe6-49e9-523e-a364-98374b6a7298', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 8, 8, '"Won''t I in that day," says Yahweh, "destroy the wise men out of Edom, and understanding out of the mountain of Esau?'),
  ('408205ad-2db8-5339-a70a-07847c6c0719', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 9, 9, 'Your mighty men, Teman, will be dismayed, to the end that everyone may be cut off from the mountain of Esau by slaughter.'),
  ('2f4064da-2866-595a-a670-3c995a9b6d6e', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 10, 10, 'For the violence done to your brother Jacob, shame will cover you, and you will be cut off forever.'),
  ('1ca83505-7011-5895-a7bd-aa0e57c388a6', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 11, 11, 'In the day that you stood on the other side, in the day that strangers carried away his substance, and foreigners entered into his gates, and cast lots for Jerusalem, even you were like one of them.'),
  ('5966ea5c-e49f-5482-a871-6193b2e32f19', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 12, 12, 'But don''t look down on your brother in the day of his disaster, and don''t rejoice over the children of Judah in the day of their destruction. Don''t speak proudly in the day of distress.'),
  ('a31e0189-79cc-5a07-aff0-b23d8adda0df', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 13, 13, 'Don''t enter into the gate of my people in the day of their calamity. Don''t look down on their affliction in the day of their calamity, neither seize their wealth on the day of their calamity.'),
  ('ee431774-5477-5a83-a3ce-4aed479459ef', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 14, 14, 'Don''t stand in the crossroads to cut off those of his who escape. Don''t deliver up those of his who remain in the day of distress.'),
  ('e5c62097-3841-5fe6-a648-2faa4cc0cd6a', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 15, 15, 'For the day of Yahweh is near all the nations! As you have done, it will be done to you. Your deeds will return upon your own head.'),
  ('a5fd7f2b-8944-5dab-a6f1-d422050e316c', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 16, 16, 'For as you have drunk on my holy mountain, so will all the nations drink continually. Yes, they will drink, swallow down, and will be as though they had not been.'),
  ('b4af55ea-8d6f-516f-a59b-89c8869fe104', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 17, 17, 'But in Mount Zion, there will be those who escape, and it will be holy. The house of Jacob will possess their possessions.'),
  ('845759ef-76ea-5bf0-a4bb-367e50411717', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 18, 18, 'The house of Jacob will be a fire, the house of Joseph a flame, and the house of Esau for stubble. They will burn among them, and devour them. There will not be any remaining to the house of Esau." Indeed, Yahweh has spoken.'),
  ('d58fd0ca-6d49-5e06-a420-b4d3f60c33e3', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 19, 19, 'Those of the South will possess the mountain of Esau, and those of the lowland, the Philistines. They will possess the field of Ephraim, and the field of Samaria. Benjamin will possess Gilead.'),
  ('8ec835c3-eae1-55ad-acee-560f7dd3a6ab', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 20, 20, 'The captives of this army of the children of Israel, who are among the Canaanites, will possess even to Zarephath; and the captives of Jerusalem, who are in Sepharad, will possess the cities of the Negev.'),
  ('aaaab8a1-d987-5b71-a3fd-7466dc8fd860', 'd00f58e2-0d30-52ed-a8be-f868eebfb0fa', NULL, 21, 21, 'Saviors will go up on Mount Zion to judge the mountains of Esau, and the kingdom will be Yahweh''s.'),
  ('dfedc64f-8f6c-53e8-a1e5-69fd2fedee07', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 1, 1, 'Now the word of Yahweh came to Jonah the son of Amittai, saying,'),
  ('8ddc3cf7-1d70-53d4-a404-45cf58d3f27a', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 2, 2, '"Arise, go to Nineveh, that great city, and preach against it, for their wickedness has come up before me."'),
  ('ea84a687-146e-5174-a399-de94bb1732cd', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 3, 3, 'But Jonah rose up to flee to Tarshish from the presence of Yahweh. He went down to Joppa, and found a ship going to Tarshish; so he paid its fare, and went down into it, to go with them to Tarshish from the presence of Yahweh.'),
  ('c42a2ac0-348b-52bc-a10b-488c27b5e700', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 4, 4, 'But Yahweh sent out a great wind on the sea, and there was a mighty storm on the sea, so that the ship was likely to break up.'),
  ('cb3a257d-f36b-509c-a55c-916f8cd4953a', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 5, 5, 'Then the mariners were afraid, and every man cried to his god. They threw the cargo that was in the ship into the sea to lighten the ship. But Jonah had gone down into the innermost parts of the ship, and he was laying down, and was fast asleep.'),
  ('92480fd2-e1c4-5a43-a206-8d773229cfb7', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 6, 6, 'So the shipmaster came to him, and said to him, "What do you mean, sleeper? Arise, call on your God! Maybe your God will notice us, so that we won''t perish."'),
  ('9046e343-de14-57e3-a5e9-b6f7a072a0dc', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 7, 7, 'They all said to each other, "Come, let us cast lots, that we may know who is responsible for this evil that is on us." So they cast lots, and the lot fell on Jonah.'),
  ('12eb5a9d-387f-5058-a255-68395546694c', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 8, 8, 'Then they asked him, "Tell us, please, for whose cause this evil is on us. What is your occupation? Where do you come from? What is your country? Of what people are you?"'),
  ('e447ec82-b72a-586f-aa7c-6d14cb9c5885', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 9, 9, 'He said to them, "I am a Hebrew, and I fear Yahweh, the God of heaven, who has made the sea and the dry land."'),
  ('f7e8828f-f5e9-5730-a1f9-321d1e5fcc4d', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 10, 10, 'Then were the men exceedingly afraid, and said to him, "What is this that you have done?" For the men knew that he was fleeing from the presence of Yahweh, because he had told them.'),
  ('7125a75c-c150-58d5-a384-96059371dcbd', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 11, 11, 'Then they said to him, "What shall we do to you, that the sea may be calm to us?" For the sea grew more and more stormy.'),
  ('36333cb3-576d-5282-af49-cb4fe97e80d0', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 12, 12, 'He said to them, "Take me up, and throw me into the sea. Then the sea will be calm for you; for I know that because of me this great storm is on you."'),
  ('8aefcd4c-6ba0-5b65-aa9e-c0d2d80e1a8c', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 13, 13, 'Nevertheless the men rowed hard to get them back to the land; but they could not, for the sea grew more and more stormy against them.'),
  ('bca05486-afc7-5ba9-a714-259667b09039', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 14, 14, 'Therefore they cried to Yahweh, and said, "We beg you, Yahweh, we beg you, don''t let us die for this man''s life, and don''t lay on us innocent blood; for you, Yahweh, have done as it pleased you."'),
  ('92540374-c505-5df1-ae4d-2d97852db3fd', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 15, 15, 'So they took up Jonah, and threw him into the sea; and the sea ceased its raging.'),
  ('410fc633-4d1c-5d76-a77d-f5dd4f6be268', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 16, 16, 'Then the men feared Yahweh exceedingly; and they offered a sacrifice to Yahweh, and made vows.'),
  ('ca7cfda1-5da9-5c97-a8c0-2e098425475c', '4c62c064-cf5a-585e-ad4c-72d3461249a2', NULL, 17, 17, 'Yahweh prepared a great fish to swallow up Jonah, and Jonah was in the belly of the fish three days and three nights.'),
  ('9cf68669-9729-524e-a067-f5d250b21fe6', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 1, 1, 'Then Jonah prayed to Yahweh, his God, out of the fish''s belly.'),
  ('88cc098e-fa97-5489-a4c0-29d81eff1b85', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 2, 2, 'He said, "I called because of my affliction to Yahweh. He answered me. Out of the belly of Sheol I cried. You heard my voice.'),
  ('0a97a5db-0a4e-50c8-a53c-e42109f3e509', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 3, 3, 'For you threw me into the depths, in the heart of the seas. The flood was all around me. All your waves and your billows passed over me.'),
  ('ab8fa8aa-4492-5d00-ab60-e6d93de97fee', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 4, 4, 'I said, ''I have been banished from your sight; yet I will look again toward your holy temple.'''),
  ('cd3309c1-f1d0-5904-a6f4-b29e93738c4e', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 5, 5, 'The waters surrounded me, even to the soul. The deep was around me. The weeds were wrapped around my head.'),
  ('ff6560bc-8d3e-575f-ac91-f6f8d8e0aed0', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 6, 6, 'I went down to the bottoms of the mountains. The earth barred me in forever: yet have you brought up my life from the pit, Yahweh my God.'),
  ('12a00d7e-45a0-50a4-a393-911816c91e4e', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 7, 7, '"When my soul fainted within me, I remembered Yahweh. My prayer came in to you, into your holy temple.'),
  ('ea6e843f-34b4-5716-a30e-89acdb462923', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 8, 8, 'Those who regard lying vanities forsake their own mercy.'),
  ('a1a5d8c1-769e-554a-a259-08674478e449', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 9, 9, 'But I will sacrifice to you with the voice of thanksgiving. I will pay that which I have vowed. Salvation belongs to Yahweh."'),
  ('32045c91-4c69-5cfe-a60a-de7947a35005', '0a49dbdf-838a-53e3-ae54-5283120d7a3b', NULL, 10, 10, 'Yahweh spoke to the fish, and it vomited out Jonah on the dry land.'),
  ('c3e4be99-c86e-5954-a152-fc93a322d881', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 1, 1, 'The word of Yahweh came to Jonah the second time, saying,'),
  ('25879c5b-abc5-5b9a-a7fc-9f7650fea192', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 2, 2, '"Arise, go to Nineveh, that great city, and preach to it the message that I give you."'),
  ('9edb6514-1e33-5a36-afd6-b439f476eef8', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 3, 3, 'So Jonah arose, and went to Nineveh, according to the word of Yahweh. Now Nineveh was an exceedingly great city, three days'' journey across.'),
  ('a6000cb5-76ba-5f05-aef3-5e335639f7c8', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 4, 4, 'Jonah began to enter into the city a day''s journey, and he cried out, and said, "In forty days, Nineveh will be overthrown!"'),
  ('60e6d2a2-c015-5c5a-aec5-c163ca8b3fd1', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 5, 5, 'The people of Nineveh believed God; and they proclaimed a fast, and put on sackcloth, from the greatest of them even to the least of them.'),
  ('1bb18779-a9e6-56a3-a370-df6b96d0b062', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 6, 6, 'The news reached the king of Nineveh, and he arose from his throne, and took off his royal robe, covered himself with sackcloth, and sat in ashes.'),
  ('21fa3031-d7d9-5b27-ad4a-0c4444703a12', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 7, 7, 'He made a proclamation and published through Nineveh by the decree of the king and his nobles, saying, "Let neither man nor animal, herd nor flock, taste anything; let them not feed, nor drink water;'),
  ('d5467cb8-4b83-5675-ab06-667d1a98fac0', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 8, 8, 'but let them be covered with sackcloth, both man and animal, and let them cry mightily to God. Yes, let them turn everyone from his evil way, and from the violence that is in his hands.'),
  ('ebd7352c-a2fb-583a-a65a-2dca7d92026a', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 9, 9, 'Who knows whether God will not turn and relent, and turn away from his fierce anger, so that we might not perish?"'),
  ('78198705-d41a-50f5-a2fe-68d9091bcb67', '0ef86b24-9e3d-58ab-a4a4-526d16536056', NULL, 10, 10, 'God saw their works, that they turned from their evil way. God relented of the disaster which he said he would do to them, and he didn''t do it.'),
  ('18188852-3ae5-5af5-a0d9-bf5ea6b212cd', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 1, 1, 'But it displeased Jonah exceedingly, and he was angry.'),
  ('e6fd98b1-7c65-55fe-a65f-82459ce449f2', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 2, 2, 'He prayed to Yahweh, and said, "Please, Yahweh, wasn''t this what I said when I was still in my own country? Therefore I hurried to flee to Tarshish, for I knew that you are a gracious God, and merciful, slow to anger, and abundant in loving kindness, and you relent of doing harm.'),
  ('09c6c31d-e522-527c-a639-2f5843bd23af', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 3, 3, 'Therefore now, Yahweh, take, I beg you, my life from me; for it is better for me to die than to live."'),
  ('1b7c6066-884e-5de4-a26f-882b704601c8', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 4, 4, 'Yahweh said, "Is it right for you to be angry?"'),
  ('b29c572a-b31d-5d93-a453-389aff9fcde4', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 5, 5, 'Then Jonah went out of the city, and sat on the east side of the city, and there made himself a booth, and sat under it in the shade, until he might see what would become of the city.'),
  ('31a76ac8-c8a2-50db-abb1-d6ac23c65b22', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 6, 6, 'Yahweh God prepared a vine, and made it to come up over Jonah, that it might be a shade over his head, to deliver him from his discomfort. So Jonah was exceedingly glad because of the vine.'),
  ('244e30b4-9b02-566d-a4ec-b08b8e487418', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 7, 7, 'But God prepared a worm at dawn the next day, and it chewed on the vine, so that it withered.'),
  ('9b452c4e-0598-5c17-a805-2b78be15c0aa', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 8, 8, 'It happened, when the sun arose, that God prepared a sultry east wind; and the sun beat on Jonah''s head, so that he fainted, and requested for himself that he might die, and said, "It is better for me to die than to live."'),
  ('c2087e22-53ef-5ec7-a4d6-cf9239c9b1da', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 9, 9, 'God said to Jonah, "Is it right for you to be angry about the vine?" He said, "I am right to be angry, even to death."'),
  ('79b1356e-eb9f-54b0-aef9-b570681c1bfe', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 10, 10, 'Yahweh said, "You have been concerned for the vine, for which you have not labored, neither made it grow; which came up in a night, and perished in a night.'),
  ('b7994b27-c8be-5a9a-a948-61bcf2c05f67', '11ec2c8b-cfee-5976-a845-816612b30805', NULL, 11, 11, 'Shouldn''t I be concerned for Nineveh, that great city, in which are more than one hundred twenty thousand persons who can''t discern between their right hand and their left hand; and also much livestock?"'),
  ('e62f0282-65fc-5146-ac0c-cb71b1fc5513', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 1, 1, 'The word of Yahweh that came to Micah the Morashtite in the days of Jotham, Ahaz, and Hezekiah, kings of Judah, which he saw concerning Samaria and Jerusalem.'),
  ('e0be010e-eaa4-556f-a603-13fd90703eea', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 2, 2, 'Hear, you peoples, all of you. Listen, O earth, and all that is therein: and let the Lord Yahweh be witness against you, the Lord from his holy temple.'),
  ('66e785dd-2343-5653-a5eb-4e0a1ee7e89a', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 3, 3, 'For, behold, Yahweh comes forth out of his place, and will come down and tread on the high places of the earth.'),
  ('83ec18a8-2170-5489-ac31-544382367686', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 4, 4, 'The mountains melt under him, and the valleys split apart, like wax before the fire, like waters that are poured down a steep place.'),
  ('4d22d4d0-e7e2-556e-aaa4-e696e28f540f', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 5, 5, '"All this is for the disobedience of Jacob, and for the sins of the house of Israel. What is the disobedience of Jacob? Isn''t it Samaria? And what are the high places of Judah? Aren''t they Jerusalem?'),
  ('0b93dc2a-04a5-5181-a093-4e71fac721df', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 6, 6, 'Therefore I will make Samaria like a rubble heap of the field, like places for planting vineyards; and I will pour down its stones into the valley, and I will uncover its foundations.'),
  ('09c5927f-87c8-5b91-ae46-d864ccbba5b4', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 7, 7, 'All her idols will be beaten to pieces, and all her temple gifts will be burned with fire, and all her images I will destroy; for of the hire of a prostitute has she gathered them, and to the hire of a prostitute shall they return."'),
  ('1154e2e0-f8a9-5be2-a9b3-b876bab7681a', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 8, 8, 'For this I will lament and wail; I will go stripped and naked; I will howl like the jackals, and moan like the daughters of owls.'),
  ('1c0ac649-f3c8-5526-ad26-a4544ada5629', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 9, 9, 'For her wounds are incurable; for it has come even to Judah. It reaches to the gate of my people, even to Jerusalem.'),
  ('a0e66ff9-50f9-55c3-a64d-02f450c499f0', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 10, 10, 'Don''t tell it in Gath. Don''t weep at all. At Beth Ophrah I have rolled myself in the dust.'),
  ('1df12fa1-c9f8-5930-a7ef-7b13508ce094', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 11, 11, 'Pass on, inhabitant of Shaphir, in nakedness and shame. The inhabitant of Zaanan won''t come out. The wailing of Beth Ezel will take from you his protection.'),
  ('bb3a3755-95b2-5613-a1af-900f90be2b42', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 12, 12, 'For the inhabitant of Maroth waits anxiously for good, because evil has come down from Yahweh to the gate of Jerusalem.'),
  ('a7d8b47c-3fe4-515a-a64d-69f61129ee6b', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 13, 13, 'Harness the chariot to the swift steed, inhabitant of Lachish. She was the beginning of sin to the daughter of Zion; For the transgressions of Israel were found in you.'),
  ('10b9d228-3816-5d0a-ae24-dfc942aad4f1', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 14, 14, 'Therefore you will give a parting gift to Moresheth Gath. The houses of Achzib will be a deceitful thing to the kings of Israel.'),
  ('4686ebb0-ffb0-5e2d-a266-4ab907ac490f', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 15, 15, 'I will yet bring to you, inhabitant of Mareshah. He who is the glory of Israel will come to Adullam.'),
  ('7936d509-cfde-5ab9-a3d5-7b1d27bc5df8', '9aeab54c-18f9-5e33-a70a-4af3491063d7', NULL, 16, 16, 'Shave your heads, and cut off your hair for the children of your delight. Enlarge your baldness like the vulture; for they have gone into captivity from you!'),
  ('43835c54-4297-52a7-ae03-dba3499d99b2', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 1, 1, 'Woe to those who devise iniquity and work evil on their beds! When the morning is light, they practice it, because it is in the power of their hand.'),
  ('8929b34b-4b36-566c-abcc-f6d67756ca7b', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 2, 2, 'They covet fields, and seize them; and houses, and take them away: and they oppress a man and his house, even a man and his heritage.'),
  ('5cfee241-0be5-5370-a3dc-e858d36a2a23', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 3, 3, 'Therefore thus says Yahweh: "Behold, I am planning against these people a disaster, from which you will not remove your necks, neither will you walk haughtily; for it is an evil time.'),
  ('5e1ed180-053e-5cea-af1f-afd4c04f5cfb', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 4, 4, 'In that day they will take up a parable against you, and lament with a doleful lamentation, saying, ''We are utterly ruined! My people''s possession is divided up. Indeed he takes it from me and assigns our fields to traitors!''"'),
  ('d1a05637-3a87-54fd-a2a1-f7d897c392d4', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 5, 5, 'Therefore you will have no one who divides the land by lot in the assembly of Yahweh.'),
  ('32872433-4c4a-525b-aa8a-788ddc689db2', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 6, 6, '"Don''t prophesy!" They prophesy. "Don''t prophesy about these things. Disgrace won''t overtake us."'),
  ('465894c1-ccdc-5725-a6cd-bdef9c4fcb55', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 7, 7, 'Shall it be said, O house of Jacob: "Is the Spirit of Yahweh angry? Are these his doings? Don''t my words do good to him who walks blamelessly?"'),
  ('3af9caa7-18fa-5ae7-aebc-448fbddace25', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 8, 8, 'But lately my people have risen up as an enemy. You strip the robe and clothing from those who pass by without a care, returning from battle.'),
  ('59ffa957-d7cc-5188-ac29-8ce95bc540d6', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 9, 9, 'You drive the women of my people out from their pleasant houses; from their young children you take away my blessing forever.'),
  ('f7b5c9ab-3f71-5635-a043-cf9ada48b22a', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 10, 10, 'Arise, and depart! For this is not your resting place, because of uncleanness that destroys, even with a grievous destruction.'),
  ('57d7f8e1-04c5-5958-a036-27c06140274c', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 11, 11, 'If a man walking in a spirit of falsehood lies: "I will prophesy to you of wine and of strong drink;" he would be the prophet of this people.'),
  ('65eeeb53-63a9-5802-af0b-23cffc3357aa', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 12, 12, 'I will surely assemble, Jacob, all of you; I will surely gather the remnant of Israel; I will put them together as the sheep of Bozrah, as a flock in the midst of their pasture; they will swarm with people.'),
  ('65fe4c9c-ee28-5b71-acdd-f46c50c616b0', 'ce8e4d87-19cd-500e-a5c0-e8113db5571f', NULL, 13, 13, 'He who breaks open the way goes up before them. They break through the gate, and go out. And their king passes on before them, with Yahweh at their head.'),
  ('d93bf0ee-5d28-50c2-a521-67ed666cc2ee', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 1, 1, 'I said, "Please listen, you heads of Jacob, and rulers of the house of Israel: Isn''t it for you to know justice?'),
  ('86c6dabc-4733-5178-acea-8066cb01a2af', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 2, 2, 'You who hate the good, and love the evil; who tear off their skin, and their flesh from off their bones;')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f48682ca-50d7-54c4-adde-02660070d843', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 3, 3, 'who also eat the flesh of my people, and flay their skin from off them, and break their bones, and chop them in pieces, as for the pot, and as flesh within the caldron.'),
  ('305a51c5-4707-5295-ab73-b4df5af462f4', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 4, 4, 'Then they will cry to Yahweh, but he will not answer them. Yes, he will hide his face from them at that time, because they made their deeds evil."'),
  ('93e93115-af55-5f6e-a342-992676186708', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 5, 5, 'Thus says Yahweh concerning the prophets who lead my people astray; for those who feed their teeth, they proclaim, "Peace!" and whoever doesn''t provide for their mouths, they prepare war against him:'),
  ('4ad6df1e-d2ef-54ec-a241-5ca7b9769d0f', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 6, 6, '"Therefore night is over you, with no vision, and it is dark to you, that you may not divine; and the sun will go down on the prophets, and the day will be black over them.'),
  ('ba6887f1-5369-5288-a1e2-bebe62c86b1a', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 7, 7, 'The seers shall be disappointed, and the diviners confounded. Yes, they shall all cover their lips; for there is no answer from God."'),
  ('1748c0f9-c350-5032-a7e5-3951bd7520ba', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 8, 8, 'But as for me, I am full of power by the Spirit of Yahweh, and of judgment, and of might, to declare to Jacob his disobedience, and to Israel his sin.'),
  ('8bfe213b-b8b1-513d-aa25-8efbbb2c8640', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 9, 9, 'Please listen to this, you heads of the house of Jacob, and rulers of the house of Israel, who abhor justice, and pervert all equity.'),
  ('d4b6b4b4-7242-5b25-adb1-890b9af81ec0', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 10, 10, 'They build up Zion with blood, and Jerusalem with iniquity.'),
  ('6ee01228-1416-5bc7-a778-35892683d457', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 11, 11, 'Her leaders judge for bribes, and her priests teach for a price, and her prophets of it tell fortunes for money: yet they lean on Yahweh, and say, "Isn''t Yahweh in the midst of us? No disaster will come on us."'),
  ('760f7759-039b-5bc3-a710-5f16abccba02', '043d3787-bbb3-52b2-a969-36d8fe016c99', NULL, 12, 12, 'Therefore Zion for your sake will be plowed like a field, and Jerusalem will become heaps of rubble, and the mountain of the temple like the high places of a forest.'),
  ('841cda08-26f4-5895-a233-26add13b09b2', '682a801e-1697-572e-a700-21dc66159941', NULL, 1, 1, 'But in the latter days, it will happen that the mountain of Yahweh''s temple will be established on the top of the mountains, and it will be exalted above the hills; and peoples will stream to it.'),
  ('16ab8121-572b-51ad-af16-5e50912dd95f', '682a801e-1697-572e-a700-21dc66159941', NULL, 2, 2, 'Many nations will go and say, "Come, and let us go up to the mountain of Yahweh, and to the house of the God of Jacob; and he will teach us of his ways, and we will walk in his paths." For out of Zion will go forth the law, and the word of Yahweh from Jerusalem;'),
  ('7348d505-bab7-5255-a326-1c5a2c8969f8', '682a801e-1697-572e-a700-21dc66159941', NULL, 3, 3, 'and he will judge between many peoples, and will decide concerning strong nations afar off. They will beat their swords into plowshares, and their spears into pruning hooks. Nation will not lift up sword against nation, neither will they learn war any more.'),
  ('e00cf093-3ac4-5c55-ae27-7a4552ca1bf2', '682a801e-1697-572e-a700-21dc66159941', NULL, 4, 4, 'But they will sit every man under his vine and under his fig tree; and no one will make them afraid: For the mouth of Yahweh of Armies has spoken.'),
  ('bf79ab99-a289-57e9-a3ec-c527605dc2f6', '682a801e-1697-572e-a700-21dc66159941', NULL, 5, 5, 'Indeed all the nations may walk in the name of their gods; but we will walk in the name of Yahweh our God forever and ever.'),
  ('f7b1d84a-abd5-5cbc-a8d1-c08eab2f2592', '682a801e-1697-572e-a700-21dc66159941', NULL, 6, 6, '"In that day," says Yahweh, "I will assemble that which is lame, and I will gather that which is driven away, and that which I have afflicted;'),
  ('ec8d2897-33b1-59f3-ad82-d02a292f3f8c', '682a801e-1697-572e-a700-21dc66159941', NULL, 7, 7, 'and I will make that which was lame a remnant, and that which was cast far off a strong nation: and Yahweh will reign over them on Mount Zion from then on, even forever."'),
  ('6f1d4e52-2b2e-5a2c-aed4-4b600b8332a9', '682a801e-1697-572e-a700-21dc66159941', NULL, 8, 8, 'You, tower of the flock, the hill of the daughter of Zion, to you it will come, yes, the former dominion will come, the kingdom of the daughter of Jerusalem.'),
  ('8d9f84e8-f148-5f06-a6c5-d5a995388a03', '682a801e-1697-572e-a700-21dc66159941', NULL, 9, 9, 'Now why do you cry out aloud? Is there no king in you? Has your counselor perished, that pains have taken hold of you as of a woman in travail?'),
  ('d60beaed-3d8b-5913-a8e8-08b6f9c548cc', '682a801e-1697-572e-a700-21dc66159941', NULL, 10, 10, 'Be in pain, and labor to bring forth, daughter of Zion, like a woman in travail; for now you will go forth out of the city, and will dwell in the field, and will come even to Babylon. There you will be rescued. There Yahweh will redeem you from the hand of your enemies.'),
  ('319159ed-6385-5e68-ab9e-f5062b0a9023', '682a801e-1697-572e-a700-21dc66159941', NULL, 11, 11, 'Now many nations have assembled against you, that say, "Let her be defiled, and let our eye gloat over Zion."'),
  ('5abf0c6d-6699-513a-a29c-cba6b20c02cc', '682a801e-1697-572e-a700-21dc66159941', NULL, 12, 12, 'But they don''t know the thoughts of Yahweh, neither do they understand his counsel; for he has gathered them like the sheaves to the threshing floor.'),
  ('cc2a756f-8644-5e28-a4f3-37e3388d91f9', '682a801e-1697-572e-a700-21dc66159941', NULL, 13, 13, 'Arise and thresh, daughter of Zion; for I will make your horn iron, and I will make your hoofs brass; and you will beat in pieces many peoples: and I will devote their gain to Yahweh, and their substance to the Lord of the whole earth.'),
  ('76a75e14-be36-5479-aecf-dbbea10a8471', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 1, 1, 'Now you shall gather yourself in troops, daughter of troops. He has laid siege against us. They will strike the judge of Israel with a rod on the cheek.'),
  ('589b9684-8713-551d-a5b1-31451fd6df3f', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 2, 2, 'But you, Bethlehem Ephrathah, being small among the clans of Judah, out of you one will come forth to me that is to be ruler in Israel; whose goings forth are from of old, from everlasting.'),
  ('b8b85862-7609-5913-a642-a6b70d4f12ad', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 3, 3, 'Therefore he will abandon them until the time that she who is in labor gives birth. Then the rest of his brothers will return to the children of Israel.'),
  ('3acf2105-d1c7-5d4b-aab0-7644266318a8', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 4, 4, 'He shall stand, and shall shepherd in the strength of Yahweh, in the majesty of the name of Yahweh his God: and they will live, for then he will be great to the ends of the earth.'),
  ('2dd5f7cb-41e8-5e09-af2d-ddbea674c448', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 5, 5, 'He will be our peace when Assyria invades our land, and when he marches through our fortresses, then we will raise against him seven shepherds, and eight leaders of men.'),
  ('8f39ee53-0bf2-5546-a771-86d665de7907', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 6, 6, 'They will rule the land of Assyria with the sword, and the land of Nimrod in its gates. He will deliver us from the Assyrian, when he invades our land, and when he marches within our border.'),
  ('a13bc112-f3ac-5a3c-ae55-a64b33a60174', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 7, 7, 'The remnant of Jacob will be in the midst of many peoples, like dew from Yahweh, like showers on the grass, that don''t wait for man, nor wait for the sons of men.'),
  ('1839b82d-8c55-55d2-ac0f-bcad3c578084', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 8, 8, 'The remnant of Jacob will be among the nations, in the midst of many peoples, like a lion among the animals of the forest, like a young lion among the flocks of sheep; who, if he goes through, treads down and tears in pieces, and there is no one to deliver.'),
  ('816fcf8e-cf5b-5530-ae16-8176ebf21ec5', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 9, 9, 'Let your hand be lifted up above your adversaries, and let all of your enemies be cut off.'),
  ('b8bb2680-847d-5ac3-adda-3f03a02a08b6', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 10, 10, '"It will happen in that day," says Yahweh, "That I will cut off your horses out of the midst of you, and will destroy your chariots.'),
  ('aa716661-0342-506c-af24-c41146aa28a1', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 11, 11, 'I will cut off the cities of your land, and will tear down all your strongholds.'),
  ('68b05a56-9b71-5d7a-afd8-12770925d57e', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 12, 12, 'I will destroy witchcraft from your hand; and you shall have no soothsayers.'),
  ('dfbe5062-791f-5dbb-a493-b39decb63281', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 13, 13, 'I will cut off your engraved images and your pillars out of your midst; and you shall no more worship the work of your hands.'),
  ('73862fbf-6b68-59aa-a9ee-d146944e8b57', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 14, 14, 'I will uproot your Asherim out of your midst; and I will destroy your cities.'),
  ('7fc7aa09-230a-5d62-a1e2-6c7445dbf184', 'e4783c71-5b48-56a9-ab5c-e320ecaff74b', NULL, 15, 15, 'I will execute vengeance in anger, and wrath on the nations that didn''t listen."'),
  ('2752ea6f-ffa3-5a6c-a806-a0952a476506', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 1, 1, 'Listen now to what Yahweh says: "Arise, plead your case before the mountains, and let the hills hear what you have to say.'),
  ('d0f17f26-0b46-5582-a9ef-287ce1fdbe6b', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 2, 2, 'Hear, you mountains, Yahweh''s controversy, and you enduring foundations of the earth; for Yahweh has a controversy with his people, and he will contend with Israel.'),
  ('00d619ed-0c5c-501c-a289-e7ccf9968f52', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 3, 3, 'My people, what have I done to you? How have I burdened you? Answer me!'),
  ('9d340f2c-92ca-53f3-ac73-3e9b0941be33', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 4, 4, 'For I brought you up out of the land of Egypt, and redeemed you out of the house of bondage. I sent before you Moses, Aaron, and Miriam.'),
  ('07dde231-7e33-5c30-a788-a93228268352', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 5, 5, 'My people, remember now what Balak king of Moab devised, and what Balaam the son of Beor answered him from Shittim to Gilgal, that you may know the righteous acts of Yahweh."'),
  ('92d420d4-e7d5-5198-ada5-8d64355c5afa', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 6, 6, 'How shall I come before Yahweh, and bow myself before the exalted God? Shall I come before him with burnt offerings, with calves a year old?'),
  ('afaf0dd9-96ba-53e8-ae48-3f47df7969cc', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 7, 7, 'Will Yahweh be pleased with thousands of rams? With tens of thousands of rivers of oil? Shall I give my firstborn for my disobedience? The fruit of my body for the sin of my soul?'),
  ('9ea98189-7657-52c6-a0b0-47eaf2e4b32e', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 8, 8, 'He has shown you, O man, what is good. What does Yahweh require of you, but to act justly, to love mercy, and to walk humbly with your God?'),
  ('4ad411c1-d2b4-50f7-a34f-1318f864ea70', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 9, 9, 'Yahweh''s voice calls to the city, and wisdom sees your name: "Listen to the rod, and he who appointed it.'),
  ('12b77e9f-713e-59be-adf9-b35899349d9e', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 10, 10, 'Are there yet treasures of wickedness in the house of the wicked, and a short ephah that is accursed?'),
  ('2c8f81f7-0930-5c5d-a6de-a5f02f98b817', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 11, 11, 'Shall I be pure with dishonest scales, and with a bag of deceitful weights?'),
  ('5de7904d-7d29-5533-a763-a20c8752c5db', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 12, 12, 'Her rich men are full of violence, her inhabitants speak lies, and their tongue is deceitful in their speech.'),
  ('45c130eb-61d4-5d13-a6ee-bfa8b42e4156', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 13, 13, 'Therefore I also have struck you with a grievous wound. I have made you desolate because of your sins.'),
  ('c1759828-59dd-52d1-ad71-847195f448de', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 14, 14, 'You shall eat, but not be satisfied. Your humiliation will be in your midst. You will store up, but not save; and that which you save I will give up to the sword.'),
  ('c66edbb0-5e01-5915-a4cc-9863f36b03a0', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 15, 15, 'You will sow, but won''t reap. You will tread the olives, but won''t anoint yourself with oil; and crush grapes, but won''t drink the wine.'),
  ('ddf63754-20d2-54f9-a25b-85abb2a40c19', '026e09d6-28d4-517d-a708-dc568cd44ac0', NULL, 16, 16, 'For the statutes of Omri are kept, and all the works of the house of Ahab. You walk in their counsels, that I may make you a ruin, and her inhabitants a hissing; And you will bear the reproach of my people."'),
  ('ea029ffe-7d60-5192-a3a4-d116376e3e75', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 1, 1, 'Misery is mine! Indeed, I am like one who gathers the summer fruits, as gleanings of the vineyard: There is no cluster of grapes to eat. My soul desires to eat the early fig.'),
  ('bd06446b-a861-5e2b-a2d6-f436701f22d1', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 2, 2, 'The godly man has perished out of the earth, and there is no one upright among men. They all lie in wait for blood; every man hunts his brother with a net.'),
  ('4de82957-6e71-587a-a09f-cf3dd496199e', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 3, 3, 'Their hands are on that which is evil to do it diligently. The ruler and judge ask for a bribe; and the powerful man dictates the evil desire of his soul. Thus they conspire together.'),
  ('3a509366-5272-5af3-a32a-c1205689b0b6', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 4, 4, 'The best of them is like a brier. The most upright is worse than a thorn hedge. The day of your watchmen, even your visitation, has come; now is the time of their confusion.'),
  ('6de5c402-0773-5337-a893-1f49d02adab4', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 5, 5, 'Don''t trust in a neighbor. Don''t put confidence in a friend. With the woman lying in your embrace, be careful of the words of your mouth!'),
  ('3a6a5931-1cd5-5f55-a041-c0c3e4e77295', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 6, 6, 'For the son dishonors the father, the daughter rises up against her mother, the daughter-in-law against her mother-in-law; a man''s enemies are the men of his own house.'),
  ('3504ef00-b6c8-55bb-a86d-1a80c8afa177', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 7, 7, 'But as for me, I will look to Yahweh. I will wait for the God of my salvation. My God will hear me.'),
  ('c4f2208b-2fc9-595b-a683-29f84c47db2f', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 8, 8, 'Don''t rejoice against me, my enemy. When I fall, I will arise. When I sit in darkness, Yahweh will be a light to me.'),
  ('a11cbc93-f849-5bef-a0e4-62415a5333bd', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 9, 9, 'I will bear the indignation of Yahweh, because I have sinned against him, until he pleads my case, and executes judgment for me. He will bring me forth to the light. I will see his righteousness.'),
  ('9235d165-388e-55b4-a03e-f4fbcd91de63', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 10, 10, 'Then my enemy will see it, and shame will cover her who said to me, where is Yahweh your God? Then my enemy will see me and will cover her shame. Now she will be trodden down like the mire of the streets.'),
  ('85e4caad-ddbb-5a0a-afda-b8d150286047', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 11, 11, 'A day to build your walls-- In that day, he will extend your boundary.'),
  ('5bbc0bf5-941c-501d-ab99-0bbf4b408667', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 12, 12, 'In that day they will come to you from Assyria and the cities of Egypt, and from Egypt even to the River, and from sea to sea, and mountain to mountain.'),
  ('c6ad048c-16cb-5618-a2aa-e34af3df0281', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 13, 13, 'Yet the land will be desolate because of those who dwell therein, for the fruit of their doings.'),
  ('6e1167a2-fbe5-5aa4-a8d1-979da0c0f811', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 14, 14, 'Shepherd your people with your staff, the flock of your heritage, who dwell by themselves in a forest, in the midst of fertile pasture land, let them feed; in Bashan and Gilead, as in the days of old.'),
  ('d1707f38-afe9-5e80-a3c1-29334d660a68', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 15, 15, '"As in the days of your coming forth out of the land of Egypt, I will show them marvelous things."'),
  ('3a9469d3-4ec8-595c-acaf-3ffe4d0d4d59', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 16, 16, 'The nations will see and be ashamed of all their might. They will lay their hand on their mouth. Their ears will be deaf.'),
  ('336dc509-a8d7-5fbd-a69f-0d28fc9cf090', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 17, 17, 'They will lick the dust like a serpent. Like crawling things of the earth they shall come trembling out of their dens. They will come with fear to Yahweh our God, and will be afraid because of you.'),
  ('9eff468c-9c4e-5370-a472-f353f32507c8', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 18, 18, 'Who is a God like you, who pardons iniquity, and passes over the disobedience of the remnant of his heritage? He doesn''t retain his anger forever, because he delights in loving kindness.'),
  ('b8acfce1-26e0-59a9-a1ff-7c9478ab11f2', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 19, 19, 'He will again have compassion on us. He will tread our iniquities under foot; and you will cast all their sins into the depths of the sea.'),
  ('a213ffd5-16b2-583a-af50-8e42696eabc3', 'f394a000-d871-514c-a5dd-dbd3c7d9217f', NULL, 20, 20, 'You will give truth to Jacob, and mercy to Abraham, as you have sworn to our fathers from the days of old.'),
  ('7e55b630-51a6-55c2-af79-f161d8eca200', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 1, 1, 'An oracle about Nineveh. The book of the vision of Nahum the Elkoshite.'),
  ('c3988c8d-4787-5bdf-a1ef-a874d9024e7d', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 2, 2, 'Yahweh is a jealous God and avenges. Yahweh avenges and is full of wrath. Yahweh takes vengeance on his adversaries, and he maintains wrath against his enemies.'),
  ('441540d0-d7da-51af-a92d-bc3208f718aa', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 3, 3, 'Yahweh is slow to anger, and great in power, and will by no means leave the guilty unpunished. Yahweh has his way in the whirlwind and in the storm, and the clouds are the dust of his feet.'),
  ('6595be67-d785-52ee-a34f-87cc82674362', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 4, 4, 'He rebukes the sea, and makes it dry, and dries up all the rivers. Bashan languishes, and Carmel; and the flower of Lebanon languishes.'),
  ('d589fc7e-aa43-5552-a590-1db9e78fada9', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 5, 5, 'The mountains quake before him, and the hills melt away. The earth trembles at his presence, yes, the world, and all who dwell in it.'),
  ('b135a147-1bd9-5bf7-a426-77ec21ae6d34', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 6, 6, 'Who can stand before his indignation? Who can endure the fierceness of his anger? His wrath is poured out like fire, and the rocks are broken apart by him.'),
  ('84e073b9-da0a-5066-ab59-7b85b7527bc3', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 7, 7, 'Yahweh is good, a stronghold in the day of trouble; and he knows those who take refuge in him.'),
  ('9f1b43d2-5252-50e3-a551-89da94eaad4b', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 8, 8, 'But with an overflowing flood, he will make a full end of her place, and will pursue his enemies into darkness.'),
  ('1e6ca3e6-3ee2-5020-a0fc-313c23ed995c', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 9, 9, 'What do you plot against Yahweh? He will make a full end. Affliction won''t rise up the second time.'),
  ('3cfc474b-43ff-50ea-ab07-4518926164c2', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 10, 10, 'For entangled like thorns, and drunken as with their drink, they are consumed utterly like dry stubble.'),
  ('feb232ce-43e1-5cfb-ab9b-eb6a097d3f4b', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 11, 11, 'There is one gone forth out of you, who devises evil against Yahweh, who counsels wickedness.'),
  ('0b9d9a47-af75-5d1d-a648-9cb2fb74ebc2', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 12, 12, 'Thus says Yahweh: "Though they be in full strength, and likewise many, even so they will be cut down, and he shall pass away. Though I have afflicted you, I will afflict you no more.'),
  ('634639d6-91f8-5527-a1dd-d94da53a3f11', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 13, 13, 'Now will I break his yoke from off you, and will burst your bonds apart."'),
  ('4cd3c39d-b5da-5458-a951-4ce4e85b6070', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 14, 14, 'Yahweh has commanded concerning you: "No more descendants will bear your name. Out of the house of your gods, will I cut off the engraved image and the molten image. I will make your grave, for you are vile."'),
  ('81d8c6df-0c01-51ca-ada0-281042422a4d', '779c4449-4860-536b-a575-804a99bc46a5', NULL, 15, 15, 'Behold, on the mountains the feet of him who brings good news, who publishes peace! Keep your feasts, Judah! Perform your vows, for the wicked one will no more pass through you. He is utterly cut off.'),
  ('9a976a55-8d67-5e5f-a544-09e007a0d8e2', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 1, 1, 'He who dashes in pieces has come up against you. Keep the fortress! Watch the way! Strengthen your waist! Fortify your power mightily!'),
  ('0045cad8-458a-5d7f-ac4e-c38a983f7ef8', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 2, 2, 'For Yahweh restores the excellency of Jacob, as the excellency of Israel; for the destroyers have destroyed them, and ruined their vine branches.'),
  ('60d34393-bceb-5530-abc0-f9b357060a2c', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 3, 3, 'The shield of his mighty men is made red. The valiant men are in scarlet. The chariots flash with steel in the day of his preparation, and the pine spears are brandished.'),
  ('efa1a585-9a46-55a2-a0dc-846c447c3ad6', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 4, 4, 'The chariots rage in the streets. They rush back and forth in the broad ways. Their appearance is like torches. They run like the lightnings.'),
  ('4ba73e4d-7ae0-5631-ab72-b5700cabad07', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 5, 5, 'He summons his picked troops. They stumble on their way. They dash to its wall, and the protective shield is put in place.'),
  ('b74368d1-95dc-58c5-abc2-e274f081e04c', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 6, 6, 'The gates of the rivers are opened, and the palace is dissolved.'),
  ('0432d4ee-d737-5b1a-a7b3-96265b912719', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 7, 7, 'It is decreed: she is uncovered, she is carried away; and her handmaids moan as with the voice of doves, beating on their breasts.'),
  ('628538a5-966d-509f-a624-70d4a50192ef', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 8, 8, 'But Nineveh has been from of old like a pool of water, yet they flee away. "Stop! Stop!" they cry, but no one looks back.'),
  ('7387bc1e-2c1c-5d26-a7af-f299d9343bc7', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 9, 9, 'Take the spoil of silver. Take the spoil of gold, for there is no end of the store, the glory of all goodly furniture.'),
  ('450216af-2526-553e-aa8b-cb452024c306', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 10, 10, 'She is empty, void, and waste. The heart melts, the knees knock together, their bodies and faces have grown pale.'),
  ('61989c44-3ba1-5dc0-a5fe-35a76b20ac9f', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 11, 11, 'Where is the den of the lions, and the feeding place of the young lions, where the lion and the lioness walked, the lion''s cubs, and no one made them afraid?'),
  ('d35a011e-5757-56bd-ab3d-412e09f07171', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 12, 12, 'The lion tore in pieces enough for his cubs, and strangled for his lionesses, and filled his caves with the kill, and his dens with prey.'),
  ('0ec25346-a523-55cd-ad44-6512a279879b', 'aa3ac615-bf84-5b89-a4aa-691e658bed6e', NULL, 13, 13, '"Behold, I am against you," says Yahweh of Armies, "and I will burn her chariots in the smoke, and the sword will devour your young lions; and I will cut off your prey from the earth, and the voice of your messengers will no longer be heard."'),
  ('7bb81b41-bd2d-5b65-ad32-0f3c84863a53', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 1, 1, 'Woe to the bloody city! It is all full of lies and robbery. The prey doesn''t depart.'),
  ('6157f5b3-13d9-5876-aa59-d5c32dd0f5ac', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 2, 2, 'The noise of the whip, the noise of the rattling of wheels, prancing horses, and bounding chariots,'),
  ('9741fb1f-ba81-55c0-a4fb-10a55320376b', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 3, 3, 'the horseman mounting, and the flashing sword, the glittering spear, and a multitude of slain, and a great heap of corpses, and there is no end of the bodies. They stumble on their bodies,'),
  ('89e63238-bb87-5bba-acdd-fc1f87692da4', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 4, 4, 'because of the multitude of the prostitution of the alluring prostitute, the mistress of witchcraft, who sells nations through her prostitution, and families through her witchcraft.'),
  ('82cac2dd-06f9-5e02-a375-5015552c8339', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 5, 5, '"Behold, I am against you," says Yahweh of Armies, "and I will lift your skirts over your face. I will show the nations your nakedness, and the kingdoms your shame.'),
  ('b8fabfbe-5ae9-5276-a870-55132ca44981', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 6, 6, 'I will throw abominable filth on you, and make you vile, and will set you a spectacle.'),
  ('b10707e8-5288-5b3d-a58a-ee96d97f9e56', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 7, 7, 'It will happen that all those who look at you will flee from you, and say, ''Nineveh is laid waste! Who will mourn for her?'' Where will I seek comforters for you?"'),
  ('fa500d73-ae20-5a72-a76d-d0e06c0bb2d3', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 8, 8, 'Are you better than No-Amon, who was situated among the rivers, who had the waters around her; whose rampart was the sea, and her wall was of the sea?'),
  ('779ae04e-c6a0-51b2-ad6e-d206498af02a', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 9, 9, 'Cush and Egypt were her boundless strength. Put and Libya were her helpers.'),
  ('ca54a905-a92b-5e3a-a290-ada783319769', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 10, 10, 'Yet was she carried away. She went into captivity. Her young children also were dashed in pieces at the head of all the streets, and they cast lots for her honorable men, and all her great men were bound in chains.'),
  ('5b920f98-3949-5c80-ab4b-8725ecc4072e', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 11, 11, 'You also will be drunken. You will be hidden. You also will seek a stronghold because of the enemy.'),
  ('2ac01ac2-df03-556b-a7e4-2a73dc1286a6', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 12, 12, 'All your fortresses will be like fig trees with the first-ripe figs: if they are shaken, they fall into the mouth of the eater.'),
  ('c59db2c5-65a3-5a34-a846-90b7b6cc477e', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 13, 13, 'Behold, your troops in your midst are women. The gates of your land are set wide open to your enemies. The fire has devoured your bars.'),
  ('57f5e2bd-af1c-5513-ad98-731c7b603051', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 14, 14, 'Draw water for the siege. Strengthen your fortresses. Go into the clay, and tread the mortar. Make the brick kiln strong.'),
  ('1d51538a-2819-54a9-a3d9-f708409bac5e', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 15, 15, 'There the fire will devour you. The sword will cut you off. It will devour you like the grasshopper. Multiply like grasshoppers. Multiply like the locust.'),
  ('7cab913f-5d8c-5e29-a925-88e85d7293cf', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 16, 16, 'You have increased your merchants more than the stars of the skies. The grasshopper strips, and flees away.'),
  ('cf462b5f-e671-5b8a-a951-1fbf71f58540', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 17, 17, 'Your guards are like the locusts, and your officials like the swarms of locusts, which settle on the walls on a cold day, but when the sun appears, they flee away, and their place is not known where they are.'),
  ('83236cff-d1eb-5dff-a4d9-e90a1b09d750', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 18, 18, 'Your shepherds slumber, king of Assyria. Your nobles lie down. Your people are scattered on the mountains, and there is no one to gather them.'),
  ('5cffc624-4232-5502-af1a-e4c1638f2b3a', '76f6d37a-053e-58d6-a898-2ab9d640f0fe', NULL, 19, 19, 'There is no healing your wound, for your injury is fatal. All who hear the report of you clap their hands over you; for who hasn''t felt your endless cruelty?'),
  ('edb9cb01-7661-5187-aa2f-500666109853', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 1, 1, 'The oracle which Habakkuk the prophet saw.'),
  ('0c2d7867-7873-5b51-a68f-48c6289673c6', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 2, 2, 'Yahweh, how long will I cry, and you will not hear? I cry out to you "Violence!" and will you not save?'),
  ('fcb2d483-70c6-564b-ac48-5a0d8651d20e', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 3, 3, 'Why do you show me iniquity, and look at perversity? For destruction and violence are before me. There is strife, and contention rises up.'),
  ('8b016853-cf33-5972-ab8e-2db03ae2521b', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 4, 4, 'Therefore the law is paralyzed, and justice never goes forth; for the wicked surround the righteous; therefore justice goes forth perverted.'),
  ('6eb86d04-bf15-5732-a200-34a9efefe637', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 5, 5, '"Look among the nations, watch, and wonder marvelously; for I am working a work in your days, which you will not believe though it is told you.'),
  ('3f4bafb8-58ba-501a-a152-d75d960644a5', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 6, 6, 'For, behold, I raise up the Chaldeans, that bitter and hasty nation, that march through the breadth of the earth, to possess dwelling places that are not theirs.'),
  ('bf9c20f5-04d4-50e2-ac32-d75064a8e744', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 7, 7, 'They are feared and dreaded. Their judgment and their dignity proceed from themselves.'),
  ('ab5e5859-e019-50e4-a1cd-ca7903cb30aa', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 8, 8, 'Their horses also are swifter than leopards, and are more fierce than the evening wolves. Their horsemen press proudly on. Yes, their horsemen come from afar. They fly as an eagle that hurries to devour.'),
  ('2847c41c-deb9-5dcc-a33f-a4a212977975', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 9, 9, 'All of them come for violence. Their hordes face the desert. He gathers prisoners like sand.'),
  ('d32c9434-104d-5fcf-a1da-6c8edbafefb9', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 10, 10, 'Yes, he scoffs at kings, and princes are a derision to him. He laughs at every stronghold, for he builds up an earthen ramp, and takes it.'),
  ('ae071583-724d-525d-a224-8799f306e4ac', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 11, 11, 'Then he sweeps by like the wind, and goes on. He is indeed guilty, whose strength is his god."'),
  ('3ca0aae0-20fa-57f9-ab47-152617451bbe', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 12, 12, 'Aren''t you from everlasting, Yahweh my God, my Holy One? We will not die. Yahweh, you have appointed him for judgment. You, Rock, have established him to punish.'),
  ('77cb6d66-635b-547d-a48a-8dc56bc14477', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 13, 13, 'You who have purer eyes than to see evil, and who cannot look on perversity, why do you tolerate those who deal treacherously, and keep silent when the wicked swallows up the man who is more righteous than he,'),
  ('fb4c00c3-cd87-56ee-a42b-d3a47cec62a6', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 14, 14, 'and make men like the fish of the sea, like the creeping things, that have no ruler over them?'),
  ('cb4d7650-6c92-5986-a89b-afae06255d8d', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 15, 15, 'He takes up all of them with the hook. He catches them in his net, and gathers them in his dragnet. Therefore he rejoices and is glad.'),
  ('8ec255c3-87d4-5f0b-aefd-c1e2bad4b039', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 16, 16, 'Therefore he sacrifices to his net, and burns incense to his dragnet, because by them his life is luxurious, and his food is good.'),
  ('a2803dbb-e238-5a90-add0-7142908cb6b4', '985894ec-7b5f-5187-ab5b-315b669a6a3c', NULL, 17, 17, 'Will he therefore continually empty his net, and kill the nations without mercy?'),
  ('35ec3233-cc6b-5d57-a570-9f53ebdecc9a', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 1, 1, 'I will stand at my watch, and set myself on the ramparts, and will look out to see what he will say to me, and what I will answer concerning my complaint.'),
  ('1bf7ad8a-c5f1-54df-aebd-3c49c586d3a3', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 2, 2, 'Yahweh answered me, "Write the vision, and make it plain on tablets, that he who runs may read it.'),
  ('c1fcdc54-a143-5bb4-a37d-6805df776ac5', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 3, 3, 'For the vision is yet for the appointed time, and it hurries toward the end, and won''t prove false. Though it takes time, wait for it; because it will surely come. It won''t delay.'),
  ('119908a6-61cc-579d-a40c-2861d6566273', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 4, 4, 'Behold, his soul is puffed up. It is not upright in him, but the righteous will live by his faith.'),
  ('dffb8d0b-78bf-5f9b-a416-10535df39168', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 5, 5, 'Yes, moreover, wine is treacherous. A haughty man who doesn''t stay at home, who enlarges his desire as Sheol, and he is like death, and can''t be satisfied, but gathers to himself all nations, and heaps to himself all peoples.'),
  ('ba18521f-010f-5d02-a1b6-c7a62c376e86', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 6, 6, 'Won''t all these take up a parable against him, and a taunting proverb against him, and say, ''Woe to him who increases that which is not his, and who enriches himself by extortion! How long?'''),
  ('5e4a7c28-da0d-585f-a4c4-f7916b7f74d8', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 7, 7, 'Won''t your debtors rise up suddenly, and wake up those who make you tremble, and you will be their victim?'),
  ('3b3c2119-7452-5460-a652-340196ab56d1', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 8, 8, 'Because you have plundered many nations, all the remnant of the peoples will plunder you, because of men''s blood, and for the violence done to the land, to the city and to all who dwell in it.'),
  ('454326be-1fff-56ab-abb9-91138b4a5442', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 9, 9, 'Woe to him who gets an evil gain for his house, that he may set his nest on high, that he may be delivered from the hand of evil!'),
  ('c6c04926-b5a4-5e1a-ab52-dd836e853883', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 10, 10, 'You have devised shame to your house, by cutting off many peoples, and have sinned against your soul.'),
  ('44f7c113-105e-5ef3-ac0b-64c4cde6ab70', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 11, 11, 'For the stone will cry out of the wall, and the beam out of the woodwork will answer it.'),
  ('161b579b-f7d1-5899-a36d-3c9c72112f82', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 12, 12, 'Woe to him who builds a town with blood, and establishes a city by iniquity!'),
  ('fc6b7817-73ba-52c5-aaa4-37df489da09f', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 13, 13, 'Behold, isn''t it of Yahweh of Armies that the peoples labor for the fire, and the nations weary themselves for vanity?'),
  ('b10a6125-56a3-56f2-a392-1d89ada67b80', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 14, 14, 'For the earth will be filled with the knowledge of the glory of Yahweh, as the waters cover the sea.'),
  ('6dbc49ba-7aa8-5d95-aac5-bfad72fa3354', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 15, 15, '"Woe to him who gives his neighbor drink, pouring your inflaming wine until they are drunk, so that you may gaze at their naked bodies!'),
  ('fd3d9514-498b-5e61-aae2-7b57695ce383', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 16, 16, 'You are filled with shame, and not glory. You will also drink, and be exposed! The cup of Yahweh''s right hand will come around to you, and disgrace will cover your glory.'),
  ('6d492cb4-da1c-56c7-ac9c-a8caac1a2234', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 17, 17, 'For the violence done to Lebanon will overwhelm you, and the destruction of the animals, which made them afraid; because of men''s blood, and for the violence done to the land, to every city and to those who dwell in them.'),
  ('5db02c6c-b9c7-58a5-a733-1a3300e23b79', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 18, 18, '"What value does the engraved image have, that its maker has engraved it; the molten image, even the teacher of lies, that he who fashions its form trusts in it, to make mute idols?'),
  ('8ce9b56a-c751-5c23-af30-f8f3b455b027', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 19, 19, 'Woe to him who says to the wood, ''Awake!'' or to the mute stone, ''Arise!'' Shall this teach? Behold, it is overlaid with gold and silver, and there is no breath at all in its midst.'),
  ('9e1d8728-2cc4-5780-a581-dffa1425f3d2', 'dfac0d7d-3a28-5201-ac07-fe203b176fb2', NULL, 20, 20, 'But Yahweh is in his holy temple. Let all the earth be silent before him!"'),
  ('b525706b-879a-568e-a609-c35f2533e369', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 1, 1, 'A prayer of Habakkuk, the prophet, set to victorious music.'),
  ('897ceb07-aa33-57ec-ae14-a3e8ec50cb64', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 2, 2, 'Yahweh, I have heard of your fame. I stand in awe of your deeds, Yahweh. Renew your work in the midst of the years. In the midst of the years make it known. In wrath, you remember mercy.'),
  ('388d7ae5-7049-5f9b-a251-cbeab3710c9a', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 3, 3, 'God came from Teman, the Holy One from Mount Paran. Selah. His glory covered the heavens, and his praise filled the earth.'),
  ('104535ab-117a-5ea6-a422-b813499019f9', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 4, 4, 'His splendor is like the sunrise. Rays shine from his hand, where his power is hidden.'),
  ('efe8ae5e-9764-5690-aac4-bc6a3901b195', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 5, 5, 'Plague went before him, and pestilence followed his feet.'),
  ('c19d7c15-f662-54f4-ab7e-48041e754a8b', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 6, 6, 'He stood, and shook the earth. He looked, and made the nations tremble. The ancient mountains were crumbled. The age-old hills collapsed. His ways are eternal.'),
  ('78bc735a-ea4c-5d5c-a5f5-a9554f06e7a1', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 7, 7, 'I saw the tents of Cushan in affliction. The dwellings of the land of Midian trembled.'),
  ('357cd3d9-911f-5fdd-aced-5ef6650eff6f', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 8, 8, 'Was Yahweh displeased with the rivers? Was your anger against the rivers, or your wrath against the sea, that you rode on your horses, on your chariots of salvation?'),
  ('7fe41a2f-3369-5093-a106-26d0579d1c9d', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 9, 9, 'You uncovered your bow. You called for your sworn arrows. Selah. You split the earth with rivers.'),
  ('d062e371-8e38-5e2a-a96e-1a69ad8724dc', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 10, 10, 'The mountains saw you, and were afraid. The storm of waters passed by. The deep roared and lifted up its hands on high.'),
  ('9decfbdf-1d1a-553d-a342-09f59a6a998f', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 11, 11, 'The sun and moon stood still in the sky, at the light of your arrows as they went, at the shining of your glittering spear.'),
  ('c7dc07da-d072-50f1-a74c-cf021b797bd2', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 12, 12, 'You marched through the land in wrath. You threshed the nations in anger.'),
  ('ac9ecc08-9ec5-5ff3-a228-0c304e53fb4b', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 13, 13, 'You went forth for the salvation of your people, for the salvation of your anointed. You crushed the head of the land of wickedness. You stripped them head to foot. Selah.'),
  ('c92798ac-eaa2-5c04-acda-866f4c3a6982', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 14, 14, 'You pierced the heads of his warriors with their own spears. They came as a whirlwind to scatter me, gloating as if to devour the wretched in secret.'),
  ('862e5ffd-1d01-57fb-a394-81e60a976f7b', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 15, 15, 'You trampled the sea with your horses, churning mighty waters.'),
  ('12a6a45b-6b5a-569b-a762-969b69ac48cc', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 16, 16, 'I heard, and my body trembled. My lips quivered at the voice. Rottenness enters into my bones, and I tremble in my place, because I must wait quietly for the day of trouble, for the coming up of the people who invade us.'),
  ('62eca246-43a6-58f2-ad2f-0d782be6e43b', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 17, 17, 'For though the fig tree doesn''t flourish, nor fruit be in the vines; the labor of the olive fails, the fields yield no food; the flocks are cut off from the fold, and there is no herd in the stalls:'),
  ('75b3fc23-239d-548c-a1f5-59e231cf6dc4', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 18, 18, 'yet I will rejoice in Yahweh. I will be joyful in the God of my salvation!'),
  ('f133c61a-d1f1-590a-a205-c7cb71e79112', '3749e96b-5f3d-50c9-ad3a-7a9deda4620b', NULL, 19, 19, 'Yahweh, the Lord, is my strength. He makes my feet like deer''s feet, and enables me to go in high places. For the music director, on my stringed instruments.'),
  ('16e95360-b8b7-561d-adb2-9b40097f5eb4', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 1, 1, 'The word of Yahweh which came to Zephaniah, the son of Cushi, the son of Gedaliah, the son of Amariah, the son of Hezekiah, in the days of Josiah, the son of Amon, king of Judah.'),
  ('d5836e4f-1c12-5222-a9d8-8dfbf7598291', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 2, 2, 'I will utterly sweep away everything off of the surface of the earth, says Yahweh.'),
  ('b3fa1a6f-e44f-5c45-ac35-37e3ead240fa', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 3, 3, 'I will sweep away man and animal. I will sweep away the birds of the sky, the fish of the sea, and the heaps of rubble with the wicked. I will cut off man from the surface of the earth, says Yahweh.'),
  ('5f4a9b26-cf2f-59ac-ab66-9121b535cee7', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 4, 4, 'I will stretch out my hand against Judah, and against all the inhabitants of Jerusalem. I will cut off the remnant of Baal from this place: the name of the idolatrous and pagan priests,'),
  ('3369e06e-0dda-5ed1-ae83-ee37da5d7523', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 5, 5, 'those who worship the army of the sky on the housetops, those who worship and swear by Yahweh and also swear by Malcam,'),
  ('1757381c-0761-5779-aaac-6f3a4a5d428f', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 6, 6, 'those who have turned back from following Yahweh, and those who haven''t sought Yahweh nor inquired after him.'),
  ('fa890eed-3a11-5502-aa87-6cabe90cb95b', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 7, 7, 'Be silent at the presence of the Lord Yahweh, for the day of Yahweh is at hand. For Yahweh has prepared a sacrifice. He has consecrated his guests.'),
  ('6d4dcdf5-1423-5936-af56-ea4930315c25', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 8, 8, 'It will happen in the day of Yahweh''s sacrifice, that I will punish the princes, the king''s sons, and all those who are clothed with foreign clothing.'),
  ('5e203c2b-4344-5aab-af29-d7aa48a59b10', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 9, 9, 'In that day, I will punish all those who leap over the threshold, who fill their master''s house with violence and deceit.'),
  ('4bddc904-0720-529a-a1de-f16f9c0e9b45', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 10, 10, 'In that day, says Yahweh, there will be the noise of a cry from the fish gate, a wailing from the second quarter, and a great crashing from the hills.'),
  ('c1343169-d7a8-54b0-ae95-fa2fea1c7175', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 11, 11, 'Wail, you inhabitants of Maktesh, for all the people of Canaan are undone! All those who were loaded with silver are cut off.'),
  ('8c9f6e65-6a99-5874-a130-ae05da7ab4ab', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 12, 12, 'It will happen at that time, that I will search Jerusalem with lamps, and I will punish the men who are settled on their dregs, who say in their heart, "Yahweh will not do good, neither will he do evil."'),
  ('3c39cacd-a98a-573c-a961-16280cacf48c', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 13, 13, 'Their wealth will become a spoil, and their houses a desolation. Yes, they will build houses, but won''t inhabit them. They will plant vineyards, but won''t drink their wine.'),
  ('ad58cf56-755d-5e57-aeff-ca22b3e23731', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 14, 14, 'The great day of Yahweh is near. It is near, and hurries greatly, the voice of the day of Yahweh. The mighty man cries there bitterly.'),
  ('09f837c0-00ab-5ce2-a1e8-edc93f0e7c3a', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 15, 15, 'That day is a day of wrath, a day of distress and anguish, a day of trouble and ruin, a day of darkness and gloom, a day of clouds and blackness,'),
  ('16a4efa6-0530-5445-a060-bd4297157a83', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 16, 16, 'a day of the trumpet and alarm, against the fortified cities, and against the high battlements.'),
  ('e398f3a5-a3d6-5fe1-a67a-c8a5b8991cb6', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 17, 17, 'I will bring distress on men, that they will walk like blind men, because they have sinned against Yahweh, and their blood will be poured out like dust, and their flesh like dung.'),
  ('a1d5c048-b4a3-503a-a751-d0123848398b', 'e08af117-46dd-5647-a977-a8cc3aa00552', NULL, 18, 18, 'Neither their silver nor their gold will be able to deliver them in the day of Yahweh''s wrath, but the whole land will be devoured by the fire of his jealousy; for he will make an end, yes, a terrible end, of all those who dwell in the land.'),
  ('954e44b6-8c49-529f-a3b3-879315946bbb', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 1, 1, 'Gather yourselves together, yes, gather together, you nation that has no shame,'),
  ('12223227-48c9-50db-a04d-f04d8c86d497', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 2, 2, 'before the appointed time when the day passes as the chaff, before the fierce anger of Yahweh comes on you, before the day of Yahweh''s anger comes on you.'),
  ('7243a754-044d-5654-aa71-31c6f5d8312d', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 3, 3, 'Seek Yahweh, all you humble of the land, who have kept his ordinances. Seek righteousness. Seek humility. It may be that you will be hidden in the day of Yahweh''s anger.'),
  ('2edc3328-af17-54ff-aef7-01abbf15c653', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 4, 4, 'For Gaza will be forsaken, and Ashkelon a desolation. They will drive out Ashdod at noonday, and Ekron will be rooted up.'),
  ('db019910-1f51-5d16-a042-4376d0e6fde6', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 5, 5, 'Woe to the inhabitants of the sea coast, the nation of the Cherethites! The word of Yahweh is against you, Canaan, the land of the Philistines. I will destroy you, that there will be no inhabitant.'),
  ('93843f38-9e15-55d2-af25-876f3faea9a9', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 6, 6, 'The sea coast will be pastures, with cottages for shepherds and folds for flocks.'),
  ('ff05e2bf-9880-5708-adf1-1474420b2f50', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 7, 7, 'The coast will be for the remnant of the house of Judah. They will find pasture. In the houses of Ashkelon, they will lie down in the evening, for Yahweh, their God, will visit them, and restore them.'),
  ('b98c4f34-f2ba-58bb-adbb-f8a77905a698', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 8, 8, 'I have heard the reproach of Moab, and the insults of the children of Ammon, with which they have reproached my people, and magnified themselves against their border.'),
  ('45171ff0-ffc3-5973-a785-d11fb4932290', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 9, 9, 'Therefore as I live, says Yahweh of Armies, the God of Israel, surely Moab will be as Sodom, and the children of Ammon as Gomorrah, a possession of nettles, and salt pits, and a perpetual desolation. The remnant of my people will plunder them, and the survivors of my nation will inherit them.'),
  ('9e4e4e67-41d1-5395-ab74-ad1709fc21a0', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 10, 10, 'This they will have for their pride, because they have reproached and magnified themselves against the people of Yahweh of Armies.'),
  ('23cbdddd-6103-5306-a4ce-350977823f90', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 11, 11, 'Yahweh will be awesome to them, for he will famish all the gods of the land. Men will worship him, everyone from his place, even all the shores of the nations.'),
  ('52d26765-247f-5d69-a07c-e9b6b938de66', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 12, 12, 'You Cushites also, you will be killed by my sword.'),
  ('606084be-2a63-51ef-afde-f133f25a1915', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 13, 13, 'He will stretch out his hand against the north, destroy Assyria, and will make Nineveh a desolation, as dry as the wilderness.'),
  ('76eff65a-d65a-5a58-a1f6-b804dadccc0a', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 14, 14, 'Herds will lie down in the midst of her, all the animals of the nations. Both the pelican and the porcupine will lodge in its capitals. Their calls will echo through the windows. Desolation will be in the thresholds, for he has laid bare the cedar beams.'),
  ('fd4a78a5-61c3-5095-aa3b-a720264ef8cc', '18832314-ebba-577f-abb4-70a123dd6600', NULL, 15, 15, 'This is the joyous city that lived carelessly, that said in her heart, "I am, and there is none besides me." How she has become a desolation, a place for animals to lie down in! Everyone who passes by her will hiss, and shake their fists.'),
  ('cd9f8741-b89e-5932-a912-d0e0dfc620d7', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 1, 1, 'Woe to her who is rebellious and polluted, the oppressing city!'),
  ('072bd3ae-34d0-569c-abd2-563bb2bf8a8e', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 2, 2, 'She didn''t obey the voice. She didn''t receive correction. She didn''t trust in Yahweh. She didn''t draw near to her God.'),
  ('f24fca4c-f955-5982-a0d8-42c0719a0eeb', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 3, 3, 'Her princes in the midst of her are roaring lions. Her judges are evening wolves. They leave nothing until the next day.'),
  ('4353864d-60da-5928-a7ef-355fea003b36', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 4, 4, 'Her prophets are arrogant and treacherous people. Her priests have profaned the sanctuary. They have done violence to the law.'),
  ('988af785-2964-5345-a3ac-e63580fe15f3', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 5, 5, 'Yahweh, in the midst of her, is righteous. He will do no wrong. Every morning he brings his justice to light. He doesn''t fail, but the unjust know no shame.'),
  ('33fce88b-883d-5618-a07d-64393f644d90', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 6, 6, 'I have cut off nations. Their battlements are desolate. I have made their streets waste, so that no one passes by. Their cities are destroyed, so that there is no man, so that there is no inhabitant.'),
  ('085caed0-04bc-50b9-ae31-f2236b37637d', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 7, 7, 'I said, "Just fear me. Receive correction, so that her dwelling won''t be cut off, according to all that I have appointed concerning her." But they rose early and corrupted all their doings.'),
  ('29263417-90c5-5bbd-acce-a2e37c2467f4', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 8, 8, '"Therefore wait for me," says Yahweh, "until the day that I rise up to the prey, for my determination is to gather the nations, that I may assemble the kingdoms, to pour on them my indignation, even all my fierce anger, for all the earth will be devoured with the fire of my jealousy.'),
  ('587d7573-c9d1-51ea-aa94-a7803a71245e', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 9, 9, 'For then I will purify the lips of the peoples, that they may all call on the name of Yahweh, to serve him shoulder to shoulder.'),
  ('244399b3-ca8f-5ee3-ad2e-7d35ec0a94d0', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 10, 10, 'From beyond the rivers of Cush, my worshipers, even the daughter of my dispersed people, will bring my offering.'),
  ('2beaa746-df7f-5128-a575-0d29eff82304', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 11, 11, 'In that day you will not be disappointed for all your doings, in which you have transgressed against me; for then I will take away out of the midst of you your proudly exulting ones, and you will no more be haughty in my holy mountain.'),
  ('0881e109-5fbd-5cde-a6a8-e9c11acb9fca', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 12, 12, 'But I will leave in the midst of you an afflicted and poor people, and they will take refuge in the name of Yahweh.'),
  ('afd0b9e3-625d-5b3b-a378-ed62c0b7fed3', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 13, 13, 'The remnant of Israel will not do iniquity, nor speak lies, neither will a deceitful tongue be found in their mouth, for they will feed and lie down, and no one will make them afraid."'),
  ('bd1c4d0e-3951-531b-ae77-793b070fa1c2', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 14, 14, 'Sing, daughter of Zion! Shout, Israel! Be glad and rejoice with all your heart, daughter of Jerusalem.'),
  ('646f3eb5-95c7-56e4-ab7c-95bf6ec9ab9a', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 15, 15, 'Yahweh has taken away your judgments. He has thrown out your enemy. The King of Israel, Yahweh, is in the midst of you. You will not be afraid of evil any more.'),
  ('2ddc13e1-07f0-56a0-a7cb-72612bdc498f', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 16, 16, 'In that day, it will be said to Jerusalem, "Don''t be afraid, Zion. Don''t let your hands be weak."'),
  ('2365669b-2b0a-579d-a812-990fd33f08b4', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 17, 17, 'Yahweh, your God, is in the midst of you, a mighty one who will save. He will rejoice over you with joy. He will calm you in his love. He will rejoice over you with singing.'),
  ('6438ed41-1711-5d4e-a9a7-2138d058ab1b', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 18, 18, 'I will remove those who grieve about the appointed feasts from you. They are a burden and a reproach to you.'),
  ('98dc785e-420c-54b3-a777-4eee61260e95', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 19, 19, 'Behold, at that time I will deal with all those who afflict you, and I will save those who are lame, and gather those who were driven away. I will give them praise and honor, whose shame has been in all the earth.'),
  ('a29b912a-34f4-53f2-ad9d-f13f41488634', '92bf6ca7-2ca7-5c85-ac97-e123d7ebc1f5', NULL, 20, 20, 'At that time will I bring you in, and at that time will I gather you; for I will give you honor and praise among all the peoples of the earth, when I restore your fortunes before your eyes, says Yahweh.'),
  ('4e3fa2a1-d4ae-50ea-ab9a-8b150384a75d', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 1, 1, 'In the second year of Darius the king, in the sixth month, in the first day of the month, the Word of Yahweh came by Haggai, the prophet, to Zerubbabel, the son of Shealtiel, governor of Judah, and to Joshua, the son of Jehozadak, the high priest, saying,'),
  ('9fda3e53-f714-5564-ae1a-e1fd7cc5d594', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 2, 2, '"This is what Yahweh of Armies says: These people say, ''The time hasn''t yet come, the time for Yahweh''s house to be built.''"'),
  ('ef2cb8c4-974b-58f8-ad81-fab60c40dacd', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 3, 3, 'Then the Word of Yahweh came by Haggai, the prophet, saying,'),
  ('560337d1-0dff-5904-a9b2-2daaf7527d8e', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 4, 4, '"Is it a time for you yourselves to dwell in your paneled houses, while this house lies waste?'),
  ('c45ff303-4248-5d0d-a067-3e63ee0909e3', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 5, 5, 'Now therefore this is what Yahweh of Armies says: Consider your ways.'),
  ('bccd6b93-91ff-59d0-ab3c-927789b3b231', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 6, 6, 'You have sown much, and bring in little. You eat, but you don''t have enough. You drink, but you aren''t filled with drink. You clothe yourselves, but no one is warm, and he who earns wages earns wages to put them into a bag with holes in it."'),
  ('c6c653d3-d3d2-5b26-ac76-964af0152e5f', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 7, 7, 'This is what Yahweh of Armies says: "Consider your ways.'),
  ('5f57f0d1-c8ff-5ab1-aa3b-971e2b57e60f', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 8, 8, 'Go up to the mountain, bring wood, and build the house. I will take pleasure in it, and I will be glorified," says Yahweh.'),
  ('6bdca619-560d-58e7-a892-d08a0ff96e99', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 9, 9, '"You looked for much, and, behold, it came to little; and when you brought it home, I blew it away. Why?" says Yahweh of Armies, "Because of my house that lies waste, while each of you is busy with his own house.'),
  ('343e1346-fd9b-5dc3-a8ce-22429fbe4ba9', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 10, 10, 'Therefore for your sake the heavens withhold the dew, and the earth withholds its fruit.'),
  ('ac358f5f-3e84-54c9-a462-bed40e39c661', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 11, 11, 'I called for a drought on the land, on the mountains, on the grain, on the new wine, on the oil, on that which the ground brings forth, on men, on livestock, and on all the labor of the hands."'),
  ('4b468062-7d2e-5c61-a411-4741e6494ca9', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 12, 12, 'Then Zerubbabel, the son of Shealtiel, and Joshua, the son of Jehozadak, the high priest, with all the remnant of the people, obeyed the voice of Yahweh, their God, and the words of Haggai, the prophet, as Yahweh, their God, had sent him; and the people feared Yahweh.'),
  ('4aab03e2-a0fc-593f-a21c-745141ce71e6', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 13, 13, 'Then Haggai, Yahweh''s messenger, spoke Yahweh''s message to the people, saying, "I am with you," says Yahweh.'),
  ('846bf91a-5383-5e9e-a552-6d06596758a4', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 14, 14, 'Yahweh stirred up the spirit of Zerubbabel, the son of Shealtiel, governor of Judah, and the spirit of Joshua, the son of Jehozadak, the high priest, and the spirit of all the remnant of the people; and they came and worked on the house of Yahweh of Armies, their God,'),
  ('a6eb150a-8491-533c-a42d-fcde5f1e25fe', 'fa11103e-fa21-5009-a900-dc27de818bcd', NULL, 15, 15, 'in the twenty-fourth day of the month, in the sixth month, in the second year of Darius the king.'),
  ('f721dfd0-c76d-5d8a-adc4-044d816c9ffb', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 1, 1, 'In the seventh month, in the twenty-first day of the month, the Word of Yahweh came by Haggai the prophet, saying,'),
  ('e2b0271c-7667-5e4c-a325-d47d1c039324', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 2, 2, '"Speak now to Zerubbabel, the son of Shealtiel, governor of Judah, and to Joshua, the son of Jehozadak, the high priest, and to the remnant of the people, saying,'),
  ('f848cee0-ada9-5a29-a43c-95c0eff8ff57', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 3, 3, '''Who is left among you who saw this house in its former glory? How do you see it now? Isn''t it in your eyes as nothing?'),
  ('2c6cd993-2721-5459-a0c3-242c9ba3ebe3', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 4, 4, 'Yet now be strong, Zerubbabel,'' says Yahweh. ''Be strong, Joshua, son of Jehozadak, the high priest. Be strong, all you people of the land,'' says Yahweh, ''and work, for I am with you,'' says Yahweh of Armies.'),
  ('e67b29de-467a-57cc-a590-8660c7c7fd73', 'fe13045d-ee4f-57d5-a200-7e89b2ccc57c', NULL, 5, 5, 'This is the word that I covenanted with you when you came out of Egypt, and my Spirit lived among you. ''Don''t be afraid.''')
